ger, useNotifications } from '../../hooks';\nimport DeleteAddressModal from './DeleteAddressModal';\nimport DisableAddressModal from './DisableAddressModal';\nimport { AddressPermissions } from './helper';\nimport CreateMissingKeysAddressModal from './missingKeys/CreateMissingKeysAddressModal';\n\ninterface Props {\n    address: Address;\n    member?: Member; // undefined if self\n    user: UserModel;\n    onSetDefault?: () => Promise<unknown>;\n    savingIndex?: number;\n    addressIndex?: number;\n    permissions: AddressPermissions;\n}\n\nconst useAddressFlagsActionsList = (address: Address, user: UserModel, member: Member | undefined) => {\n    const addressFlags = useAddressFlags(address);\n    const isPaidMail = user.hasPaidMail;\n    // Only allow on the user's own settings address list, not in org admin management panel.\n    // This still allows an admin logged in as sub-user to manage the preferences.\n    const isSelf = member === undefined || !!member.Self;\n    if (!addressFlags || !isPaidMail || !isSelf) {\n        return [];\n    }\n\n    const { allowDisablingEncryption, encryptionDisabled, expectSignatureDisabled, handleSetAddressFlags } =\n        addressFlags;\n\n    const actions = [];\n\n    if (!encryptionDisabled && allowDisablingEncryption) {\n        actions.push({\n            // translator: this is in a small space, so the string should be short, max 25 characters\n            text: c('Address action').t`Disable E2EE mail`,\n            onClick: () => handleSetAddressFlags(true, expectSignatureDisabled),\n        });\n    }\n\n    if (encryptionDisabled) {\n        actions.push({\n            // translator: this is in a small space, so the string should be short, max 25 characters\n            text: c('Address action').t`Enable E2EE mail`,\n            onClick: () => handleSetAddressFlags(false, expectSignatureDisabled),\n        });\n    }\n\n    if (expectSignatureDisabled) {\n        actions.push({\n            // translator: this is in a small space, so the string should be short, max 25 characters\n            text: c('Address action').t`Disallow unsigned mail`,\n            onClick: () => handleSetAddressFlags(encryptionDisabled, false),\n        });\n    }\n\n    return actions;\n};\n\nconst AddressActions = ({ address, member, user, onSetDefault, savingIndex, addressIndex, permissions }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n    const addressFlagsActionsList = useAddressFlagsActionsList(address, user, member);\n\n    const [missingKeysProps, setMissingKeysAddressModalOpen, renderMissingKeysModal] = useModalState();\n    const [deleteAddressProps, setDeleteAddressModalOpen, renderDeleteAddress] = useModalState();\n    const [disableAddressProps, setDisableAddressModalOpen, renderDisableAddress] = useModalState();\n    const [editInternalAddressProps, setEditInternalAddressOpen, renderEditInternalAddressModal] = useModalState();\n    const [editExternalAddressProps, setEditExternalAddressOpen, renderEditExternalAddressModal] = useModalState();\n\n    const handleDelete = async () => {\n        if (address.Status === ADDRESS_STATUS.STATUS_ENABLED) {\n            await api(disableAddress(address.ID));\n        }\n        await api(deleteAddress(address.ID));\n        await call();\n        createNotification({ text: c('Success notification').t`Address deleted` });\n    };\n\n    const handleEnable = async () => {\n        await api(enableAddress(address.ID));\n        await call();\n        createNotification({ text: c('Success notification').t`Address enabled` });\n    };\n\n    const handleDisable = async () => {\n        await api(disableAddress(address.ID));\n        await call();\n        createNotification({ text: c('Success notification').t`Address disabled` });\n    };\n\n    const list =\n        savingIndex !== undefined\n            ? [savingIndex === addressIndex ? { text: c('Address action').t`Saving` } : null].filter(isTruthy)\n            : [\n                  permissions.canGenerate && {\n                      text: c('Address action').t`Generate missing keys`,\n                      onClick: () => setMissingKeysAddressModalOpen(true),\n                  },\n                  permissions.canEditInternalAddress && {\n                      text: c('Address action').t`Edit`,\n                      onClick: () => setEditInternalAddressOpen(true),\n                  },\n                  permissions.canEditExternalAddress && {\n                      text: c('Address action').t`Edit address`,\n                      onClick: () => setEditExternalAddressOpen(true),\n                  },\n                  permissions.canMakeDefault &&\n                      onSetDefault && {\n                          text: c('Address action').t`Set as default`,\n                          onClick: () => onSetDefault(),\n                      },\n                  permissions.canEnable && {\n                      text: c('Address action').t`Enable`,\n                      onClick: () => withLoading(handleEnable()),\n                  },\n                  permissions.canDisable && {\n                      text: c('Address action').t`Disable`,\n                      onClick: () => setDisableAddressModalOpen(true),\n                  },\n                  permissions.canDelete &&\n                      ({\n                          text: c('Address action').t`Delete`,\n                          actionType: 'delete',\n                          onClick: () => setDeleteAddressModalOpen(true),\n                      } as const),\n                  ...addressFlagsActionsList,\n              ].filter(isTruthy);\n\n    return (\n        <>\n            {renderMissingKeysModal && (\n                <CreateMissingKeysAddressModal {...missingKeysProps} member={member} addressesToGenerate={[address]} />\n            )}\n            {renderEditInternalAddressModal && (\n                <EditInternalAddressModal address={address} {...editInternalAddressProps} />\n            )}\n            {renderEditExternalAddressModal && (\n                <EditExternalAddressModal address={address} {...editExternalAddressProps} />\n            )}\n            {renderDeleteAddress && (\n                <DeleteAddressModal email={address.Email} onDeleteAddress={handleDelete} {...deleteAddressProps} />\n            )}\n            {renderDisableAddress && (\n                <DisableAddressModal email={address.Email} onDisable={handleDisable} {...disableAddressProps} />\n            )}\n\n            {list.length ? (\n                <DropdownActions size=\"small\" list={list} loading={loading || savingIndex !== undefined} />\n            ) : (\n                <div\n                    // This is a placeholder to avoid height loss when dropdownActions are not rendered\n                    style={{ height: '24px' }}\n                />\n            )}\n        </>\n    );\n};\n\nexport default AddressActions;\n","import { c } from 'ttag';\n\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { Badge } from '../../components';\nimport { AddressStatuses } from './helper';\n\nconst AddressStatus = ({\n    isDefault,\n    isActive,\n    isDisabled,\n    isOrphan,\n    isMissingKeys,\n    isExternal,\n    isNotEncrypted,\n    isSignatureNotExpected,\n}: Partial<AddressStatuses>) => {\n    const list = [\n        isDefault &&\n            ({\n                text: c('Address status').t`Default`,\n                type: 'primary',\n            } as const),\n        isExternal &&\n            ({\n                text: c('Address status').t`External`,\n                type: 'info',\n            } as const),\n        isActive &&\n            ({\n                text: c('Address status').t`Active`,\n                type: 'success',\n            } as const),\n        isDisabled &&\n            ({\n                text: c('Address status').t`Disabled`,\n                type: 'light',\n            } as const),\n        isOrphan &&\n            ({\n                text: c('Address status').t`Orphan`,\n                type: 'origin',\n            } as const),\n        isMissingKeys &&\n            ({\n                text: c('Address status').t`Missing keys`,\n                type: 'warning',\n            } as const),\n        isNotEncrypted &&\n            ({\n                // translator: E2EE stands for end-to-end encryption. If possible, keep the abbreviation as the UI will be best with a short translated string.\n                text: c('Address status').t`No E2EE mail`,\n                type: 'error',\n            } as const),\n        isSignatureNotExpected &&\n            ({\n                text: c('Address status').t`Allow unsigned mail`,\n                type: 'error',\n            } as const),\n    ]\n        .filter(isTruthy)\n        .map(({ text, type }) => {\n            return (\n                <Badge key={text} type={type} className=\"mr-1 mb-1\">\n                    {text}\n                </Badge>\n            );\n        });\n\n    return <>{list}</>;\n};\nexport default AddressStatus;\n","import { c } from 'ttag';\n\nimport {\n    ADDRESS_FLAGS,\n    ADDRESS_PERMISSIONS,\n    ADDRESS_PERMISSION_TYPE,\n    ADDRESS_RECEIVE,\n    ADDRESS_STATUS,\n    ADDRESS_TYPE,\n    MEMBER_PRIVATE,\n    MEMBER_TYPE,\n} from '@proton/shared/lib/constants';\nimport { hasBit } from '@proton/shared/lib/helpers/bitset';\nimport {\n    Address,\n    AddressConfirmationState,\n    CachedOrganizationKey,\n    Member,\n    PartialMemberAddress,\n    UserModel,\n} from '@proton/shared/lib/interfaces';\nimport { getCanGenerateMemberAddressKeys } from '@proton/shared/lib/keys/memberKeys';\nimport { getIsNonDefault } from '@proton/shared/lib/mail/addresses';\n\nconst { TYPE_ORIGINAL, TYPE_CUSTOM_DOMAIN, TYPE_PREMIUM } = ADDRESS_TYPE;\n\nexport const getStatus = (address: Address, i: number) => {\n    const { Type, Status, Receive, DomainID, HasKeys, Flags } = address;\n\n    const isActive = Status === ADDRESS_STATUS.STATUS_ENABLED && Receive === ADDRESS_RECEIVE.RECEIVE_YES;\n    const isDisabled = Status === ADDRESS_STATUS.STATUS_DISABLED;\n    const isExternal = Type === ADDRESS_TYPE.TYPE_EXTERNAL;\n    const isOrphan = DomainID === null && !isExternal;\n    const isMissingKeys = !HasKeys;\n    const isNotEncrypted = hasBit(Flags, ADDRESS_FLAGS.FLAG_DISABLE_E2EE);\n    const isSignatureNotExpected = hasBit(Flags, ADDRESS_FLAGS.FLAG_DISABLE_EXPECTED_SIGNED);\n\n    return {\n        isDefault: i === 0,\n        isActive,\n        isExternal,\n        isDisabled,\n        isOrphan,\n        isMissingKeys,\n        isNotEncrypted,\n        isSignatureNotExpected,\n    };\n};\n\nexport const getPermissions = ({\n    member,\n    address,\n    addresses,\n    user,\n    organizationKey,\n    addressIndex,\n}: {\n    addressIndex: number;\n    member?: Member;\n    address: Address;\n    addresses: PartialMemberAddress[];\n    user: UserModel;\n    organizationKey?: CachedOrganizationKey;\n}) => {\n    const { isAdmin, canPay } = user;\n    const { ID, Status, Type, Priority, ConfirmationState } = address;\n\n    const isSpecialAddress = Type === TYPE_ORIGINAL || Type === TYPE_PREMIUM;\n\n    const isSelf = !member || !!member.Self;\n    const isDefault = addressIndex === 0;\n    const isEnabled = Status === ADDRESS_STATUS.STATUS_ENABLED;\n    const isExternal = Type === ADDRESS_TYPE.TYPE_EXTERNAL;\n\n    const canMakeDefault = !isDefault && !getIsNonDefault(address);\n\n    const canGenerateMemberAddressKeys = getCanGenerateMemberAddressKeys({ user, member, organizationKey, address });\n    /*\n     * Even though the user in question regarding the permissions here might be\n     * the currently logged in user itself (isSelf), it's possible that they don't\n     * have the necessary permission to generate their own missing keys. This is\n     * the case if the currently logged in user is a member of an org of which they\n     * are not an admin of.\n     */\n    const canGenerateSelfAddressKeys = isSelf && user.Private === MEMBER_PRIVATE.UNREADABLE && !address.HasKeys;\n    const canGenerate = canGenerateMemberAddressKeys || canGenerateSelfAddressKeys;\n\n    let canDisable = isEnabled && isAdmin && !isSpecialAddress && !isExternal;\n\n    const isManagedUser = member?.Type === MEMBER_TYPE.MANAGED;\n    if (isManagedUser) {\n        const hasOtherEnabledAddress = addresses.some(\n            (otherAddress) => otherAddress.ID !== ID && otherAddress.Status === ADDRESS_STATUS.STATUS_ENABLED\n        );\n        // Accounts for: 'Cannot disable your only enabled address. Please add another address first'\n        if (!hasOtherEnabledAddress && isSelf) {\n            canDisable = false;\n        }\n        // Accounts for: 'Cannot disable your default address. Please make another address default first'\n        if (hasOtherEnabledAddress && Priority === 1) {\n            canDisable = false;\n        }\n    }\n\n    const canEditInternalAddress = Type !== ADDRESS_TYPE.TYPE_EXTERNAL && isSelf;\n    const canEditExternalAddress =\n        Type === ADDRESS_TYPE.TYPE_EXTERNAL &&\n        ConfirmationState !== AddressConfirmationState.CONFIRMATION_CONFIRMED &&\n        isSelf;\n\n    return {\n        canMakeDefault,\n        canGenerate,\n        canEditInternalAddress,\n        canEditExternalAddress,\n        canDisable,\n        canEnable: Status === ADDRESS_STATUS.STATUS_DISABLED && isAdmin && !isSpecialAddress,\n        // Takes into account disabling permissions since it does that automatically. canPay to simulate the \"payments\" scope for delete route.\n        canDelete: ((isEnabled && canDisable) || !isEnabled) && Type === TYPE_CUSTOM_DOMAIN && canPay,\n        canEdit: isSelf,\n    };\n};\n\nexport type AddressPermissions = ReturnType<typeof getPermissions>;\nexport type AddressStatuses = ReturnType<typeof getStatus>;\n\nexport interface AddressWithMemberID extends PartialMemberAddress {\n    MemberID: string;\n    MemberName?: string;\n}\n\nexport interface MembersMap {\n    [MemberID: string]: Member;\n}\n\nexport interface SwitchAddressPermissionMultiResponses {\n    Responses: SwitchAddressPermissionResponse[];\n}\n\nexport interface SwitchAddressPermissionResponse {\n    AddressID: string;\n    Response: {\n        Code: number;\n    };\n}\n\nexport interface PermissionOption {\n    text: string;\n    value: ADDRESS_PERMISSIONS;\n    testid: string;\n}\n\nexport const canReceive = (permissions: number): boolean => {\n    return (\n        hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ALL) ||\n        hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ORG)\n    );\n};\n\nexport const canSend = (permissions: number): boolean => {\n    return (\n        hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ALL) ||\n        hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ORG)\n    );\n};\n\nexport const hasIncompleteSetup = (permissions: number): boolean => {\n    return !canReceive(permissions) && !canSend(permissions);\n};\n\nexport const noPermissionMap = (): PermissionOption[] => {\n    return [\n        {\n            text: c('Option').t`No permission`,\n            value: ADDRESS_PERMISSIONS.NO_PERMISSION,\n            testid: 'permission-map:none',\n        },\n    ];\n};\n\nexport const setupIncompletePermissionMap = (): PermissionOption[] => {\n    return [\n        {\n            text: c('Option').t`Setup incomplete`,\n            value: ADDRESS_PERMISSIONS.NO_PERMISSION,\n            testid: 'permission-map:setup-incomplete',\n        },\n    ];\n};\n\nexport const permissionsReceiveMap = (): PermissionOption[] => {\n    return [\n        {\n            text: c('Option').t`Receive from all`,\n            value: ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ALL,\n            testid: 'permission-dropdown:receive-all',\n        },\n        {\n            text: c('Option').t`Organization only`,\n            value: ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ORG,\n            testid: 'permission-dropdown:receive-org',\n        },\n    ];\n};\n\nexport const permissionsSendMap = (): PermissionOption[] => {\n    return [\n        {\n            text: c('Option').t`Send to all`,\n            value: ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ALL,\n            testid: 'permission-dropdown:send-all',\n        },\n        {\n            text: c('Option').t`Organization only`,\n            value: ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ORG,\n            testid: 'permission-dropdown:send-org',\n        },\n    ];\n};\n\nexport const getReceivePermission = (permissions: number) => {\n    if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ALL)) {\n        return ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ALL;\n    }\n    if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ORG)) {\n        return ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ORG;\n    }\n    return ADDRESS_PERMISSIONS.NO_PERMISSION;\n};\n\nexport const getSendPermission = (permissions: number) => {\n    if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ALL)) {\n        return ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ALL;\n    }\n    if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ORG)) {\n        return ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ORG;\n    }\n    return ADDRESS_PERMISSIONS.NO_PERMISSION;\n};\n\nexport const permissionsMap = (addressPermissions: number | undefined, type: ADDRESS_PERMISSION_TYPE) => {\n    if (addressPermissions && !hasIncompleteSetup(addressPermissions)) {\n        if (\n            type === ADDRESS_PERMISSION_TYPE.RECEIVE &&\n            getReceivePermission(addressPermissions) !== ADDRESS_PERMISSIONS.NO_PERMISSION\n        ) {\n            return permissionsReceiveMap();\n        }\n        if (\n            type === ADDRESS_PERMISSION_TYPE.SEND &&\n            getSendPermission(addressPermissions) !== ADDRESS_PERMISSIONS.NO_PERMISSION\n        ) {\n            return permissionsSendMap();\n        }\n    }\n    if (!addressPermissions || hasIncompleteSetup(addressPermissions)) {\n        return setupIncompletePermissionMap();\n    }\n    return noPermissionMap();\n};\n\nexport const getPermission = (permissions: number, type: ADDRESS_PERMISSION_TYPE): string => {\n    if (type === ADDRESS_PERMISSION_TYPE.RECEIVE) {\n        if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ALL)) {\n            return c('Permission').t`Receive from all`;\n        }\n        if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_RECEIVE_ORG)) {\n            return c('Permission').t`Organization only`;\n        }\n        if (hasIncompleteSetup(permissions)) {\n            return c('Permission').t`Setup incomplete`;\n        }\n    } else {\n        if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ALL)) {\n            return c('Permission').t`Send to all`;\n        }\n        if (hasBit(permissions, ADDRESS_PERMISSIONS.PERMISSIONS_SEND_ORG)) {\n            return c('Permission').t`Organization only`;\n        }\n        if (hasIncompleteSetup(permissions)) {\n            return c('Permission').t`Setup incomplete`;\n        }\n    }\n\n    return c('Permission').t`No permission`;\n};\n","import { c } from 'ttag';\n\nimport { CircleLoader } from '@proton/atoms/CircleLoader';\nimport { Address, CachedOrganizationKey, Member, PartialMemberAddress, UserModel } from '@proton/shared/lib/interfaces';\n\nimport { Table, TableBody, TableHeader, TableRow } from '../../components';\nimport AddressActions from './AddressActions';\nimport AddressStatus from './AddressStatus';\nimport { getPermissions, getStatus } from './helper';\n\ninterface AddressesTableProps {\n    loading: boolean;\n    hasUsername: boolean;\n    user: UserModel;\n    members: Member[];\n    memberAddressesMap?: { [key: string]: (Address | PartialMemberAddress)[] | undefined };\n    organizationKey?: CachedOrganizationKey;\n}\n\nconst AddressesTable = ({\n    loading,\n    hasUsername,\n    user,\n    members,\n    memberAddressesMap,\n    organizationKey,\n}: AddressesTableProps) => {\n    return (\n        <Table responsive=\"cards\" hasActions>\n            <TableHeader\n                cells={[\n                    c('Header for addresses table').t`Address`,\n                    hasUsername ? c('Header for addresses table').t`Username` : null,\n                    c('Header for addresses table').t`Status`,\n                    c('Header for addresses table').t`Actions`,\n                ].filter(Boolean)}\n            />\n            <TableBody colSpan={hasUsername ? 4 : 3} loading={loading}>\n                {members.flatMap((member) => {\n                    const memberAddresses = memberAddressesMap?.[member.ID] || [];\n                    return memberAddresses.map((address, i) => {\n                        const emailCell = (\n                            <div className=\"text-ellipsis\" title={address.Email}>\n                                {address.Email}\n                            </div>\n                        );\n                        const nameCell = hasUsername && member.Name;\n\n                        // Partial address getting loaded\n                        if (!('Keys' in address)) {\n                            return (\n                                <TableRow\n                                    key={address.ID}\n                                    cells={[\n                                        emailCell,\n                                        nameCell,\n                                        <div className=\"visibility-hidden\">\n                                            <AddressStatus isActive />\n                                        </div>,\n                                        <CircleLoader />,\n                                    ].filter(Boolean)}\n                                />\n                            );\n                        }\n\n                        return (\n                            <TableRow\n                                key={address.ID}\n                                cells={[\n                                    emailCell,\n                                    nameCell,\n                                    <AddressStatus {...getStatus(address, i)} />,\n                                    <AddressActions\n                                        member={member}\n                                        address={address}\n                                        user={user}\n                                        permissions={getPermissions({\n                                            addressIndex: i,\n                                            member,\n                                            address,\n                                            addresses: memberAddresses,\n                                            user,\n                                            organizationKey,\n                                        })}\n                                    />,\n                                ].filter(Boolean)}\n                            />\n                        );\n                    });\n                })}\n            </TableBody>\n        </Table>\n    );\n};\n\nexport default AddressesTable;\n","/**\n * Returns a new array with the item moved to the new position.\n * @param list List of items\n * @param from Index of item to move. If negative, it will begin that many elements from the end.\n * @param to Index of where to move the item. If negative, it will begin that many elements from the end.\n * @return New array with the item moved to the new position\n */\nconst move = <T>(list: T[] = [], from: number, to: number) => {\n    const copy = list.slice();\n    copy.splice(to < 0 ? copy.length + to : to, 0, copy.splice(from, 1)[0]);\n    return copy;\n};\n\nexport default move;\n","import { PromotionButton } from '../button/PromotionButton';\n\ninterface Props {\n    onClick: () => void;\n    text: string;\n}\n\nconst MailUpsellButton = ({ onClick, text }: Props) => {\n    return (\n        <PromotionButton iconName=\"brand-proton-mail-filled-plus\" onClick={onClick}>\n            {text}\n        </PromotionButton>\n    );\n};\n\nexport default MailUpsellButton;\n","import { ComponentType, ReactNode } from 'react';\nimport { SortableContainer, SortableContainerProps } from 'react-sortable-hoc';\n\ninterface Props extends SortableContainerProps {\n    children: ReactNode;\n}\n\nconst OrderableContainer = SortableContainer(({ children }: Props) => children) as ComponentType<Props>;\n\nexport default OrderableContainer;\n","import { ReactNode, useRef } from 'react';\nimport { SortableContainerProps } from 'react-sortable-hoc';\n\nimport clsx from '@proton/utils/clsx';\n\nimport OrderableContainer from '../orderable/OrderableContainer';\nimport { Table } from '../table';\n\nimport './OrderableTable.scss';\n\ninterface Props extends SortableContainerProps {\n    className?: string;\n    helperClassname?: string;\n    children?: ReactNode;\n    caption?: string;\n}\n\nconst OrderableTable = ({ children = [], className = '', helperClassname, caption, ...props }: Props) => {\n    let wrapperRef = useRef<HTMLDivElement | null>(null);\n\n    return (\n        <div ref={wrapperRef}>\n            <OrderableContainer\n                helperClass={clsx(['orderableHelper'])}\n                useDragHandle\n                helperContainer={() => {\n                    const tbodyElement = wrapperRef.current?.querySelector('tbody');\n                    return tbodyElement || document.body;\n                }}\n                onSortStart={({ node, helper }) => {\n                    // Set the width of each cell in the helper to match the corresponding cell in the node\n                    node.childNodes.forEach((child, index) => {\n                        if (child instanceof HTMLElement) {\n                            const helperChild = helper.childNodes[index];\n\n                            if (helperChild instanceof HTMLElement) {\n                                helperChild.style.width = `${child.offsetWidth}px`;\n                            }\n                        }\n                    });\n                }}\n                {...props}\n            >\n                <Table caption={caption} responsive=\"cards\" className={clsx(['orderableTable', className])}>\n                    {children}\n                </Table>\n            </OrderableContainer>\n        </div>\n    );\n};\n\nexport default OrderableTable;\n","import { ReactNode } from 'react';\n\nimport clsx from '@proton/utils/clsx';\n\nimport { TableHeader } from '../table';\n\nimport './OrderableTableHeader.scss';\n\ninterface Props {\n    cells?: ReactNode[];\n    className?: string;\n    children?: ReactNode;\n}\n\nconst OrderableTableHeader = ({ cells = [], className = '', children = null, ...rest }: Props) => (\n    <TableHeader\n        cells={[\n            null, // column for icon\n            ...cells,\n        ]}\n        className={clsx(['orderableTableHeader', className])}\n        {...rest}\n    >\n        {children}\n    </TableHeader>\n);\n\nexport default OrderableTableHeader;\n","import { ReactNode } from 'react';\n\nimport { TableBody } from '../table';\n\ninterface Props {\n    children?: ReactNode;\n    colSpan?: number;\n    loading?: boolean;\n}\n\nconst OrderableTableBody = ({ children, colSpan = 0, loading, ...rest }: Props) => (\n    <TableBody {...rest} colSpan={colSpan + 1} loading={loading}>\n        {children}\n    </TableBody>\n);\n\nexport default OrderableTableBody;\n","import { ComponentType, ReactNode, Ref } from 'react';\nimport { SortableElement, SortableElementProps } from 'react-sortable-hoc';\n\ninterface Props extends SortableElementProps {\n    children?: ReactNode;\n    ref?: Ref<any>;\n}\n\nconst OrderableElement = SortableElement(({ children }: Props) => children) as unknown as ComponentType<Props>;\n\nexport default OrderableElement;\n","import { ComponentType, ReactNode } from 'react';\nimport { SortableHandle } from 'react-sortable-hoc';\n\ninterface Props {\n    children?: ReactNode;\n}\n\nconst OrderableHandle = SortableHandle(({ children }: Props): ReactNode => children) as ComponentType<Props>;\n\nexport default OrderableHandle;\n","import { ReactNode, Ref, forwardRef } from 'react';\n\nimport Icon from '../icon/Icon';\nimport { OrderableElement, OrderableHandle } from '../orderable';\nimport { Cell, TableRow } from '../table';\n\ninterface Props {\n    index: number;\n    className?: string;\n    cells?: (Cell | ReactNode)[];\n    disableSort?: boolean;\n}\n\nconst OrderableTableRow = ({ index, cells = [], className, disableSort, ...rest }: Props, ref: Ref<any>) => {\n    if (disableSort) {\n        return <TableRow cells={['', ...cells]} className={className} {...rest} />;\n    }\n\n    return (\n        <OrderableElement index={index} ref={ref}>\n            <TableRow\n                cells={[\n                    <OrderableHandle key=\"icon\">\n                        <span className=\"flex\" data-testid=\"table:order-icon\">\n                            <Icon className=\"my-auto cursor-grab color-hint\" name=\"dots\" />\n                        </span>\n                    </OrderableHandle>,\n                    ...cells,\n                ]}\n                className={className}\n                {...rest}\n            />\n        </OrderableElement>\n    );\n};\n\nexport default forwardRef(OrderableTableRow);\n","import { c } from 'ttag';\n\nimport { MAX_CALENDARS_PAID } from '@proton/shared/lib/calendar/constants';\nimport { BRAND_NAME, CALENDAR_APP_NAME, DRIVE_APP_NAME, MAIL_APP_NAME } from '@proton/shared/lib/constants';\n\nimport { getNCalendarsText } from '../../../containers/payments/features/calendar';\nimport { UpsellFeature } from './interface';\n\nexport type UpsellFeatureName =\n    | 'auto-delete-trash-and-spam'\n    | 'schedule-messages'\n    | 'unlimited-folders-and-labels'\n    | 'search-message-content'\n    | 'more-storage'\n    | 'more-email-addresses'\n    | 'custom-email-domains'\n    | 'email-aliases'\n    | 'snooze-messages'\n    | 'more-calendars'\n    | 'calendar-sharing';\n\nconst domain = 'proton.me';\n// Dirty fix because we cannot add twice the same variable in a string with ttag\nconst domain2 = 'proton.me';\n\n/**\n * Default upsell features\n */\nexport const upsellFeatures: Record<UpsellFeatureName, UpsellFeature> = {\n    'auto-delete-trash-and-spam': {\n        icon: 'trash-clock',\n        getText: () => c('new_plans: feature').t`Auto-delete spam and trashed messages`,\n    },\n    'schedule-messages': {\n        icon: 'paper-plane-clock',\n        getText: () => c('new_plans: feature').t`Schedule messages at any time`,\n    },\n    'unlimited-folders-and-labels': {\n        icon: 'folders',\n        getText: () => c('new_plans: feature').t`Unlimited folders, labels, and filters`,\n    },\n    'search-message-content': {\n        icon: 'magnifier',\n        getText: () => c('new_plans: feature').t`Search message content`,\n    },\n    'more-storage': {\n        icon: 'storage',\n        getText: () => c('new_plans: feature').t`Up to 3 TB of storage`,\n        getTooltip: () =>\n            c('new_plans: feature info')\n                .t`Storage space is shared across ${MAIL_APP_NAME}, ${CALENDAR_APP_NAME} and ${DRIVE_APP_NAME}`,\n    },\n    'more-email-addresses': {\n        icon: 'envelopes',\n        getText: () => c('new_plans: feature').t`Up to 15 email addresses`,\n        getTooltip: () =>\n            c('new_plans: feature info')\n                .t`Create multiple email addresses for your online identities e.g. JohnShopper@${domain} for shopping accounts, JohnNews@${domain2} for news subscription`,\n    },\n    'custom-email-domains': {\n        icon: 'globe',\n        getText: () => c('new_plans: feature').t`Custom email domains`,\n        getTooltip: () =>\n            c('new_plans: feature info').t`Use your own custom email domain address, e.g., you@yourname.com`,\n    },\n    'email-aliases': {\n        icon: 'eye-slash',\n        getText: () => c('new_plans: feature').t`Hide-my-email aliases`,\n        getTooltip: () => c('new_plans: feature info').t`Get unlimited aliases with SimpleLogin by ${BRAND_NAME}`,\n    },\n    'snooze-messages': {\n        icon: 'clock',\n        getText: () => c('new_plans: feature').t`Custom snooze time`,\n        getTooltip: () => c('new_plans: feature info').t`Snooze messages and get reminded when you want`,\n    },\n    'more-calendars': {\n        icon: 'calendar-grid',\n        getText: () => {\n            return getNCalendarsText(MAX_CALENDARS_PAID);\n        },\n    },\n    'calendar-sharing': {\n        icon: 'users',\n        getText: () => c('new_plans: feature').t`Calendar sharing`,\n    },\n};\n","import React from 'react';\n\nimport { c } from 'ttag';\n\nimport { ButtonLike } from '@proton/atoms/Button';\nimport {\n    Icon,\n    Info,\n    ModalSize,\n    ModalStateProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoHeader,\n    SettingsLink,\n} from '@proton/components/components';\nimport calendarHeaderImage from '@proton/styles/assets/img/illustrations/upsell-calendar-header.svg';\nimport mailHeaderImage from '@proton/styles/assets/img/illustrations/upsell-mail-header.svg';\n\nimport { UpsellFeatureName, upsellFeatures } from './constants';\n\ntype UpsellHeaderType = 'mail' | 'calendar';\nconst getHeader = (headerType: UpsellHeaderType) => {\n    switch (headerType) {\n        case 'mail':\n            return mailHeaderImage;\n        case 'calendar':\n            return calendarHeaderImage;\n    }\n};\n\ntype UpsellBoxProps = Partial<Pick<UpsellModalProps, 'hideInfo'>> &\n    Required<\n        Pick<UpsellModalProps, 'description' | 'title' | 'features'> & {\n            handleUpgrade: () => void;\n            headerType: UpsellHeaderType;\n            path: string;\n        }\n    >;\n\nconst UpsellBox = ({ description, handleUpgrade, title, features, hideInfo, headerType, path }: UpsellBoxProps) => {\n    const UpgradeButton = (\n        <ButtonLike\n            as={SettingsLink}\n            path={path}\n            onClick={handleUpgrade}\n            size=\"large\"\n            color=\"norm\"\n            shape=\"solid\"\n            fullWidth\n        >\n            {c('new_plans: Action').t`Upgrade now`}\n        </ButtonLike>\n    );\n    return (\n        <div>\n            <div className=\"text-center\">\n                <div className=\"mb-4 rounded\">\n                    <img src={getHeader(headerType)} className=\"w-full block\" alt=\"\" />\n                </div>\n                <h1 className=\"h3 text-bold mb-4\">{title}</h1>\n                <div className=\"color-weak mb-4 px-4\">{description}</div>\n            </div>\n\n            {features.length ? (\n                <div className=\"border border-primary rounded p-6 pt-4\">\n                    <ul className=\"m-0 unstyled mb-4\">\n                        {features.map((featureName) => {\n                            const feature = upsellFeatures[featureName];\n                            return (\n                                <li className=\"py-2 rounded\" key={feature.getText()}>\n                                    <div className=\"flex flex-nowrap items-center\">\n                                        <div className=\"mr-3 shrink-0 flex\">\n                                            <Icon className=\"color-primary m-auto\" size={5} name={feature.icon} />\n                                        </div>\n                                        <div className=\"flex-1\">\n                                            {feature.getText()}\n                                            {feature.getTooltip && !hideInfo ? (\n                                                <Info buttonClass=\"ml-2\" title={feature.getTooltip()} />\n                                            ) : null}\n                                        </div>\n                                    </div>\n                                </li>\n                            );\n                        })}\n                    </ul>\n                    {UpgradeButton}\n                </div>\n            ) : (\n                UpgradeButton\n            )}\n        </div>\n    );\n};\n\nexport interface UpsellModalProps {\n    ['data-testid']?: string;\n    description: string;\n    features: UpsellFeatureName[];\n    modalProps: ModalStateProps;\n    title: string;\n    upgradePath: string;\n    onClose?: () => void;\n    headerType?: UpsellHeaderType;\n    hideInfo?: boolean;\n    size?: ModalSize;\n}\n\nconst UpsellModal = ({\n    description,\n    features,\n    hideInfo,\n    modalProps,\n    title,\n    upgradePath,\n    'data-testid': dataTestid,\n    onClose,\n    headerType = 'mail',\n    size,\n}: UpsellModalProps) => {\n    const handleUpgrade = () => {\n        modalProps.onClose();\n    };\n\n    const handleClose = () => {\n        onClose?.();\n        modalProps.onClose();\n    };\n\n    return (\n        <ModalTwo data-testid={dataTestid} {...modalProps} onClose={handleClose} size={size}>\n            <ModalTwoHeader />\n            <ModalTwoContent className=\"mb-8\">\n                <UpsellBox\n                    title={title}\n                    description={description}\n                    features={features}\n                    handleUpgrade={handleUpgrade}\n                    headerType={headerType}\n                    path={upgradePath}\n                    hideInfo={hideInfo}\n                />\n            </ModalTwoContent>\n        </ModalTwo>\n    );\n};\n\nexport default UpsellModal;\n","import { useCallback, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Href } from '@proton/atoms/Href';\nimport { SettingsParagraph } from '@proton/components/containers';\nimport { orderAddress } from '@proton/shared/lib/api/addresses';\nimport { APP_UPSELL_REF_PATH, BRAND_NAME, MAIL_UPSELL_PATHS, UPSELL_COMPONENT } from '@proton/shared/lib/constants';\nimport isDeepEqual from '@proton/shared/lib/helpers/isDeepEqual';\nimport { addUpsellPath, getUpgradePath, getUpsellRef } from '@proton/shared/lib/helpers/upsell';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Address, CachedOrganizationKey, Member, UserModel } from '@proton/shared/lib/interfaces';\nimport { getIsNonDefault, sortAddresses } from '@proton/shared/lib/mail/addresses';\nimport move from '@proton/utils/move';\n\nimport {\n    Alert,\n    MailUpsellButton,\n    OrderableTable,\n    OrderableTableBody,\n    OrderableTableHeader,\n    OrderableTableRow,\n    UpsellModal,\n    useModalState,\n} from '../../components';\nimport { useAddresses, useApi, useEventManager, useNotifications } from '../../hooks';\nimport AddressActions from './AddressActions';\nimport AddressStatus from './AddressStatus';\nimport { getPermissions, getStatus } from './helper';\n\ninterface Props {\n    user: UserModel;\n    member?: Member;\n    organizationKey?: CachedOrganizationKey;\n    hasDescription?: boolean;\n}\n\nconst AddressesUser = ({ user, organizationKey, member, hasDescription = true }: Props) => {\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const [savingIndex, setSavingIndex] = useState<number | undefined>();\n    const { call } = useEventManager();\n    const [addresses, loadingAddresses] = useAddresses();\n    const [list, setAddresses] = useState<Address[]>(() => sortAddresses(addresses || []));\n\n    const upsellRef = getUpsellRef({\n        app: APP_UPSELL_REF_PATH.MAIL_UPSELL_REF_PATH,\n        component: UPSELL_COMPONENT.MODAL,\n        feature: MAIL_UPSELL_PATHS.UNLIMITED_ADDRESSES,\n        isSettings: true,\n    });\n\n    const [upsellModalProps, handleUpsellModalDisplay, renderUpsellModal] = useModalState();\n\n    useEffect(() => {\n        if (addresses) {\n            setAddresses(sortAddresses(addresses));\n        }\n    }, [addresses]);\n\n    const handleSortEnd = useCallback(\n        async ({ oldIndex, newIndex }: { oldIndex: number; newIndex: number }) => {\n            try {\n                const newList = move(list, oldIndex, newIndex);\n                const { isExternal, isDisabled } = getStatus(newList[0], 0);\n\n                if (isDeepEqual(list, newList)) {\n                    return;\n                }\n\n                if (newIndex === 0 && (isDisabled || isExternal)) {\n                    const errorMessage = (() => {\n                        if (isDisabled) {\n                            return c('Notification').t`A disabled address cannot be default`;\n                        }\n                        if (isExternal) {\n                            return c('Notification').t`An external address cannot be default`;\n                        }\n                    })();\n                    if (errorMessage) {\n                        createNotification({\n                            type: 'error',\n                            text: errorMessage,\n                        });\n                    }\n                    setAddresses(sortAddresses(addresses));\n                    return;\n                }\n\n                setAddresses(newList);\n                setSavingIndex(newIndex);\n\n                await api(orderAddress(newList.map(({ ID }) => ID)));\n                await call();\n\n                setSavingIndex(undefined);\n            } catch (e: any) {\n                setSavingIndex(undefined);\n                setAddresses(sortAddresses(addresses));\n            }\n        },\n        [list, addresses]\n    );\n\n    const setDefaultAddress = useCallback(\n        (addressOldIndex: number) => {\n            return async () => {\n                await handleSortEnd({ oldIndex: addressOldIndex, newIndex: 0 });\n            };\n        },\n        [list, addresses]\n    );\n\n    if (!loadingAddresses && !addresses?.length) {\n        return <Alert className=\"mb-4\">{c('Info').t`No addresses exist`}</Alert>;\n    }\n\n    return (\n        <>\n            {hasDescription && (\n                <SettingsParagraph className=\"mt-2\">\n                    <span>\n                        {c('Info').t`Use the different types of email addresses and aliases offered by ${BRAND_NAME}.`}\n                    </span>\n                    <br />\n                    <Href href={getKnowledgeBaseUrl('/addresses-and-aliases')}>{c('Link').t`Learn more`}</Href>\n                </SettingsParagraph>\n            )}\n\n            {!user.hasPaidMail && (\n                <MailUpsellButton\n                    onClick={() => handleUpsellModalDisplay(true)}\n                    text={c('Action').t`Get more addresses`}\n                />\n            )}\n\n            <OrderableTable\n                onSortEnd={handleSortEnd}\n                className=\"simple-table--has-actions\"\n                helperClassname=\"simple-table--has-actions\"\n            >\n                <OrderableTableHeader\n                    cells={[\n                        c('Header for addresses table').t`Address`,\n                        c('Header for addresses table').t`Status`,\n                        c('Header for addresses table').t`Actions`,\n                    ]}\n                />\n                <OrderableTableBody colSpan={3} loading={loadingAddresses}>\n                    {list &&\n                        list.map((address, i) => {\n                            const addressStatuses = getStatus(address, i);\n                            return (\n                                <OrderableTableRow\n                                    disableSort={getIsNonDefault(address)}\n                                    key={i}\n                                    index={i}\n                                    cells={[\n                                        <div key={0} className=\"text-ellipsis\" title={address.Email}>\n                                            {address.Email}\n                                        </div>,\n                                        <AddressStatus key={1} {...addressStatuses} />,\n                                        <AddressActions\n                                            key={2}\n                                            address={address}\n                                            member={member}\n                                            user={user}\n                                            onSetDefault={setDefaultAddress(i)}\n                                            savingIndex={savingIndex}\n                                            addressIndex={i}\n                                            permissions={getPermissions({\n                                                addressIndex: i,\n                                                member,\n                                                address,\n                                                addresses: list,\n                                                user,\n                                                organizationKey,\n                                            })}\n                                        />,\n                                    ]}\n                                />\n                            );\n                        })}\n                </OrderableTableBody>\n            </OrderableTable>\n\n            {renderUpsellModal && (\n                <UpsellModal\n                    title={c('Title').t`Increase your privacy with more addresses`}\n                    description={c('Description')\n                        .t`Separate different aspects of your life with multiple email addresses and unlock more premium features when you upgrade.`}\n                    modalProps={upsellModalProps}\n                    upgradePath={addUpsellPath(getUpgradePath({ user }), upsellRef)}\n                    features={[\n                        'more-storage',\n                        'more-email-addresses',\n                        'unlimited-folders-and-labels',\n                        'custom-email-domains',\n                    ]}\n                />\n            )}\n        </>\n    );\n};\n\nexport default AddressesUser;\n","import { useMemo, useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { useMemberAddresses } from '@proton/account';\nimport { getDomainAdressError } from '@proton/account/members/validateAddUser';\nimport { Button, Href } from '@proton/atoms';\nimport { GenericError } from '@proton/components/containers';\nimport { ALL_MEMBERS_ID, BRAND_NAME, MEMBER_PRIVATE } from '@proton/shared/lib/constants';\nimport { getAvailableAddressDomains } from '@proton/shared/lib/helpers/address';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Member, Organization, UserModel } from '@proton/shared/lib/interfaces';\n\nimport { Alert, Loader, SettingsLink, useModalState } from '../../components';\nimport {\n    useAddresses,\n    useCustomDomains,\n    useMembers,\n    useNotifications,\n    useOrganizationKey,\n    useProtonDomains,\n} from '../../hooks';\nimport { SettingsParagraph } from '../account';\nimport AddressModal from './AddressModal';\nimport AddressesTable from './AddressesTable';\nimport AddressesWithUser from './AddressesWithUser';\n\nconst getMemberIndex = (members: Member[] = [], memberID?: string, isOnlySelf?: boolean) => {\n    const newMemberIndex =\n        memberID && !isOnlySelf\n            ? members.findIndex(({ ID }) => ID === memberID)\n            : members.findIndex(({ Self }) => Self);\n    if (newMemberIndex === -1 && members.length) {\n        return 0;\n    }\n    return newMemberIndex;\n};\n\ninterface Props {\n    user: UserModel;\n    organization?: Organization;\n    isOnlySelf?: boolean;\n    memberID?: string;\n}\n\nconst AddressesWithMembers = ({ user, organization, memberID, isOnlySelf }: Props) => {\n    const [members, loadingMembers] = useMembers();\n    const [addresses, loadingAddresses] = useAddresses();\n    const [customDomains] = useCustomDomains();\n    const [{ premiumDomains, protonDomains }] = useProtonDomains();\n    const [organizationKey] = useOrganizationKey();\n    const [addressModalProps, setAddressModalOpen, renderAddressModal] = useModalState();\n    const { createNotification } = useNotifications();\n    const [tmpMember, setTmpMember] = useState<Member | null>(null);\n\n    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;\n\n    const { UsedAddresses: OrganizationUsedAddresses, MaxAddresses: OrganizationMaxAddresses } = organization || {};\n    const UsedAddresses = hasAddresses ? OrganizationUsedAddresses || 1 : 0;\n    const MaxAddresses = OrganizationMaxAddresses || 1;\n\n    const memberIndex = useMemo(() => {\n        if (Array.isArray(members)) {\n            return getMemberIndex(members, memberID, isOnlySelf);\n        }\n\n        return -1;\n    }, [members, memberID]);\n\n    const selectedMembers = useMemo(() => {\n        if (members && memberIndex === ALL_MEMBERS_ID) {\n            return members;\n        }\n        if (members && memberIndex in members) {\n            return [members[memberIndex]];\n        }\n        return [];\n    }, [members, memberIndex]);\n\n    const { value: memberAddressesMap, retry } = useMemberAddresses({\n        members: selectedMembers,\n        partial: false,\n    });\n\n    const hasUsernameDisplay = memberIndex === ALL_MEMBERS_ID;\n    const isSelfSelected = useMemo(() => {\n        if (!members) {\n            return false;\n        }\n        return memberIndex === members.findIndex(({ Self }) => Self);\n    }, [memberIndex, members]);\n\n    const handleAddAddress = (member: Member) => {\n        if (member.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey) {\n            createNotification({ type: 'error', text: c('Error').t`The organization key must be activated first` });\n            return;\n        }\n        const domains = getAvailableAddressDomains({\n            member,\n            user,\n            premiumDomains,\n            customDomains,\n            protonDomains,\n        });\n        if (!domains.length) {\n            createNotification({ type: 'error', text: getDomainAdressError() });\n            return;\n        }\n        setTmpMember(member);\n        setAddressModalOpen(true);\n    };\n\n    const currentMember = members?.[memberIndex];\n\n    const mustActivateOrganizationKey =\n        currentMember?.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey;\n\n    const activateLink = (\n        <SettingsLink path=\"/organization-keys\" key=\"activate\">{c('Action').t`activate`}</SettingsLink>\n    );\n\n    const membersWithError = selectedMembers.filter((member) => {\n        return member.addressState === 'rejected';\n    });\n\n    const children = (\n        <>\n            <SettingsParagraph className=\"mt-2\">\n                <span>\n                    {c('Info').t`Use the different types of email addresses and aliases offered by ${BRAND_NAME}.`}\n                </span>\n                <br />\n                <Href href={getKnowledgeBaseUrl('/addresses-and-aliases')}>{c('Link').t`Learn more`}</Href>\n            </SettingsParagraph>\n\n            {currentMember && !user.isSubUser && (\n                <div className=\"mb-4 flex gap-2 self-start items-center\">\n                    <div className=\"mr-4\">\n                        {mustActivateOrganizationKey ? (\n                            <Alert className=\"mb-4\" type=\"warning\">\n                                {c('Warning')\n                                    .jt`You must ${activateLink} the organization key before adding an email address to a non-private member.`}\n                            </Alert>\n                        ) : (\n                            <Button\n                                shape=\"outline\"\n                                onClick={() => handleAddAddress(currentMember)}\n                                data-testid=\"settings:identity-section:add-address\"\n                            >\n                                {c('Action').t`Add address`}\n                            </Button>\n                        )}\n                    </div>\n                    <div>\n                        {c('Label').ngettext(\n                            msgid`${UsedAddresses} of ${MaxAddresses} email address`,\n                            `${UsedAddresses} of ${MaxAddresses} email addresses`,\n                            MaxAddresses\n                        )}\n                    </div>\n                </div>\n            )}\n\n            {(() => {\n                if (isSelfSelected) {\n                    return (\n                        <AddressesWithUser\n                            user={user}\n                            member={currentMember}\n                            organizationKey={organizationKey}\n                            hasDescription={false}\n                        />\n                    );\n                }\n\n                if (membersWithError.length) {\n                    return (\n                        <GenericError>\n                            <Button onClick={() => retry(membersWithError)}>{c('Action').t`Retry`}</Button>\n                        </GenericError>\n                    );\n                }\n\n                return (\n                    <AddressesTable\n                        hasUsername={hasUsernameDisplay}\n                        loading={selectedMembers.some(({ ID }) => !Array.isArray(memberAddressesMap?.[ID]))}\n                        user={user}\n                        members={selectedMembers}\n                        memberAddressesMap={memberAddressesMap}\n                        organizationKey={organizationKey}\n                    />\n                );\n            })()}\n        </>\n    );\n    const loading = loadingMembers || loadingAddresses || memberIndex === -1;\n\n    return (\n        <>\n            {renderAddressModal && tmpMember && members && (\n                <AddressModal member={tmpMember} members={members} {...addressModalProps} />\n            )}\n            {loading ? <Loader /> : children}\n        </>\n    );\n};\n\nexport default AddressesWithMembers;\n","import { Organization } from '@proton/shared/lib/interfaces';\n\nimport { useUser } from '../../hooks';\nimport AddressesWithMembers from './AddressesWithMembers';\nimport AddressesWithUser from './AddressesWithUser';\n\ninterface AddressesProps {\n    isOnlySelf?: boolean;\n    organization?: Organization;\n    memberID?: string;\n}\n\nconst Addresses = ({ isOnlySelf, organization, memberID }: AddressesProps) => {\n    const [user] = useUser();\n\n    return user.isAdmin && user.hasPaidMail ? (\n        <AddressesWithMembers isOnlySelf={isOnlySelf} user={user} memberID={memberID} organization={organization} />\n    ) : (\n        <AddressesWithUser user={user} />\n    );\n};\n\nexport default Addresses;\n","import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport {\n    MemberKeyPayload,\n    editMember,\n    getMemberAddresses,\n    getMemberEditPayload,\n    getPrivateAdminError,\n} from '@proton/account';\nimport { Button, Card } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { useDispatch } from '@proton/redux-shared-store';\nimport { getSilentApi } from '@proton/shared/lib/api/helpers/customConfig';\nimport { GIGA, MEMBER_PRIVATE, MEMBER_ROLE, MEMBER_SUBSCRIBER, NAME_PLACEHOLDER } from '@proton/shared/lib/constants';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { EnhancedMember } from '@proton/shared/lib/interfaces';\nimport { getIsPasswordless } from '@proton/shared/lib/keys';\nimport noop from '@proton/utils/noop';\n\nimport {\n    Icon,\n    Info,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    Prompt,\n    Toggle,\n    Tooltip,\n    useFormErrors,\n    useModalState,\n} from '../../components';\nimport {\n    useApi,\n    useErrorHandler,\n    useEventManager,\n    useNotifications,\n    useOrganization,\n    useOrganizationKey,\n} from '../../hooks';\nimport Addresses from '../addresses/Addresses';\nimport useVerifyOutboundPublicKeys from '../keyTransparency/useVerifyOutboundPublicKeys';\nimport MemberStorageSelector, { getStorageRange, getTotalStorage } from './MemberStorageSelector';\nimport { adminTooltipText } from './constants';\n\ninterface Props extends ModalProps<'form'> {\n    member: EnhancedMember;\n    allowStorageConfiguration?: boolean;\n    allowVpnAccessConfiguration?: boolean;\n    allowPrivateMemberConfiguration?: boolean;\n    showAddressesSection?: boolean;\n}\n\nconst SubUserEditModal = ({\n    member,\n    allowStorageConfiguration,\n    allowVpnAccessConfiguration,\n    allowPrivateMemberConfiguration,\n    showAddressesSection,\n    ...rest\n}: Props) => {\n    const [organization] = useOrganization();\n    const [organizationKey] = useOrganizationKey();\n    const dispatch = useDispatch();\n    const storageSizeUnit = GIGA;\n    const { call } = useEventManager();\n    const verifyOutboundPublicKeys = useVerifyOutboundPublicKeys();\n    const { validator, onFormSubmit } = useFormErrors();\n    const [confirmDemotionModalProps, setConfirmDemotionModal, renderConfirmDemotion] = useModalState();\n    const [confirmPromotionModalProps, setConfirmPromotionModal, renderConfirmPromotion] = useModalState();\n    const memberKeyPacketPayload = useRef<MemberKeyPayload | null>(null);\n    const passwordlessMode = getIsPasswordless(organizationKey?.Key);\n\n    useEffect(() => {\n        dispatch(getMemberAddresses({ member })).catch(noop);\n    }, []);\n\n    const initialModel = useMemo(\n        () => ({\n            name: member.Name,\n            storage: member.MaxSpace,\n            vpn: !!member.MaxVPN,\n            private: !!member.Private,\n            admin: member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN,\n        }),\n        [member]\n    );\n\n    const [model, updateModel] = useState(initialModel);\n\n    const [submitting, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n    const normalApi = useApi();\n    const silentApi = getSilentApi(normalApi);\n\n    const hasVPN = Boolean(organization?.MaxVPN);\n    const canMakePrivate = member.Private === MEMBER_PRIVATE.READABLE;\n    const canMakeAdmin = !member.Self && member.Role === MEMBER_ROLE.ORGANIZATION_MEMBER && !member.SSO;\n    const canRevokeAdmin = !member.Self && member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN;\n    const errorHandler = useErrorHandler();\n\n    const updatePartialModel = (partial: Partial<typeof model>) => {\n        updateModel({ ...model, ...partial });\n    };\n\n    const handleSubmit = async ({\n        role,\n        memberKeyPacketPayload,\n    }: {\n        role: MEMBER_ROLE | null;\n        memberKeyPacketPayload: MemberKeyPayload | null;\n    }) => {\n        const result = await dispatch(\n            editMember({\n                member,\n                memberDiff: {\n                    name: initialModel.name !== model.name ? model.name : undefined,\n                    storage: initialModel.storage !== model.storage ? model.storage : undefined,\n                    vpn: hasVPN && initialModel.vpn !== model.vpn ? model.vpn : undefined,\n                    private:\n                        canMakePrivate && model.private && model.private !== initialModel.private ? true : undefined,\n                    role: role !== null ? role : undefined,\n                },\n                memberKeyPacketPayload,\n                api: silentApi,\n            })\n        );\n        if (result) {\n            await call();\n            createNotification({ text: c('Success').t`User updated` });\n        }\n        rest.onClose?.();\n    };\n\n    const handleClose = submitting ? undefined : rest.onClose;\n\n    return (\n        <>\n            {renderConfirmDemotion && (\n                <Prompt\n                    title={c('Title').t`Change role`}\n                    buttons={[\n                        <Button\n                            color=\"danger\"\n                            loading={submitting}\n                            onClick={() => {\n                                confirmDemotionModalProps.onClose();\n                                void withLoading(\n                                    handleSubmit({\n                                        role: MEMBER_ROLE.ORGANIZATION_MEMBER,\n                                        memberKeyPacketPayload: memberKeyPacketPayload.current,\n                                    })\n                                ).catch(errorHandler);\n                            }}\n                        >{c('Action').t`Remove`}</Button>,\n                        <Button\n                            onClick={() => {\n                                confirmDemotionModalProps.onClose();\n                            }}\n                        >{c('Action').t`Cancel`}</Button>,\n                    ]}\n                    {...confirmDemotionModalProps}\n                >\n                    {member.Subscriber === MEMBER_SUBSCRIBER.PAYER\n                        ? c('Info')\n                              .t`This user is currently responsible for payments for your organization. By demoting this member, you will become responsible for payments for your organization.`\n                        : c('Info').t`Are you sure you want to remove administrative privileges from this user?`}\n                </Prompt>\n            )}\n            {renderConfirmPromotion && (\n                <Prompt\n                    title={c('Title').t`Change role`}\n                    buttons={[\n                        <Button\n                            color=\"norm\"\n                            loading={submitting}\n                            onClick={() => {\n                                confirmPromotionModalProps.onClose();\n                                withLoading(\n                                    handleSubmit({\n                                        role: MEMBER_ROLE.ORGANIZATION_ADMIN,\n                                        memberKeyPacketPayload: memberKeyPacketPayload.current,\n                                    })\n                                ).catch(errorHandler);\n                            }}\n                        >{c('Action').t`Make admin`}</Button>,\n                        <Button\n                            onClick={() => {\n                                confirmPromotionModalProps.onClose();\n                            }}\n                        >{c('Action').t`Cancel`}</Button>,\n                    ]}\n                    {...confirmPromotionModalProps}\n                >\n                    <div className=\"mb-2\">\n                        {c('Info').t`Are you sure you want to give administrative privileges to this user?`}\n                    </div>\n                    <Card rounded className=\"text-break\">\n                        {(() => {\n                            if (!memberKeyPacketPayload.current) {\n                                return '';\n                            }\n                            const { member, email } = memberKeyPacketPayload.current;\n                            return (\n                                <>\n                                    <div className=\"text-bold\">{member.Name}</div>\n                                    <div>{email}</div>\n                                </>\n                            );\n                        })()}\n                    </Card>\n                </Prompt>\n            )}\n            <Modal\n                as=\"form\"\n                size=\"large\"\n                {...rest}\n                onSubmit={(event: FormEvent<HTMLFormElement>) => {\n                    event.preventDefault();\n                    event.stopPropagation();\n\n                    if (!onFormSubmit(event.currentTarget)) {\n                        return;\n                    }\n\n                    let role: MEMBER_ROLE | null = (() => {\n                        if (canRevokeAdmin && !model.admin && model.admin !== initialModel.admin) {\n                            return MEMBER_ROLE.ORGANIZATION_MEMBER;\n                        }\n                        if (canMakeAdmin && model.admin && model.admin !== initialModel.admin) {\n                            return MEMBER_ROLE.ORGANIZATION_ADMIN;\n                        }\n                        return null;\n                    })();\n\n                    const run = async () => {\n                        memberKeyPacketPayload.current = null;\n                        const { payload, action } = await dispatch(\n                            getMemberEditPayload({\n                                verifyOutboundPublicKeys,\n                                role,\n                                member,\n                                api: silentApi,\n                            })\n                        );\n                        memberKeyPacketPayload.current = payload;\n                        if (action === 'confirm-demote') {\n                            setConfirmDemotionModal(true);\n                            return;\n                        }\n                        if (action === 'confirm-promote') {\n                            setConfirmPromotionModal(true);\n                            return;\n                        }\n                        await handleSubmit({ role, memberKeyPacketPayload: payload });\n                    };\n\n                    withLoading(run()).catch(errorHandler);\n                }}\n                onClose={handleClose}\n            >\n                <ModalHeader title={c('Title').t`Edit user`} />\n                <ModalContent>\n                    <InputFieldTwo\n                        id=\"name\"\n                        value={model.name}\n                        error={validator([requiredValidator(model.name)])}\n                        onValue={(value: string) => updatePartialModel({ name: value })}\n                        label={c('Label').t`Name`}\n                        placeholder={NAME_PLACEHOLDER}\n                        autoFocus\n                    />\n                    {allowStorageConfiguration && (\n                        <MemberStorageSelector\n                            className=\"mb-5\"\n                            value={model.storage}\n                            sizeUnit={storageSizeUnit}\n                            totalStorage={getTotalStorage(member, organization)}\n                            range={getStorageRange(member, organization)}\n                            onChange={(storage) => updatePartialModel({ storage })}\n                        />\n                    )}\n\n                    {allowVpnAccessConfiguration && hasVPN ? (\n                        <div className=\"flex mb-5\">\n                            <label className=\"text-semibold mr-4\" htmlFor=\"vpn-toggle\">\n                                {c('Label for new member').t`VPN connections`}\n                            </label>\n                            <Toggle\n                                id=\"vpn-toggle\"\n                                checked={model.vpn}\n                                onChange={({ target }) => updatePartialModel({ vpn: target.checked })}\n                            />\n                        </div>\n                    ) : null}\n\n                    {allowPrivateMemberConfiguration && canMakePrivate && (\n                        <div className=\"flex mb-6\">\n                            <label className=\"text-semibold mr-4\" htmlFor=\"private-toggle\">\n                                {c('Label for new member').t`Private`}\n                            </label>\n                            <Toggle\n                                id=\"private-toggle\"\n                                checked={model.private}\n                                onChange={({ target }) => updatePartialModel({ private: target.checked })}\n                            />\n                        </div>\n                    )}\n                    {(canMakeAdmin || canRevokeAdmin) && (\n                        <div className=\"flex items-center mb-6\">\n                            <label className=\"text-semibold mr-1\" htmlFor=\"admin-toggle\">\n                                {c('Label for new member').t`Admin`}\n                            </label>\n                            <Info className=\"mr-4\" title={adminTooltipText} url={getKnowledgeBaseUrl('/user-roles')} />\n                            <Toggle\n                                id=\"admin-toggle\"\n                                checked={model.admin}\n                                onChange={({ target }) => updatePartialModel({ admin: target.checked })}\n                            />\n                            {passwordlessMode &&\n                                model.private &&\n                                model.admin &&\n                                member.addressState === 'full' &&\n                                !member.Addresses?.[0]?.HasKeys && (\n                                    <Tooltip title={getPrivateAdminError()} openDelay={0}>\n                                        <Icon className=\"color-danger ml-2\" name=\"info-circle-filled\" />\n                                    </Tooltip>\n                                )}\n                        </div>\n                    )}\n                    {showAddressesSection && (\n                        <div>\n                            <h3 className=\"text-strong\">{c('Label').t`Addresses`}</h3>\n                            <div>\n                                <Addresses organization={organization} memberID={member.ID} />\n                            </div>\n                        </div>\n                    )}\n                </ModalContent>\n                <ModalFooter>\n                    <Button onClick={handleClose} disabled={submitting}>\n                        {c('Action').t`Cancel`}\n                    </Button>\n                    <Button loading={submitting} type=\"submit\" color=\"norm\">\n                        {c('Action').t`Save`}\n                    </Button>\n                </ModalFooter>\n            </Modal>\n        </>\n    );\n};\n\nexport default SubUserEditModal;\n","import { FormEvent, useMemo, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { editMemberInvitation, inviteMember } from '@proton/shared/lib/api/members';\nimport { GIGA, MAIL_APP_NAME, MEMBER_ROLE } from '@proton/shared/lib/constants';\nimport { emailValidator, requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Domain, Member, Organization } from '@proton/shared/lib/interfaces';\nimport clamp from '@proton/utils/clamp';\n\nimport {\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalStateProps,\n    useFormErrors,\n} from '../../components';\nimport { useApi, useEventManager, useNotifications } from '../../hooks';\nimport MemberStorageSelector, { getStorageRange, getTotalStorage } from './MemberStorageSelector';\n\ninterface Props extends ModalStateProps {\n    organization?: Organization;\n    domains: Domain[];\n    member: Member | null | undefined;\n}\n\nconst UserInviteOrEditModal = ({ organization, domains, member, ...modalState }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const [submitting, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n    const { validator, onFormSubmit } = useFormErrors();\n    const totalStorage = getTotalStorage(member ?? {}, organization);\n    const storageRange = getStorageRange(member ?? {}, organization);\n    const storageSizeUnit = GIGA;\n    const isEditing = !!member?.ID;\n\n    const initialModel = useMemo(\n        () => ({\n            address: '',\n            storage: member ? member.MaxSpace : clamp(500 * GIGA, storageRange.min, storageRange.max),\n            vpn: !!member?.MaxVPN,\n            admin: member?.Role === MEMBER_ROLE.ORGANIZATION_ADMIN,\n        }),\n        [member]\n    );\n    const [model, setModel] = useState(initialModel);\n\n    const handleClose = () => {\n        if (submitting) {\n            return;\n        }\n\n        modalState.onClose();\n    };\n\n    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) => {\n        setModel({ ...model, [key]: value });\n    };\n\n    const sendInvitation = async () => {\n        await api(inviteMember(model.address, model.storage));\n        createNotification({ text: c('Success').t`Invitation sent` });\n    };\n\n    const editInvitation = async () => {\n        let updated = false;\n        await api(editMemberInvitation(member!.ID, model.storage));\n        updated = true;\n        if (updated) {\n            createNotification({ text: c('familyOffer_2023:Success').t`Member updated` });\n        }\n    };\n\n    const handleSubmit = async () => {\n        if (isEditing) {\n            await editInvitation();\n        } else {\n            await sendInvitation();\n        }\n        await call();\n        modalState.onClose();\n    };\n\n    const mailFieldValidator = !isEditing ? [requiredValidator(model.address), emailValidator(model.address)] : [];\n    const modalTitle = isEditing\n        ? c('familyOffer_2023:Title').t`Edit user storage`\n        : c('familyOffer_2023:Title').t`Invite a user`;\n    const modalDescription = isEditing\n        ? c('familyOffer_2023:Info').t`You can increase or reduce the storage for this user.`\n        : c('familyOffer_2023:Info')\n              .t`If the user already has a ${MAIL_APP_NAME} address, enter it here. Otherwise they need to create an account first.`;\n\n    return (\n        <Modal\n            as=\"form\"\n            size=\"large\"\n            {...modalState}\n            onClose={handleClose}\n            noValidate\n            onSubmit={(event: FormEvent) => {\n                event.preventDefault();\n                event.stopPropagation();\n                if (!onFormSubmit()) {\n                    return;\n                }\n                void withLoading(handleSubmit());\n            }}\n        >\n            <ModalHeader title={modalTitle} />\n            <ModalContent>\n                <p className=\"color-weak\">{modalDescription}</p>\n\n                {!isEditing && (\n                    <InputFieldTwo\n                        id=\"email-address\"\n                        type=\"email\"\n                        autoCapitalize=\"off\"\n                        autoComplete=\"off\"\n                        autoCorrect=\"off\"\n                        value={model.address}\n                        error={validator(mailFieldValidator)}\n                        onValue={handleChange('address')}\n                        label={c('Label').t`Email address`}\n                        placeholder=\"thomas.anderson@proton.me\"\n                        disableChange={submitting}\n                        autoFocus\n                    />\n                )}\n\n                <MemberStorageSelector\n                    value={model.storage}\n                    disabled={submitting}\n                    sizeUnit={storageSizeUnit}\n                    range={storageRange}\n                    totalStorage={totalStorage}\n                    onChange={handleChange('storage')}\n                />\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={handleClose} disabled={submitting}>\n                    {c('Action').t`Cancel`}\n                </Button>\n                <Button loading={submitting} type=\"submit\" color=\"norm\">\n                    {isEditing ? c('Action').t`Save` : c('Action').t`Invite`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default UserInviteOrEditModal;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { deleteMember } from '@proton/shared/lib/api/members';\nimport { BRAND_NAME } from '@proton/shared/lib/constants';\nimport { MEMBER_STATE, Member, Organization } from '@proton/shared/lib/interfaces';\n\nimport { ModalProps, Prompt } from '../../components';\nimport { useApi, useEventManager, useNotifications } from '../../hooks';\n\ninterface Props extends ModalProps {\n    member: Member | undefined;\n    organization?: Organization;\n}\n\nconst UserRemoveModal = ({ member: initialMember, organization, ...rest }: Props) => {\n    const api = useApi();\n    const [member] = useState(initialMember!);\n    const { call } = useEventManager();\n    const [submitting, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n\n    const isInvitationPending = !!(member.State === MEMBER_STATE.STATUS_INVITED);\n\n    const handleClose = () => {\n        if (submitting) {\n            return undefined;\n        }\n        rest?.onClose?.();\n    };\n\n    const organizationName = organization?.Name || '';\n    const handleDelete = async () => {\n        if (!member?.ID) {\n            createNotification({\n                text: c('familyOffer_2023:Success').t`An error occurred, please try again`,\n                type: 'error',\n            });\n            return;\n        }\n\n        await api(deleteMember(member?.ID));\n        await call();\n        rest?.onClose?.();\n        createNotification({\n            // translator: Success message when a user has been removed from an organization. Looks like: 'John Doe has been removed from Bernie's Family'\n            text: c('familyOffer_2023:Success').t`${member.Name} has been removed from ${organizationName}`,\n        });\n    };\n\n    const description = isInvitationPending\n        ? // translator: Info message when a user has been invited to an organization. Looks like: 'The invitation will be cancelled and the user won't be able to join Bernie's Family.'\n          c('familyOffer_2023:Info')\n              .t`The invitation will be cancelled and the user won't be able to join ${organizationName}.`\n        : c('familyOffer_2023:Info')\n              .t`The user's account will be moved to a ${BRAND_NAME} Unlimited plan for a 30-day free trial*.`;\n\n    return (\n        <Prompt\n            {...rest}\n            title={c('Title').t`Remove user?`}\n            footnote={isInvitationPending ? undefined : c('familyOffer_2023:Info').t`*Only one free trial per user.`}\n            buttons={[\n                <Button\n                    color=\"danger\"\n                    loading={submitting}\n                    onClick={() => {\n                        void withLoading(handleDelete);\n                    }}\n                >{c('Action').t`Remove`}</Button>,\n                <Button onClick={handleClose} disabled={submitting}>{c('Action').t`Cancel`}</Button>,\n            ]}\n        >\n            <p>{description}</p>\n        </Prompt>\n    );\n};\n\nexport default UserRemoveModal;\n","import { CSSProperties, JSX } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Info, TableCell } from '@proton/components/components';\nimport { adminTooltipText } from '@proton/components/containers/members/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport isTruthy from '@proton/utils/isTruthy';\n\ntype HeaderCellItem = {\n    key: string;\n    node: string | JSX.Element;\n    className?: string;\n    style?: CSSProperties;\n};\n\ninterface Props {\n    useEmail?: boolean;\n    showFeaturesColumn?: boolean;\n}\n\nconst UsersAndAddressesSectionHeader = ({ useEmail, showFeaturesColumn }: Props) => {\n    const addressesTitle = useEmail\n        ? c('Title header for members table').t`Email`\n        : c('Title header for members table').t`Addresses`;\n\n    const headerCells: HeaderCellItem[] = [\n        { key: 'name', node: c('Title header for members table').t`Name`, className: 'w-3/10' },\n        {\n            key: 'role',\n            node: (\n                <div className=\"flex gap-2 flex *:flex items-center\">\n                    <span>{c('Title header for members table').t`Role`}</span>\n                    <span className=\"hidden md:inline\">\n                        <Info title={adminTooltipText} url={getKnowledgeBaseUrl('/user-roles')} />\n                    </span>\n                </div>\n            ),\n            className: 'w-1/6',\n        },\n        {\n            key: 'addresses',\n            node: (\n                <>\n                    <span className=\"text-ellipsis inline-block align-bottom max-w-full\" title={addressesTitle}>\n                        {addressesTitle}\n                    </span>\n                </>\n            ),\n            className: 'w-1/4',\n        },\n        showFeaturesColumn && {\n            key: 'features',\n            node: (\n                <>\n                    <span\n                        className=\"text-ellipsis inline-block align-bottom max-w-full\"\n                        title={c('Title header for members table').t`Features`}\n                    >{c('Title header for members table').t`Features`}</span>\n                </>\n            ),\n            className: 'w-1/4',\n        },\n        { key: 'actions', node: '', className: 'w-1/6' },\n    ].filter(isTruthy);\n\n    return (\n        <>\n            {headerCells.map(({ key, node, className = '' }) => (\n                <TableCell key={key} className={className} type=\"header\">\n                    {node}\n                </TableCell>\n            ))}\n        </>\n    );\n};\n\nexport default UsersAndAddressesSectionHeader;\n","import { MutableRefObject, useMemo, useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { useMemberAddresses } from '@proton/account';\nimport { getDomainError } from '@proton/account/members/validateAddUser';\nimport { Avatar, Button } from '@proton/atoms';\nimport { revokeSessions } from '@proton/shared/lib/api/memberSessions';\nimport { removeMember, updateRole } from '@proton/shared/lib/api/members';\nimport { APP_NAMES, MEMBER_ROLE, MEMBER_SUBSCRIBER, MEMBER_TYPE } from '@proton/shared/lib/constants';\nimport { getAvailableAddressDomains } from '@proton/shared/lib/helpers/address';\nimport { hasOrganizationSetup, hasOrganizationSetupWithKeys } from '@proton/shared/lib/helpers/organization';\nimport { getInitials, normalize } from '@proton/shared/lib/helpers/string';\nimport {\n    getHasPassB2BPlan,\n    getHasVpnOrPassB2BPlan,\n    hasBundlePro,\n    hasFamily,\n    hasMailPro,\n    hasNewVisionary,\n    hasVisionary,\n} from '@proton/shared/lib/helpers/subscription';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { EnhancedMember, MEMBER_STATE, Member } from '@proton/shared/lib/interfaces';\nimport {\n    getIsDomainActive,\n    getOrganizationKeyInfo,\n    validateOrganizationKey,\n} from '@proton/shared/lib/organization/helper';\nimport clsx from '@proton/utils/clsx';\n\nimport {\n    Badge,\n    Block,\n    Info,\n    SearchInput,\n    Table,\n    TableBody,\n    TableCell,\n    TableRow,\n    useModalState,\n} from '../../../components';\nimport {\n    useAddresses,\n    useApi,\n    useCustomDomains,\n    useEventManager,\n    useGetOrganizationKey,\n    useMembers,\n    useNotifications,\n    useOrganization,\n    useOrganizationKey,\n    useProtonDomains,\n    useSubscription,\n    useUser,\n} from '../../../hooks';\nimport { SettingsParagraph, SettingsSectionWide, useAccountSpotlights } from '../../account';\nimport { SetupOrgSpotlight } from '../../account/spotlights/passB2bOnboardingSpotlights/PassB2bOnboardingSpotlights';\nimport { AddressModal } from '../../addresses';\nimport CreateMissingKeysAddressModal from '../../addresses/missingKeys/CreateMissingKeysAddressModal';\nimport useOrganizationModals from '../../organization/useOrganizationModals';\nimport { SUBSCRIPTION_STEPS, useSubscriptionModal } from '../../payments/subscription';\nimport ChangeMemberPasswordModal from '../ChangeMemberPasswordModal';\nimport InviteUserCreateSubUserModal from '../InviteUserCreateSubUserModal';\nimport LoginMemberModal from '../LoginMemberModal';\nimport MemberActions from '../MemberActions';\nimport MemberAddresses from '../MemberAddresses';\nimport MemberFeatures from '../MemberFeatures';\nimport MemberRole from '../MemberRole';\nimport SubUserCreateModal from '../SubUserCreateModal';\nimport SubUserDeleteModal from '../SubUserDeleteModal';\nimport SubUserEditModal from '../SubUserEditModal';\nimport UserInviteOrEditModal from '../UserInviteOrEditModal';\nimport UserRemoveModal from '../UserRemoveModal';\nimport UsersAndAddressesSectionHeader from './UsersAndAddressesSectionHeader';\n\nconst UsersAndAddressesSection = ({ app, onceRef }: { app: APP_NAMES; onceRef: MutableRefObject<boolean> }) => {\n    const [organization, loadingOrganization] = useOrganization();\n    const [organizationKey] = useOrganizationKey();\n    const getOrganizationKey = useGetOrganizationKey();\n    const [customDomains, loadingCustomDomains] = useCustomDomains();\n    const [{ protonDomains, premiumDomains }] = useProtonDomains();\n    const [members, loadingMembers] = useMembers();\n    const [subscription] = useSubscription();\n    const [addresses] = useAddresses();\n    const [user] = useUser();\n    const [openSubscriptionModal] = useSubscriptionModal();\n    const { value: memberAddressesMap } = useMemberAddresses({ members, partial: true });\n    const [keywords, setKeywords] = useState('');\n    const [tmpMemberID, setTmpMemberID] = useState<string | null>(null);\n    const api = useApi();\n    const { call } = useEventManager();\n    const hasReachedLimit = organization?.InvitationsRemaining === 0;\n    const hasSetupOrganization = hasOrganizationSetup(organization);\n    const hasSetupOrganizationWithKeys = hasOrganizationSetupWithKeys(organization);\n    const organizationModals = useOrganizationModals(onceRef);\n\n    const {\n        passOnboardingSpotlights: { setupOrgSpotlight },\n    } = useAccountSpotlights();\n\n    const hasPassB2BPlan = getHasPassB2BPlan(subscription);\n    const hasVpnOrPassB2BPlan = getHasVpnOrPassB2BPlan(subscription);\n    const hasInboxB2BPlan = hasBundlePro(subscription) || hasMailPro(subscription);\n\n    const useEmail = hasVpnOrPassB2BPlan;\n    const allowStorageConfiguration = !hasVpnOrPassB2BPlan;\n    const allowVpnAccessConfiguration = !hasVpnOrPassB2BPlan;\n    const allowPrivateMemberConfiguration = !hasVpnOrPassB2BPlan;\n\n    const showMultipleUserUploadButton = hasVpnOrPassB2BPlan;\n    const showAddressesSection = !hasVpnOrPassB2BPlan;\n    const showFeaturesColumn = !hasVpnOrPassB2BPlan;\n\n    const canInviteProtonUsers = hasNewVisionary(subscription) || hasFamily(subscription);\n    const { createNotification } = useNotifications();\n\n    const cleanOption = {\n        onExit: () => setTmpMemberID(null),\n    };\n\n    const [addAddressModalProps, setAddAddressModalOpen, renderAddAddressModal] = useModalState();\n    const [subUserCreateModalProps, setSubUserCreateModalOpen, renderSubUserCreateModal] = useModalState();\n    const [subUserEditModalProps, setSubUserEditModalOpen, renderSubUserEditModal] = useModalState(cleanOption);\n    const [loginMemberModalProps, setLoginMemberModalOpen, renderLoginMemberModal] = useModalState(cleanOption);\n    const [changeMemberPasswordModalProps, setChangeMemberPasswordModalOpen, renderChangeMemberPasswordModal] =\n        useModalState(cleanOption);\n    const [subUserDeleteModalProps, setSubUserDeleteModalOpen, renderSubUserDeleteModal] = useModalState(cleanOption);\n    const [userRemoveModalProps, setUserRemoveModalOpen, renderUserRemoveModal] = useModalState(cleanOption);\n    const [userSetupModal, setUserSetupModal, renderUserSetupModal] = useModalState(cleanOption);\n    const [inviteOrCreateUserModalProps, setInviteOrCreateUserModalOpen, renderInviteOrCreateUserModal] =\n        useModalState(cleanOption);\n    const [userInviteOrEditModalProps, setUserInviteOrEditModalOpen, renderUserInviteOrEditModal] =\n        useModalState(cleanOption);\n\n    const verifiedDomains = useMemo(() => (customDomains || []).filter(getIsDomainActive), [customDomains]);\n\n    const handleSearch = (value: string) => setKeywords(value);\n\n    const membersSelected = useMemo(() => {\n        if (!members) {\n            return [];\n        }\n        if (!keywords) {\n            return members;\n        }\n\n        const normalizedWords = normalize(keywords, true);\n\n        return members.filter((member) => {\n            const memberAddresses = memberAddressesMap?.[member.ID] || [];\n            const addressMatch = memberAddresses?.some((address) =>\n                normalize(address.Email, true).includes(normalizedWords)\n            );\n            const nameMatch = normalize(member.Name, true).includes(normalizedWords);\n\n            return addressMatch || nameMatch;\n        });\n    }, [keywords, members]);\n\n    const handleDeleteUserConfirm = async (member: Member) => {\n        if (member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN) {\n            await api(updateRole(member.ID, MEMBER_ROLE.ORGANIZATION_MEMBER));\n        }\n        await api(removeMember(member.ID));\n        await call();\n        createNotification({ text: c('Success message').t`User deleted` });\n    };\n\n    const handleSetupUser = (member: EnhancedMember) => {\n        setTmpMemberID(member.ID);\n        setUserSetupModal(true);\n    };\n\n    const handleDeleteUser = (member: EnhancedMember) => {\n        setTmpMemberID(member.ID);\n\n        //  We can remove members if the user is a Proton member (excluding logged user)\n        if (canInviteProtonUsers && member.Type === MEMBER_TYPE.PROTON && !member.Self) {\n            setUserRemoveModalOpen(true);\n        } else {\n            setSubUserDeleteModalOpen(true);\n        }\n    };\n\n    const handleRevokeUserSessions = async (member: EnhancedMember) => {\n        await api(revokeSessions(member.ID));\n        await call();\n        createNotification({ text: c('Success message').t`Sessions revoked` });\n    };\n\n    const handleInviteUser = () => {\n        setUserInviteOrEditModalOpen(true);\n    };\n\n    const handleAddAddress = () => {\n        setAddAddressModalOpen(true);\n    };\n\n    const handleEditUser = (member: EnhancedMember) => {\n        setTmpMemberID(member.ID);\n\n        // We can open the invite modal if the user is a Proton member (excluding logged user)\n        if (\n            canInviteProtonUsers &&\n            member.Type === MEMBER_TYPE.PROTON &&\n            !member.Self &&\n            member.State === MEMBER_STATE.STATUS_INVITED\n        ) {\n            setUserInviteOrEditModalOpen(true);\n        } else {\n            setSubUserEditModalOpen(true);\n        }\n    };\n\n    const handleAddUser = () => {\n        // Visionary can either create a sub user or invite existing users\n        if (hasVisionary(subscription) || hasNewVisionary(subscription) || hasFamily(subscription)) {\n            setInviteOrCreateUserModalOpen(true);\n            return;\n        }\n\n        if (!useEmail && !verifiedDomains.length) {\n            createNotification({ text: getDomainError(), type: 'error' });\n            return;\n        }\n\n        setSubUserCreateModalOpen(true);\n    };\n\n    const handleLoginUser = async (member: EnhancedMember) => {\n        const organizationKey = await getOrganizationKey();\n        const error = validateOrganizationKey(getOrganizationKeyInfo(organization, organizationKey, addresses));\n        if (error) {\n            return createNotification({ type: 'error', text: error });\n        }\n        setTmpMemberID(member.ID);\n        setLoginMemberModalOpen(true);\n    };\n\n    const handleChangeMemberPassword = async (member: EnhancedMember) => {\n        const organizationKey = await getOrganizationKey();\n        const error = validateOrganizationKey(getOrganizationKeyInfo(organization, organizationKey, addresses));\n        if (error) {\n            return createNotification({ type: 'error', text: error });\n        }\n        setTmpMemberID(member.ID);\n        setChangeMemberPasswordModalOpen(true);\n    };\n\n    const handleGetMoreLicense = () => {\n        openSubscriptionModal({\n            step: SUBSCRIPTION_STEPS.CHECKOUT_WITH_CUSTOMIZATION,\n            disablePlanSelection: true,\n            metrics: {\n                /**\n                 * The `vpn` in `vpn-um-get-more` is unimportant.\n                 * The intention is to observe the user journey, not the specific plan the journey is for.\n                 * However changing this would require a new metric schema version.\n                 */\n                source: 'vpn-um-get-more',\n            },\n        });\n    };\n\n    // Members for which addresses can be created\n    const filteredMembers = (() => {\n        if (useEmail) {\n            return members;\n        }\n\n        return members?.filter((member) => {\n            const availableAddressDomains = getAvailableAddressDomains({\n                user,\n                member,\n                protonDomains,\n                customDomains,\n                premiumDomains,\n            });\n\n            return availableAddressDomains.length;\n        });\n    })();\n\n    const userFound = membersSelected.length;\n\n    const tableLabel = [\n        '',\n        <>\n            <span className=\"mr-2\">{c('Title header for members table').t`Role`}</span>\n            <Info url={getKnowledgeBaseUrl('/user-roles')} />\n        </>,\n        c('Title header for members table').t`Addresses`,\n        c('Title header for members table').t`Features`,\n        '',\n    ];\n\n    const disableInviteUserButton = loadingOrganization || loadingCustomDomains || hasReachedLimit;\n\n    const disableAddUserButton =\n        loadingOrganization ||\n        loadingCustomDomains ||\n        (organization?.UsedMembers || 0) >= (organization?.MaxMembers || 0);\n    const loadingAddAddresses = loadingOrganization || loadingCustomDomains || loadingMembers;\n    const selfMember = members?.find((member) => member.Self);\n\n    const settingsParagraphContent = (() => {\n        if (hasFamily(subscription)) {\n            return c('familyOffer_2023:Info for members section')\n                .t`Add, remove, and make changes to user accounts in your family group.`;\n        }\n\n        const defaultString = c('familyOffer_2023:Info for members section')\n            .t`Add, remove, and make changes to user accounts in your organization.`;\n\n        if (hasVpnOrPassB2BPlan || hasInboxB2BPlan) {\n            const maxMembers = organization?.MaxMembers || 0;\n            const usedMembers = organization?.UsedMembers || 0;\n            return (\n                <>\n                    {c('Info').ngettext(\n                        msgid`You are currently using ${usedMembers} of your ${maxMembers} available user license.`,\n                        `You are currently using ${usedMembers} of your ${maxMembers} available user licenses.`,\n                        maxMembers\n                    )}\n                    {user.canPay && selfMember?.Subscriber === MEMBER_SUBSCRIBER.PAYER && (\n                        <Button shape=\"outline\" color=\"norm\" size=\"small\" onClick={handleGetMoreLicense}>\n                            {c('Action').t`Get more licenses`}\n                        </Button>\n                    )}\n                </>\n            );\n        }\n\n        return defaultString;\n    })();\n\n    const tmpMember = members?.find((member) => tmpMemberID === member.ID);\n\n    return (\n        <SettingsSectionWide>\n            {organizationModals.info}\n            {organizationModals.modals}\n            <SettingsParagraph large className=\"flex items-baseline mb-6 gap-2\">\n                {settingsParagraphContent}\n            </SettingsParagraph>\n            <Block className=\"flex items-start\">\n                {renderUserSetupModal && (\n                    <CreateMissingKeysAddressModal member={tmpMember} addressesToGenerate={[]} {...userSetupModal} />\n                )}\n                {renderAddAddressModal && filteredMembers && (\n                    <AddressModal members={filteredMembers} {...addAddressModalProps} />\n                )}\n                {renderSubUserDeleteModal && (\n                    <SubUserDeleteModal\n                        member={tmpMember}\n                        onDelete={handleDeleteUserConfirm}\n                        {...subUserDeleteModalProps}\n                    />\n                )}\n                {renderUserRemoveModal && (\n                    <UserRemoveModal member={tmpMember} organization={organization} {...userRemoveModalProps} />\n                )}\n                {renderSubUserCreateModal && (\n                    <SubUserCreateModal\n                        organization={organization}\n                        verifiedDomains={verifiedDomains}\n                        app={app}\n                        onSuccess={setupOrgSpotlight.close}\n                        useEmail={useEmail}\n                        optionalName={hasVpnOrPassB2BPlan}\n                        allowStorageConfiguration={allowStorageConfiguration}\n                        allowVpnAccessConfiguration={allowVpnAccessConfiguration}\n                        allowPrivateMemberConfiguration={allowPrivateMemberConfiguration}\n                        showMultipleUserUploadButton={showMultipleUserUploadButton}\n                        disableStorageValidation={!allowStorageConfiguration}\n                        disableDomainValidation={useEmail}\n                        disableAddressValidation={hasPassB2BPlan}\n                        {...subUserCreateModalProps}\n                    />\n                )}\n                {renderSubUserEditModal && tmpMember && (\n                    <SubUserEditModal\n                        member={tmpMember}\n                        allowStorageConfiguration={allowStorageConfiguration}\n                        allowVpnAccessConfiguration={allowVpnAccessConfiguration}\n                        allowPrivateMemberConfiguration={allowPrivateMemberConfiguration}\n                        showAddressesSection={showAddressesSection}\n                        {...subUserEditModalProps}\n                    />\n                )}\n                {renderUserInviteOrEditModal && (\n                    <UserInviteOrEditModal\n                        member={tmpMember}\n                        organization={organization}\n                        domains={verifiedDomains}\n                        {...userInviteOrEditModalProps}\n                    />\n                )}\n                {renderLoginMemberModal && tmpMember && (\n                    <LoginMemberModal app={app} member={tmpMember} {...loginMemberModalProps} />\n                )}\n                {renderChangeMemberPasswordModal && tmpMember && (\n                    <ChangeMemberPasswordModal member={tmpMember} {...changeMemberPasswordModalProps} />\n                )}\n                {renderInviteOrCreateUserModal && (\n                    <InviteUserCreateSubUserModal\n                        organization={organization}\n                        verifiedDomains={verifiedDomains}\n                        onInviteUser={handleInviteUser}\n                        app={app}\n                        {...inviteOrCreateUserModalProps}\n                    />\n                )}\n                <div className=\"flex items-center mb-2 gap-2 mr-4\">\n                    {hasVpnOrPassB2BPlan ? (\n                        <>\n                            {hasSetupOrganizationWithKeys && (\n                                <SetupOrgSpotlight app={app}>\n                                    <Button color=\"norm\" disabled={disableAddUserButton} onClick={handleAddUser}>\n                                        {c('Action').t`Add user`}\n                                    </Button>\n                                </SetupOrgSpotlight>\n                            )}\n                        </>\n                    ) : (\n                        <>\n                            {hasSetupOrganization && (\n                                <Button color=\"norm\" disabled={disableInviteUserButton} onClick={handleInviteUser}>\n                                    {c('Action').t`Invite user`}\n                                </Button>\n                            )}\n\n                            {hasSetupOrganizationWithKeys && (\n                                <Button color=\"norm\" disabled={disableAddUserButton} onClick={handleAddUser}>\n                                    {c('Action').t`Add user`}\n                                </Button>\n                            )}\n\n                            {/* Only family and visionary can invite existing Proton users */}\n                            {canInviteProtonUsers &&\n                                (hasReachedLimit ? (\n                                    <Info\n                                        className=\"color-danger\"\n                                        title={c('familyOffer_2023:Family plan')\n                                            .t`You have reached the limit of 10 accepted invitations in 6 months.`}\n                                    />\n                                ) : (\n                                    <Info\n                                        title={c('familyOffer_2023:Family plan')\n                                            .t`Only 10 accepted invitations are allowed in a 6-month period.`}\n                                    />\n                                ))}\n\n                            <Button shape=\"outline\" disabled={loadingAddAddresses} onClick={handleAddAddress}>\n                                {c('Action').t`Add address`}\n                            </Button>\n                        </>\n                    )}\n                </div>\n                <div className=\"ml-0 lg:ml-auto mb-2 w-full lg:w-custom\" style={{ '--lg-w-custom': '24em' }}>\n                    <SearchInput\n                        onChange={handleSearch}\n                        placeholder={c('Placeholder').t`Search for a user or address`}\n                        value={keywords}\n                        aria-label={c('Placeholder').t`Search users`}\n                    />\n                </div>\n            </Block>\n            <span className=\"sr-only\" aria-live=\"polite\" aria-atomic=\"true\">\n                {c('Info').ngettext(msgid`${userFound} user found`, `${userFound} users found`, userFound)}\n            </span>\n\n            <Table hasActions responsive=\"cards\" data-testid=\"users-and-addresses-table\">\n                <thead>\n                    <tr>\n                        <UsersAndAddressesSectionHeader showFeaturesColumn={showFeaturesColumn} useEmail={useEmail} />\n                    </tr>\n                </thead>\n                <TableBody loading={loadingMembers} colSpan={showFeaturesColumn ? 5 : 4}>\n                    {membersSelected.map((member) => {\n                        const memberAddresses = memberAddressesMap?.[member.ID] || [];\n                        const isInvitationPending = !!(member.State === MEMBER_STATE.STATUS_INVITED);\n\n                        const memberName = (() => {\n                            if (hasFamily(subscription) && member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN) {\n                                return member?.Addresses?.[0]?.Email || member.Name;\n                            }\n\n                            return member.Name;\n                        })();\n                        return (\n                            <TableRow\n                                key={member.ID}\n                                labels={tableLabel}\n                                className={clsx('align-top', isInvitationPending && 'color-weak')}\n                            >\n                                <TableCell style={{ verticalAlign: 'baseline' }}>\n                                    <div className=\"flex items-center gap-3\">\n                                        <Avatar className=\"shrink-0 text-rg\" color=\"weak\">\n                                            {getInitials(memberName)}\n                                        </Avatar>\n                                        <div\n                                            className=\"text-ellipsis flex-1 min-w-custom\"\n                                            style={{ '--min-w-custom': '6rem' }}\n                                            data-testid=\"users-and-addresses-table:memberName\"\n                                            title={memberName}\n                                        >\n                                            {memberName}\n                                        </div>\n                                        <div className=\"flex items-center gap-1\">\n                                            {allowPrivateMemberConfiguration &&\n                                                !hasFamily(subscription) &&\n                                                Boolean(member.Private) && (\n                                                    <Badge\n                                                        type=\"origin\"\n                                                        className=\"rounded-sm\"\n                                                        data-testid=\"users-and-addresses-table:memberIsPrivate\"\n                                                    >\n                                                        {c('Private Member').t`private`}\n                                                    </Badge>\n                                                )}\n                                            {member['2faStatus'] > 0 && (\n                                                <Badge type=\"origin\" className=\"rounded-sm\">\n                                                    {c('Enabled 2FA').t`2FA`}\n                                                </Badge>\n                                            )}\n                                            {member.SSO > 0 && (\n                                                <Badge\n                                                    type=\"success\"\n                                                    className=\"rounded-sm\"\n                                                    tooltip={c('Users table: single sign-on tooltip')\n                                                        .t`SSO user provided by your identity provider`}\n                                                >\n                                                    {c('Users table: single sign-on enabled').t`SSO`}\n                                                </Badge>\n                                            )}\n                                        </div>\n                                    </div>\n                                </TableCell>\n                                <TableCell\n                                    className=\"text-cut\"\n                                    data-testid=\"users-and-addresses-table:memberRole\"\n                                    style={{ verticalAlign: 'baseline' }}\n                                >\n                                    <div className=\"flex flex-column flex-nowrap\">\n                                        <MemberRole member={member} />\n                                        {isInvitationPending && (\n                                            <span>\n                                                <Badge type=\"origin\" className=\"rounded-sm color-weak\">{c(\n                                                    'familyOffer_2023:Family plan'\n                                                ).t`Pending`}</Badge>\n                                            </span>\n                                        )}\n                                    </div>\n                                </TableCell>\n                                <TableCell style={{ verticalAlign: 'baseline' }}>\n                                    <div>\n                                        {member.State && member.State === MEMBER_STATE.STATUS_INVITED ? (\n                                            <p className=\"m-0 text-ellipsis\">{member.Name}</p>\n                                        ) : (\n                                            <MemberAddresses addresses={memberAddresses} />\n                                        )}\n                                    </div>\n                                </TableCell>\n                                {showFeaturesColumn && (\n                                    <TableCell>\n                                        <MemberFeatures member={member} organization={organization} />\n                                    </TableCell>\n                                )}\n                                <TableCell style={{ verticalAlign: 'baseline' }}>\n                                    <MemberActions\n                                        user={user}\n                                        organizationKey={organizationKey}\n                                        onEdit={handleEditUser}\n                                        onDelete={handleDeleteUser}\n                                        onSetup={handleSetupUser}\n                                        onRevoke={handleRevokeUserSessions}\n                                        onLogin={handleLoginUser}\n                                        onChangePassword={handleChangeMemberPassword}\n                                        member={member}\n                                        addresses={memberAddresses}\n                                        organization={organization}\n                                        disableMemberSignIn={hasVpnOrPassB2BPlan}\n                                    />\n                                </TableCell>\n                            </TableRow>\n                        );\n                    })}\n                </TableBody>\n            </Table>\n        </SettingsSectionWide>\n    );\n};\n\nexport default UsersAndAddressesSection;\n","import React, { ComponentPropsWithRef, ReactNode } from 'react';\n\ninterface Props extends ComponentPropsWithRef<'div'> {\n    imageProps?: ComponentPropsWithRef<'img'>;\n    children: ReactNode;\n}\n\nconst EmptyViewContainer = ({ imageProps, children, ...containerProps }: Props) => {\n    return (\n        <div className=\"m-auto p-11\" {...containerProps}>\n            <figure className=\"flex-1 text-center p-4\">\n                {imageProps && <img className=\"h-auto\" {...imageProps} alt={imageProps.alt || ''} />}\n                <figcaption className=\"mt-8\">{children}</figcaption>\n            </figure>\n        </div>\n    );\n};\n\nexport default EmptyViewContainer;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Icon } from '@proton/components/components';\nimport clsx from '@proton/utils/clsx';\n\nexport const ButtonNumberInput = ({\n    value,\n    onChange,\n    id,\n    min = 0,\n    max = 999,\n    step = 1,\n    disabled = false,\n}: {\n    step?: number;\n    id: string;\n    min?: number;\n    max?: number;\n    value: number;\n    disabled?: boolean;\n    onChange?: (newValue: number) => void;\n}) => {\n    const [tmpValue, setTmpValue] = useState<number | undefined>(value);\n\n    const getIsValidValue = (newValue?: number) => {\n        return newValue !== undefined && newValue >= min && newValue <= max && newValue % step === 0;\n    };\n\n    const isDecDisabled = disabled || !getIsValidValue((tmpValue || 0) - step);\n    const isIncDisabled = disabled || !getIsValidValue((tmpValue || 0) + step);\n\n    const isValidTmpValue = getIsValidValue(tmpValue);\n\n    return (\n        <div className=\"border rounded shrink-0 flex flex-nowrap\">\n            <button\n                type=\"button\"\n                title={c('Action').t`Decrease`}\n                className={clsx(['p-2 flex', isDecDisabled && 'color-disabled'])}\n                disabled={isDecDisabled}\n                onClick={() => {\n                    if (!isValidTmpValue || tmpValue === undefined) {\n                        return;\n                    }\n                    const newValue = tmpValue - step;\n                    setTmpValue?.(newValue);\n                    onChange?.(newValue);\n                }}\n            >\n                <Icon name=\"minus\" alt={c('Action').t`Decrease`} className=\"m-auto\" />\n            </button>\n            <label htmlFor={id} className=\"my-2 flex\">\n                <input\n                    autoComplete=\"off\"\n                    min={min}\n                    max={max}\n                    value={tmpValue}\n                    id={id}\n                    className=\"w-custom border-left border-right text-center\"\n                    style={{ '--w-custom': '6em' }}\n                    onBlur={() => {\n                        if (!isValidTmpValue) {\n                            // Revert to the latest valid value upon blur\n                            setTmpValue(value);\n                        }\n                    }}\n                    onChange={({ target: { value: newValue } }) => {\n                        if (newValue === '') {\n                            setTmpValue?.(undefined);\n                            return;\n                        }\n                        const newIntValue = parseInt(newValue, 10);\n                        setTmpValue?.(newIntValue);\n                        if (getIsValidValue(newIntValue)) {\n                            onChange?.(newIntValue);\n                        }\n                    }}\n                />\n            </label>\n            <button\n                type=\"button\"\n                title={c('Action').t`Increase`}\n                className={clsx(['p-2 flex', isIncDisabled && 'color-disabled'])}\n                disabled={isIncDisabled}\n                onClick={() => {\n                    if (!isValidTmpValue || tmpValue === undefined) {\n                        return;\n                    }\n                    const newValue = tmpValue + step;\n                    setTmpValue?.(newValue);\n                    onChange?.(newValue);\n                }}\n            >\n                <Icon name=\"plus\" alt={c('Action').t`Increase`} className=\"m-auto\" />\n            </button>\n        </div>\n    );\n};\n","import { Attributes, ImgHTMLAttributes } from 'react';\n\nimport { getLocalizedCountryByAbbr } from '@proton/components/helpers/countries';\nimport clsx from '@proton/utils/clsx';\n\nimport { getFlagSvg } from '../flag';\n\nexport const getCountryFlagAndName = (\n    languageOrLanguages: string | readonly string[],\n    countryCode?: string,\n    label?: string,\n    rest: Attributes & ImgHTMLAttributes<HTMLImageElement> = {}\n) => {\n    const upperCode = (countryCode || '').toUpperCase();\n    const flag = getFlagSvg(upperCode);\n    const name = getLocalizedCountryByAbbr(upperCode, languageOrLanguages);\n    const classes = rest.className;\n    delete rest.className;\n\n    return [\n        flag && <img width={20} className={clsx(['mx-2 border', classes])} src={flag} alt={name} {...rest} />,\n        label ?? name,\n    ];\n};\n","import { c, msgid } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Field, Icon, Label, Option, Row, SelectTwo } from '@proton/components/components';\nimport { SelectChangeEvent } from '@proton/components/components/selectTwo/select';\nimport { vpnEnterpriseContactUrl } from '@proton/components/containers/payments/subscription/helpers';\nimport { getLocalizedCountryByAbbr } from '@proton/components/helpers/countries';\nimport { MAX_IPS_ADDON } from '@proton/shared/lib/constants';\n\nimport { ButtonNumberInput } from './ButtonNumberInput';\nimport { GatewayDto } from './GatewayDto';\nimport { getCountryFlagAndName } from './getCountryFlagAndName';\n\ninterface Props {\n    singleServer: boolean;\n    countries: readonly string[];\n    ownedCount: number;\n    usedCount: number;\n    addedCount: number;\n    language: string | readonly string[];\n    onUpsell: () => void;\n    specificCountryCount: number;\n    loading?: boolean;\n    needUpsell: boolean;\n    model: GatewayDto;\n    changeModel: (diff: Partial<GatewayDto>) => void;\n}\n\nexport const GatewayCountrySelection = ({\n    singleServer,\n    countries,\n    ownedCount,\n    usedCount,\n    addedCount,\n    language,\n    onUpsell,\n    loading = false,\n    needUpsell,\n    specificCountryCount,\n    model,\n    changeModel,\n}: Props) => {\n    const remainingCount = ownedCount - usedCount;\n    const availableCount = Math.max(0, remainingCount - addedCount);\n    const totalCountExceeded = addedCount > remainingCount;\n    const canBuyMore = ownedCount < MAX_IPS_ADDON;\n\n    const handleCountryChange = ({ value }: SelectChangeEvent<string>) => changeModel({ country: value });\n\n    return singleServer ? (\n        <Row>\n            <Label htmlFor=\"domain\">{c('Label').t`Country`}</Label>\n            <Field>\n                <SelectTwo value={model.country} onChange={handleCountryChange}>\n                    {countries.map((country) => (\n                        <Option\n                            key={country}\n                            value={country}\n                            title={getLocalizedCountryByAbbr(country, language) || country}\n                        >\n                            {getCountryFlagAndName(language, country, undefined, {\n                                key: country + '-country-option-image',\n                            })}\n                        </Option>\n                    ))}\n                </SelectTwo>\n            </Field>\n        </Row>\n    ) : (\n        <>\n            <p className=\"mb-2\">\n                {c('Info').ngettext(\n                    msgid`You have ${availableCount} dedicated server available.`,\n                    `You have ${availableCount} dedicated servers available.`,\n                    availableCount\n                )}\n            </p>\n            {countries.map((country) => (\n                <div\n                    key={'country-' + country}\n                    className=\"flex *:min-size-auto md:flex-nowrap items-center mb-4\"\n                >\n                    <Label htmlFor={'country-number-' + country} className=\"flex-1\">\n                        {getCountryFlagAndName(language, country, undefined, {\n                            key: country + '-country-label-image',\n                        })}\n                    </Label>\n                    <ButtonNumberInput\n                        id={'country-number-' + country}\n                        value={model.quantities?.[country] || 0}\n                        min={0}\n                        max={99}\n                        disabled={loading}\n                        onChange={(newQuantity) => {\n                            const quantities = {\n                                ...model.quantities,\n                                [country]: newQuantity,\n                            };\n                            const mainCountry = Object.keys(quantities).reduce(\n                                (previous, country) =>\n                                    (quantities[country] || 0) > (quantities[previous] || 0) ? country : previous,\n                                'US'\n                            );\n\n                            if (mainCountry !== model.country) {\n                                changeModel({ country: mainCountry });\n                            }\n\n                            changeModel({ quantities });\n                        }}\n                        step={1}\n                    />\n                </div>\n            ))}\n            <Row>\n                {c('Info').t`Want servers in other countries?`}\n                <a href={vpnEnterpriseContactUrl} className=\"ml-1\">{c('Link').t`Contact us`}</a>\n            </Row>\n            {needUpsell && (\n                <>\n                    <Row className=\"rounded p-2 bg-info\">\n                        <div className=\"shrink-0\">\n                            <Icon name=\"info-circle\" />\n                        </div>\n                        <div className=\"ml-2\">\n                            {totalCountExceeded ? (\n                                c('Info')\n                                    .t`Number of dedicated servers you try to assign (${addedCount}) is more than what is still available in your plan (${remainingCount}) as you own ${ownedCount} and you already use ${usedCount}.`\n                            ) : (\n                                <>\n                                    <div>{c('Info')\n                                        .t`Some of your available servers can only be used in specific countries due to recent removals`}</div>\n                                    <div className=\"mt-3\">\n                                        {c('Info')\n                                            .t`You can immediately unlock the setup above by adding ${specificCountryCount} to the number of IP addresses in your plan or reach us for tailor-made solutions.`}\n                                        <a href={vpnEnterpriseContactUrl} className=\"ml-1\">{c('Link').t`Contact us`}</a>\n                                    </div>\n                                </>\n                            )}\n                        </div>\n                    </Row>\n                    <Row>\n                        {canBuyMore && (\n                            <Button\n                                color=\"norm\"\n                                onClick={onUpsell}\n                                title={c('Title').t`Customize the number of IP addresses in your plan`}\n                            >\n                                {c('Action').t`Get more servers`}\n                            </Button>\n                        )}\n                    </Row>\n                </>\n            )}\n            <Row className=\"rounded p-2 bg-weak\">\n                <div className=\"shrink-0\">\n                    <Icon name=\"info-circle\" />\n                </div>\n                <div className=\"ml-2\">\n                    {c('Info').t`We recommend having multiple servers in different locations to provide redundancy.`}\n                </div>\n            </Row>\n        </>\n    );\n};\n\nexport default GatewayCountrySelection;\n","import { c } from 'ttag';\n\nimport { InputFieldTwo } from '@proton/components/components';\nimport { maxLengthValidator, minLengthValidator, requiredValidator } from '@proton/shared/lib/helpers/formValidators';\n\nimport { GatewayDto } from './GatewayDto';\n\ntype GatewayName = Pick<GatewayDto, 'name'>;\n\ninterface Props {\n    model: GatewayName;\n    changeModel: (diff: Partial<GatewayDto>) => void;\n    validator: (validations: string[]) => string;\n}\n\nexport const GatewayNameField = ({ model, changeModel, validator }: Props) => {\n    const noSpaceMessage = c('Info').t`Must not contain spaces.`;\n    const formatMessage = c('Info').t`Must contain only letters, digits, and dashes (-).`;\n    const startWithLetterMessage = c('Info').t`Must start with a letter.`;\n\n    const gatewayNameNoSpaceValidator = (value: string) => (/\\s/.test(value) ? noSpaceMessage : '');\n    const gatewayNameStartWithLetterValidator = (value: string) => (/^[A-Z]/.test(value) ? '' : startWithLetterMessage);\n    const gatewayNameValidator = (value: string) => (/^[A-Z][A-Z0-9-]+$/.test(value) ? '' : formatMessage);\n\n    const name = model.name || '';\n\n    return (\n        <>\n            <InputFieldTwo\n                autoFocus\n                label={c('Label').t`Gateway name`}\n                placeholder=\"MY-COMPANY-OFFICE\"\n                value={name}\n                onValue={(value: string) => {\n                    changeModel({ name: value.toUpperCase() });\n                }}\n                error={validator([\n                    requiredValidator(name),\n                    minLengthValidator(name, 3),\n                    maxLengthValidator(name, 20),\n                    gatewayNameStartWithLetterValidator(name),\n                    gatewayNameNoSpaceValidator(name),\n                    gatewayNameValidator(name),\n                ])}\n            />\n            <div>\n                <ul className=\"pl-4 mt-2 color-weak\">\n                    <li>{c('Info').t`Must be between 3 and 20 characters long.`}</li>\n                    <li>{startWithLetterMessage}</li>\n                    <li>{formatMessage}</li>\n                    <li>{noSpaceMessage}</li>\n                </ul>\n            </div>\n        </>\n    );\n};\n\nexport default GatewayNameField;\n","import { HTMLAttributes, ReactNode, ThHTMLAttributes } from 'react';\n\nimport { Icon, TableCell } from '@proton/components/components';\nimport { SORT_DIRECTION } from '@proton/shared/lib/constants';\nimport noop from '@proton/utils/noop';\n\nconst { ASC, DESC } = SORT_DIRECTION;\n\ninterface SortingTableCellHeaderProps {\n    content: ReactNode;\n    onClick: () => void;\n    direction?: SORT_DIRECTION;\n}\n\nexport const SortingTableCellHeader = ({ content, onClick = noop, direction }: SortingTableCellHeaderProps) => {\n    return (\n        <div className=\"flex-nowrap inline-flex *:self-center\">\n            <span\n                tabIndex={0}\n                role=\"button\"\n                className=\"link mr-2\"\n                onClick={onClick}\n                onKeyDown={(e) => {\n                    if (e.key === 'Enter') {\n                        onClick();\n                    }\n                }}\n            >\n                {content}\n            </span>\n            {direction === ASC || direction === DESC ? (\n                <Icon name=\"chevron-down\" className={`shrink-0 ${direction === DESC ? '' : 'rotateX-180'}`} />\n            ) : null}\n        </div>\n    );\n};\n\ninterface CellUnsortableProps extends Omit<ThHTMLAttributes<HTMLTableCellElement>, 'content'> {\n    content: ReactNode;\n    key?: undefined | null | never;\n    sorting?: undefined | null | false;\n}\n\ninterface CellSortableProps<T> extends Omit<ThHTMLAttributes<HTMLTableCellElement>, 'content'> {\n    content: ReactNode;\n    key: keyof T;\n    sorting: true;\n}\n\ntype CellProps<T = any> = CellUnsortableProps | CellSortableProps<T>;\n\ninterface SortingTableHeaderProps<T> extends HTMLAttributes<HTMLTableSectionElement> {\n    cells: CellProps<T>[];\n    config: {\n        key: keyof T;\n        direction: SORT_DIRECTION;\n    };\n    onToggleSort: (key: keyof T) => void;\n}\n\nconst getCellKey = (key: symbol | string | number | null | undefined, index: number) =>\n    typeof key === 'string' || typeof key === 'number' ? `key-${key}` : `index-${index}`;\n\nexport const SortingTableHeader = <T extends unknown>({\n    cells = [],\n    config,\n    onToggleSort,\n    ...rest\n}: SortingTableHeaderProps<T>) => {\n    return (\n        <thead {...rest}>\n            <tr>\n                {cells.map(({ content, key, sorting, ...rest }, index) => (\n                    <TableCell key={getCellKey(key, index)} type=\"header\" {...rest}>\n                        {sorting ? (\n                            <SortingTableCellHeader\n                                content={content}\n                                onClick={() => onToggleSort(key)}\n                                direction={config && config.key === key ? config.direction : undefined}\n                            />\n                        ) : (\n                            content\n                        )}\n                    </TableCell>\n                ))}\n            </tr>\n        </thead>\n    );\n};\n","import { c } from 'ttag';\n\nimport {\n    Checkbox,\n    Field,\n    Option,\n    Row,\n    SelectTwo,\n    SortingTableHeader,\n    Table,\n    TableBody,\n    TableRow,\n} from '@proton/components/components';\nimport { SelectChangeEvent } from '@proton/components/components/selectTwo/select';\nimport { useSortedList } from '@proton/components/hooks';\nimport { SERVER_FEATURES, SORT_DIRECTION, USER_ROLES } from '@proton/shared/lib/constants';\nimport noop from '@proton/utils/noop';\n\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayUser } from './GatewayUser';\n\ntype PartialGateway = Pick<GatewayDto, 'features' | 'userIds'>;\n\ninterface Props {\n    loading: boolean;\n    users: readonly GatewayUser[];\n    model: PartialGateway;\n    changeModel: (model: Partial<PartialGateway>) => void;\n}\n\nexport const GatewayUserSelection = ({ loading, users, model, changeModel }: Props) => {\n    const { sortConfig, sortedList, toggleSort } = useSortedList(users as GatewayUser[], {\n        key: 'Email',\n        direction: SORT_DIRECTION.DESC,\n    });\n\n    const handleFeatureChange = ({ value }: SelectChangeEvent<string>) => changeModel({ features: Number(value) });\n\n    const getSelectToggle = (id: string) =>\n        loading\n            ? noop\n            : () =>\n                  changeModel({\n                      userIds:\n                          model.userIds.indexOf(id) !== -1\n                              ? model.userIds.filter((selected) => selected !== id)\n                              : [...model.userIds, id],\n                  });\n\n    const selectAllToggle = loading\n        ? noop\n        : () =>\n              changeModel({\n                  userIds: users.every(({ ID }) => model.userIds.indexOf(ID) !== -1) ? [] : users.map(({ ID }) => ID),\n              });\n\n    return (\n        <>\n            <Row>\n                <Field>\n                    <SelectTwo\n                        value={`${model.features & SERVER_FEATURES.DOUBLE_RESTRICTION}`}\n                        onChange={handleFeatureChange}\n                    >\n                        <Option value=\"0\" title={c('Title').t`Every member of the organization can access`}>\n                            {c('Option').t`The whole organization`}\n                        </Option>\n                        <Option\n                            value={`${SERVER_FEATURES.DOUBLE_RESTRICTION}`}\n                            title={c('Title').t`Custom selection of users`}\n                        >\n                            {c('Option').t`Select who can access...`}\n                        </Option>\n                    </SelectTwo>\n                </Field>\n            </Row>\n            {model.features & SERVER_FEATURES.DOUBLE_RESTRICTION ? (\n                <Table>\n                    <SortingTableHeader\n                        config={sortConfig}\n                        onToggleSort={toggleSort as any}\n                        cells={[\n                            {\n                                content: (\n                                    <Checkbox\n                                        className=\"p-1\"\n                                        checked={users.every(({ ID }) => model.userIds.indexOf(ID) !== -1)}\n                                        onChange={selectAllToggle}\n                                    />\n                                ),\n                                className: 'w-custom',\n                                style: { '--w-custom': '5%' },\n                            },\n                            { key: 'Name', content: c('TableHeader').t`Name`, sorting: true },\n                            { key: 'Email', content: c('TableHeader').t`Email`, sorting: true },\n                            {\n                                key: 'Role',\n                                content: c('TableHeader').t`Role`,\n                                sorting: true,\n                                className: 'w-1/10',\n                            },\n                        ]}\n                    />\n                    <TableBody loading={!users} colSpan={4}>\n                        {sortedList.map(({ ID, Name, Email, Role, Subscriber }: GatewayUser) => (\n                            <TableRow\n                                key={`select-user--${ID}`}\n                                cells={[\n                                    <Checkbox\n                                        className=\"p-1\"\n                                        checked={model.userIds.indexOf(ID) !== -1}\n                                        onChange={getSelectToggle(ID)}\n                                    />,\n                                    <div className=\"text-ellipsis\">{Name}</div>,\n                                    <div className=\"text-ellipsis\">{Email}</div>,\n                                    Role === USER_ROLES.ADMIN_ROLE\n                                        ? Subscriber\n                                            ? /* Current status of a user being admin of their organization */ c('Role')\n                                                  .t`Primary admin`\n                                            : /* Current status of a user being admin of their organization */ c('Role')\n                                                  .t`Admin`\n                                        : /* Current status of a user being simple member in their organization */ c(\n                                              'Role'\n                                          ).t`User`,\n                                ]}\n                            />\n                        ))}\n                    </TableBody>\n                </Table>\n            ) : undefined}\n        </>\n    );\n};\n\nexport default GatewayUserSelection;\n","import { c } from 'ttag';\n\nimport { SERVER_FEATURES } from '@proton/shared/lib/constants';\n\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayLogical } from './GatewayLogical';\nimport { GatewayServer } from './GatewayServer';\nimport { GatewayUser } from './GatewayUser';\n\nexport const getSuffix = (name: string | undefined) => name?.match(/#\\d+$/)?.[0] || '';\n\nconst getAverageLoad = (servers: GatewayServer[]) =>\n    servers.reduce((load, server) => load + server.Load, 0) / servers.length;\n\nconst getColorForLoad = (load: number): string => {\n    if (load > 90) {\n        return 'danger';\n    }\n\n    if (load > 75) {\n        return 'warning';\n    }\n\n    return 'success';\n};\n\nexport const getFormattedLoad = (servers: GatewayServer[]) => {\n    const load = Math.max(0, Math.min(100, Math.round(getAverageLoad(servers))));\n\n    return <span className={'color-' + getColorForLoad(load)}>{load}%</span>;\n};\n\nconst getInitialQuantities = (countries: readonly string[]) => {\n    const quantities: Record<string, 1> = {};\n\n    // Add 2 by default in different countries (take 1 in each of the 2 first countries)\n    for (let i = 0; i < 2 && countries[i]; i++) {\n        quantities[countries[i] as string] = 1;\n    }\n\n    return quantities;\n};\n\nexport const getTotalAdded = (quantities: Record<string, number> | null | undefined): number =>\n    Object.values(quantities || {}).reduce((total, quantity) => total + quantity, 0);\n\nexport const getInitialModel = (countries: readonly string[]): GatewayDto => ({\n    country: countries[0] || 'US',\n    name: '',\n    features: 0,\n    userIds: [],\n    quantities: getInitialQuantities(countries),\n});\n\nconst getUsersList = (userIds: readonly string[], users: readonly GatewayUser[], key = '') =>\n    userIds.length\n        ? userIds.map((id) => {\n              const user = users?.find((user) => user.ID === id);\n\n              return <div key={'logical-users-' + key + '-' + id}>{user?.Name || user?.Email}</div>;\n          })\n        : '0';\n\nexport const getMembers = (users: readonly GatewayUser[], logical: GatewayLogical) =>\n    logical.Features & SERVER_FEATURES.DOUBLE_RESTRICTION\n        ? getUsersList(logical.Users, users, logical.ID)\n        : /* translator: The whole organization has access to the gateway */ c('Info').t`Whole organization`;\n","import { useMemo } from 'react';\n\nimport { getTotalAdded } from './helpers';\n\nexport const useAddedQuantities = (model: { quantities?: Record<string, number> }) =>\n    useMemo(() => getTotalAdded(model.quantities), [model]);\n","import { useMemo } from 'react';\n\nconst getMaxForCountry = (country: string, remainingCount: number, deletedInCountries: Record<string, number>) =>\n    remainingCount -\n    Object.keys(deletedInCountries).reduce(\n        (count, otherCountry) => count + (country === otherCountry ? 0 : deletedInCountries[country]),\n        0\n    );\n\nexport const useSpecificCountryCount = (\n    model: { quantities?: Record<string, number> },\n    remainingCount: number,\n    deletedInCountries: Record<string, number>\n) =>\n    useMemo(\n        () =>\n            Object.keys(model.quantities || {}).reduce(\n                (total, country) =>\n                    total +\n                    Math.max(\n                        0,\n                        (model.quantities?.[country] || 0) -\n                            getMaxForCountry(country, remainingCount, deletedInCountries)\n                    ),\n                0\n            ),\n        [model, remainingCount, deletedInCountries]\n    );\n","import { useMemo, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Form,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    useFormErrors,\n} from '@proton/components/components';\n\nimport { GatewayCountrySelection } from './GatewayCountrySelection';\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayModel } from './GatewayModel';\nimport { GatewayNameField } from './GatewayNameField';\nimport { GatewayUser } from './GatewayUser';\nimport { GatewayUserSelection } from './GatewayUserSelection';\nimport { getInitialModel } from './helpers';\nimport { useAddedQuantities } from './useAddedQuantities';\nimport { useSpecificCountryCount } from './useSpecificCountryCount';\n\ninterface Props extends ModalProps<typeof Form> {\n    countries: readonly string[];\n    deletedInCountries: Record<string, number>;\n    ownedCount: number;\n    usedCount: number;\n    users: readonly GatewayUser[];\n    language: string | readonly string[];\n    isEditing?: boolean;\n    singleServer?: boolean;\n    showCancelButton?: boolean;\n    onSubmitDone: (server: GatewayModel) => Promise<void>;\n    onUpsell: () => void;\n}\n\nenum STEP {\n    NAME,\n    COUNTRIES,\n    MEMBERS,\n}\n\nconst GatewayModal = ({\n    countries,\n    deletedInCountries,\n    ownedCount,\n    usedCount,\n    users,\n    language,\n    onSubmitDone,\n    onUpsell,\n    isEditing = false,\n    singleServer = false,\n    showCancelButton = false,\n    ...rest\n}: Props) => {\n    const { validator, onFormSubmit } = useFormErrors();\n    const [step, setStep] = useState(STEP.NAME);\n    const [model, setModel] = useState(getInitialModel(countries));\n    const [loading, setLoading] = useState(false);\n    const remainingCount = useMemo(() => ownedCount - usedCount, [ownedCount, usedCount]);\n    const addedCount = useAddedQuantities(model);\n    const totalCountExceeded = useMemo(() => addedCount > remainingCount, [addedCount, remainingCount]);\n    const specificCountryCount = useSpecificCountryCount(model, remainingCount, deletedInCountries);\n    const needUpsell = useMemo(\n        () => totalCountExceeded || specificCountryCount > 0,\n        [totalCountExceeded, specificCountryCount]\n    );\n    const canContinue = useMemo(\n        () => step !== STEP.COUNTRIES || !(needUpsell || (!singleServer && addedCount < 1)),\n        [step, needUpsell, singleServer, addedCount]\n    );\n\n    const changeModel = (diff: Partial<GatewayDto>) => setModel((model: GatewayDto) => ({ ...model, ...diff }));\n\n    const stepBack = () => {\n        if (step === STEP.MEMBERS) {\n            setStep(countries.length > 1 ? STEP.COUNTRIES : STEP.NAME);\n\n            return;\n        }\n\n        if (step === STEP.COUNTRIES) {\n            setStep(STEP.NAME);\n\n            return;\n        }\n\n        rest.onClose?.();\n    };\n\n    const handleSubmit = async () => {\n        if (!onFormSubmit()) {\n            return;\n        }\n\n        if (step === STEP.NAME) {\n            setStep(countries.length > 1 ? STEP.COUNTRIES : STEP.MEMBERS);\n\n            return;\n        }\n\n        if (step === STEP.COUNTRIES) {\n            setStep(STEP.MEMBERS);\n\n            return;\n        }\n\n        const quantities: Record<string, number> = {};\n        let total = 0;\n\n        Object.keys(model.quantities || {}).forEach((country) => {\n            const count = model.quantities?.[country] || 0;\n\n            if (count > 0) {\n                quantities[country] = count;\n                total += count;\n            }\n        });\n\n        const dtoBody: GatewayModel =\n            singleServer || total === 1\n                ? {\n                      Name: model.name,\n                      Country: model.country,\n                      Features: model.features,\n                      UserIds: model.userIds,\n                  }\n                : {\n                      Name: model.name,\n                      Features: model.features,\n                      UserIds: model.userIds,\n                      Quantities: quantities,\n                  };\n\n        try {\n            setLoading(true);\n            await onSubmitDone(dtoBody);\n            rest.onClose?.();\n        } finally {\n            setLoading(false);\n        }\n    };\n\n    return (\n        <ModalTwo size={step === STEP.MEMBERS ? 'xlarge' : 'large'} as={Form} onSubmit={handleSubmit} {...rest}>\n            <ModalTwoHeader\n                title={(() => {\n                    if (step === STEP.NAME) {\n                        return isEditing ? c('Action').t`Edit Gateway` : c('Title').t`Create Gateway`;\n                    }\n\n                    if (step === STEP.COUNTRIES) {\n                        return c('Title').t`Add servers`;\n                    }\n\n                    return c('Title').t`Add users`;\n                })()}\n            />\n            <ModalTwoContent>\n                {step === STEP.NAME && (\n                    <GatewayNameField model={model} changeModel={changeModel} validator={validator} />\n                )}\n                {step === STEP.COUNTRIES && (\n                    <GatewayCountrySelection\n                        singleServer={singleServer}\n                        countries={countries}\n                        ownedCount={ownedCount}\n                        usedCount={usedCount}\n                        addedCount={addedCount}\n                        needUpsell={needUpsell}\n                        specificCountryCount={specificCountryCount}\n                        language={language}\n                        onUpsell={() => {\n                            rest.onClose?.();\n                            onUpsell();\n                        }}\n                        loading={loading}\n                        model={model}\n                        changeModel={changeModel}\n                    />\n                )}\n                {step === STEP.MEMBERS && (\n                    <GatewayUserSelection loading={loading} users={users} model={model} changeModel={changeModel} />\n                )}\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {showCancelButton || step !== STEP.NAME ? (\n                    <Button color=\"weak\" onClick={stepBack}>\n                        {step === STEP.NAME\n                            ? c('Action').t`Cancel`\n                            : /* button to go back to previous step of gateway creation */ c('Action').t`Back`}\n                    </Button>\n                ) : (\n                    <div />\n                )}\n                <Button color=\"norm\" type=\"submit\" loading={loading} disabled={!canContinue}>\n                    {step === STEP.MEMBERS\n                        ? /* final step submit button of the creation, if not clean translation possible, it can also simply be \"Create\" */ c(\n                              'Action'\n                          ).t`Done`\n                        : /* button to continue to the next step of gateway creation */ c('Action').t`Continue`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default GatewayModal;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Form,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    useFormErrors,\n} from '@proton/components/components';\n\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayNameField } from './GatewayNameField';\n\ninterface Props extends ModalProps<typeof Form> {\n    currentName: string;\n    showCancelButton?: boolean;\n    onSubmitDone: (server: { Name: string }) => Promise<void>;\n}\n\nconst GatewayRenameModal = ({ currentName, showCancelButton = false, onSubmitDone, ...rest }: Props) => {\n    const { validator, onFormSubmit } = useFormErrors();\n    const [model, setModel] = useState({\n        name: '',\n    } as GatewayDto);\n    const [loading, setLoading] = useState(false);\n\n    const changeModel = (diff: Partial<GatewayDto>) => setModel((model: GatewayDto) => ({ ...model, ...diff }));\n\n    const handleSubmit = async () => {\n        if (!onFormSubmit()) {\n            return;\n        }\n\n        const dtoBody = {\n            Name: model.name || '',\n        };\n\n        try {\n            setLoading(true);\n            await onSubmitDone(dtoBody);\n            rest.onClose?.();\n        } finally {\n            setLoading(false);\n        }\n    };\n\n    return (\n        <ModalTwo size=\"large\" {...rest} as={Form} onSubmit={handleSubmit}>\n            <ModalTwoHeader title={c('Title').t`Edit Gateway ${currentName}`} />\n            <ModalTwoContent>\n                <GatewayNameField model={model} changeModel={changeModel} validator={validator} />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {showCancelButton ? (\n                    <Button color=\"weak\" onClick={rest.onClose}>\n                        {c('Action').t`Cancel`}\n                    </Button>\n                ) : (\n                    <div />\n                )}\n                <Button color=\"norm\" type=\"submit\" loading={loading}>\n                    {c('Action').t`Rename`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default GatewayRenameModal;\n","import { c, msgid } from 'ttag';\n\nimport {\n    Dropdown,\n    DropdownButton,\n    DropdownMenu,\n    DropdownMenuButton,\n    Icon,\n    usePopperAnchor,\n} from '@proton/components/components';\n\nimport { Gateway } from './Gateway';\nimport { GatewayLogical } from './GatewayLogical';\n\ninterface Props {\n    gateway: Gateway;\n    logical: GatewayLogical;\n    deleted: boolean;\n    deletingLogicals: readonly string[];\n    deletedLogicals: Record<string, boolean>;\n    renameGateway: (id: string, name: string) => () => any;\n    editGatewayServers: (gateway: Gateway, logical: GatewayLogical) => () => any;\n    editGatewayUsers: (gateway: Gateway, logical: GatewayLogical) => () => any;\n    deleteGateway: (gateway: Gateway) => () => any;\n}\n\nexport const GatewayManageButton = ({\n    gateway,\n    logical,\n    renameGateway = () => () => {},\n    editGatewayServers = () => () => {},\n    editGatewayUsers = () => () => {},\n    deleteGateway = () => () => {},\n    deletingLogicals,\n    deletedLogicals,\n    deleted = false,\n}: Props) => {\n    const deleteServerTitle = (() => {\n        const days = 7;\n\n        return c('Title').ngettext(\n            msgid`Delete the server (you will still be able to recover it for ${days} day)`,\n            `Delete the server (you will still be able to recover it for ${days} days)`,\n            days\n        );\n    })();\n    const loading = deletingLogicals.indexOf(logical.ID) !== -1;\n    const disabled = Boolean(deletedLogicals[logical.ID]);\n\n    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();\n\n    return (\n        <>\n            <DropdownButton\n                ref={anchorRef}\n                isOpen={isOpen}\n                onClick={toggle}\n                icon\n                title={c('Title').t`Open actions dropdown`}\n                size=\"small\"\n            >\n                <Icon name=\"three-dots-vertical\" />\n            </DropdownButton>\n            <Dropdown isOpen={isOpen} anchorRef={anchorRef} onClose={close} originalPlacement=\"bottom-end\">\n                <DropdownMenu>\n                    <DropdownMenuButton\n                        className=\"text-left\"\n                        loading={loading}\n                        disabled={disabled}\n                        onClick={renameGateway(logical.ID, logical.Name.replace(/#\\d+$/, '').replace(/-\\d+$/, ''))}\n                        title={c('Title').t`Rename the gateway`}\n                    >\n                        <Icon name=\"pen\" className=\"mr-2\" />\n                        {c('Action').t`Edit name`}\n                    </DropdownMenuButton>\n                    <DropdownMenuButton\n                        className=\"text-left\"\n                        loading={loading}\n                        disabled={disabled}\n                        onClick={editGatewayServers(gateway, logical)}\n                        title={c('Title').t`Edit the list of servers of the gateway`}\n                    >\n                        <Icon name=\"servers\" className=\"mr-2\" />\n                        {c('Action').t`Edit servers`}\n                    </DropdownMenuButton>\n                    <DropdownMenuButton\n                        className=\"text-left\"\n                        loading={loading}\n                        disabled={disabled}\n                        onClick={editGatewayUsers(gateway, logical)}\n                        title={c('Title').t`Edit who can access the gateway`}\n                    >\n                        <Icon name=\"users\" className=\"mr-2\" />\n                        {c('Action').t`Edit users`}\n                    </DropdownMenuButton>\n                    {!deleted && (\n                        <>\n                            <div className=\"dropdown-item-hr\" key=\"hr-more-options\" />\n                            <DropdownMenuButton\n                                className=\"text-left color-danger\"\n                                loading={loading}\n                                onClick={deleteGateway(gateway)}\n                                title={deleteServerTitle}\n                            >\n                                <Icon name=\"trash\" className=\"mr-2\" />\n                                {c('Action').t`Delete`}\n                            </DropdownMenuButton>\n                        </>\n                    )}\n                </DropdownMenu>\n            </Dropdown>\n        </>\n    );\n};\n\nexport default GatewayManageButton;\n","import { c, msgid } from 'ttag';\n\nimport { Copy, TableRow } from '@proton/components/components';\nimport { useNotifications } from '@proton/components/hooks';\nimport clsx from '@proton/utils/clsx';\n\nimport { Gateway } from './Gateway';\nimport { GatewayLogical } from './GatewayLogical';\nimport GatewayManageButton from './GatewayManageButton';\nimport { GatewayServer } from './GatewayServer';\nimport { GatewayUser } from './GatewayUser';\nimport { getCountryFlagAndName } from './getCountryFlagAndName';\nimport { getFormattedLoad, getMembers, getSuffix } from './helpers';\n\ninterface Props {\n    isAdmin: boolean;\n    showDeleted?: boolean;\n    showIPv4?: boolean;\n    showIPv6?: boolean;\n    showLoad?: boolean;\n    gateway: Gateway;\n    isDeleted: (logical: GatewayLogical) => boolean;\n    users: readonly GatewayUser[];\n    language: string | readonly string[];\n    provisioningDuration: string;\n    deletingLogicals: readonly string[];\n    deletedLogicals: Record<string, boolean>;\n    renameGateway: (id: string, name: string) => () => any;\n    editGatewayServers: (gateway: Gateway, logical: GatewayLogical) => () => any;\n    editGatewayUsers: (gateway: Gateway, logical: GatewayLogical) => () => any;\n    deleteGateway: (gateway: Gateway) => () => any;\n}\n\nexport const GatewayRow = ({\n    isAdmin,\n    showDeleted,\n    showIPv4,\n    showIPv6,\n    showLoad,\n    gateway,\n    isDeleted,\n    users,\n    language,\n    provisioningDuration,\n    renameGateway,\n    editGatewayServers,\n    editGatewayUsers,\n    deleteGateway,\n    deletingLogicals,\n    deletedLogicals,\n}: Props) => {\n    const { createNotification } = useNotifications();\n\n    let provisioningCounter = 0;\n    const allLogicals = gateway.Logicals || [];\n    const deleted = allLogicals.every(isDeleted);\n\n    if (deleted && !showDeleted) {\n        return <></>;\n    }\n\n    const logicals = allLogicals.filter((logical) => {\n        if (isDeleted(logical)) {\n            return false;\n        }\n\n        if (!logical.Servers?.length) {\n            provisioningCounter++;\n\n            return false;\n        }\n\n        return true;\n    });\n    const provisionedLogicals = [...logicals.filter((l) => l.Visible), ...logicals.filter((l) => !l.Visible)];\n    const hasPendingServers = provisioningCounter > 0;\n    const main = provisionedLogicals[0] || allLogicals[0];\n    const [statusClasses, statusText] = provisionedLogicals.length\n        ? ['bg-success', /** translator: status of the gateway: people can connect to it */ c('Info').t`active`]\n        : [\n              'bg-weak color-weak',\n              /** translator: status of the gateway: people cannot connect to it */ c('Info').t`inactive`,\n          ];\n\n    const getIpsCell = (servers: GatewayServer[]) =>\n        servers[0]\n            ? [\n                  ...(showIPv4 ? [servers[0].ExitIPv4] : []),\n                  ...(showIPv6 ? [servers[0].ExitIPv6] : []),\n                  ...(showLoad ? [getFormattedLoad(servers)] : []),\n              ].join(', ')\n            : c('Action').t`Your server will be provisioned in the next days`;\n\n    return (\n        <TableRow\n            className={deleted ? 'opacity-50' : undefined}\n            cells={[\n                gateway.Name,\n                <span className={clsx(['py-1 px-2 rounded text-uppercase', statusClasses])}>{statusText}</span>,\n                <div>\n                    {provisionedLogicals.length < 1 && !hasPendingServers && '0'}\n                    {provisionedLogicals.map((logical) => (\n                        <div key={'logical-' + logical.ID}>\n                            <span className=\"text-nowrap bg-weak py-1 px-2 rounded\">\n                                {getCountryFlagAndName(language, logical.ExitCountry, getSuffix(logical.Name), {\n                                    className: 'mb-1',\n                                    key: 'country-logical-' + logical.ID + '-' + logical.ExitCountry,\n                                })}\n                                <span className=\"color-weak\">&nbsp; • &nbsp;</span>\n                                {getIpsCell(logical.Servers)}\n                                <Copy\n                                    value={logical.Servers[0].ExitIPv4}\n                                    shape=\"ghost\"\n                                    onCopy={() => {\n                                        createNotification({\n                                            text: c('Notification').t`IP Address copied to clipboard`,\n                                        });\n                                    }}\n                                />\n                            </span>\n                        </div>\n                    ))}\n                    {hasPendingServers && (\n                        <div className=\"color-weak\">\n                            {c('Info').ngettext(\n                                msgid`${provisioningCounter} server is still being set up. This usually takes around ${provisioningDuration}.`,\n                                `${provisioningCounter} servers are still being set up. This usually takes around ${provisioningDuration}.`,\n                                provisioningCounter\n                            )}\n                        </div>\n                    )}\n                </div>,\n                ...(isAdmin\n                    ? [\n                          getMembers(users, main),\n                          <GatewayManageButton\n                              gateway={gateway}\n                              logical={main}\n                              renameGateway={renameGateway}\n                              editGatewayServers={editGatewayServers}\n                              editGatewayUsers={editGatewayUsers}\n                              deleteGateway={deleteGateway}\n                              deletingLogicals={deletingLogicals}\n                              deletedLogicals={deletedLogicals}\n                              deleted={deleted}\n                          />,\n                      ]\n                    : []),\n            ]}\n        />\n    );\n};\n\nexport default GatewayRow;\n","/**\n * Build an array with a numeric range, specified by a start, an end, and a step\n */\nconst range = (start = 0, end = 1, step = 1) => {\n    const result = [];\n    for (let index = start; index < end; index += step) {\n        result.push(index);\n    }\n    return result;\n};\n\nexport default range;\n","import { useMemo, useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Form,\n    ModalStateProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n} from '@proton/components/components';\n\nimport { GatewayCountrySelection } from './GatewayCountrySelection';\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayUser } from './GatewayUser';\nimport { getInitialModel } from './helpers';\nimport { useAddedQuantities } from './useAddedQuantities';\nimport { useSpecificCountryCount } from './useSpecificCountryCount';\n\ninterface Props extends ModalStateProps {\n    countries: readonly string[];\n    deletedInCountries: Record<string, number>;\n    ownedCount: number;\n    usedCount: number;\n    users: readonly GatewayUser[];\n    language: string | readonly string[];\n    singleServer?: boolean;\n    showCancelButton?: boolean;\n    onSubmitDone: (quantities: Record<string, number>) => void;\n    onUpsell: () => void;\n}\n\nconst GatewayAddServersModal = ({\n    countries,\n    deletedInCountries,\n    ownedCount,\n    usedCount,\n    users,\n    language,\n    onSubmitDone,\n    onUpsell,\n    singleServer = false,\n    showCancelButton = false,\n    ...rest\n}: Props) => {\n    const [model, setModel] = useState(getInitialModel(countries));\n    const remainingCount = useMemo(() => ownedCount - usedCount, [ownedCount, usedCount]);\n    const numberOfAddedServers = useAddedQuantities(model);\n    const totalCountExceeded = useMemo(\n        () => numberOfAddedServers > remainingCount,\n        [numberOfAddedServers, remainingCount]\n    );\n    const specificCountryCount = useSpecificCountryCount(model, remainingCount, deletedInCountries);\n    const needUpsell = useMemo(\n        () => totalCountExceeded || specificCountryCount > 0,\n        [totalCountExceeded, specificCountryCount]\n    );\n\n    const changeModel = (diff: Partial<GatewayDto>) => setModel((model) => ({ ...model, ...diff }));\n\n    const handleSubmit = async () => {\n        onSubmitDone(model.quantities || {});\n        rest.onClose?.();\n    };\n\n    return (\n        <ModalTwo size=\"large\" as={Form} onSubmit={handleSubmit} {...rest}>\n            <ModalTwoHeader title={c('Title').t`Add servers`} />\n            <ModalTwoContent>\n                <GatewayCountrySelection\n                    singleServer={singleServer}\n                    countries={countries}\n                    ownedCount={ownedCount}\n                    usedCount={usedCount}\n                    addedCount={numberOfAddedServers}\n                    needUpsell={needUpsell}\n                    specificCountryCount={specificCountryCount}\n                    language={language}\n                    onUpsell={() => {\n                        rest.onClose?.();\n                        onUpsell();\n                    }}\n                    model={model}\n                    changeModel={changeModel}\n                />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {showCancelButton ? (\n                    <Button color=\"weak\" onClick={rest.onClose}>\n                        {c('Action').t`Cancel`}\n                    </Button>\n                ) : (\n                    <div />\n                )}\n                {!needUpsell && numberOfAddedServers >= 1 ? (\n                    <Button color=\"norm\" type=\"submit\">\n                        {c('Feature').ngettext(\n                            msgid`Add (${numberOfAddedServers})`,\n                            `Add (${numberOfAddedServers})`,\n                            numberOfAddedServers\n                        )}\n                    </Button>\n                ) : (\n                    <Button color=\"norm\" type=\"submit\" disabled>\n                        {c('Feature').t`Add`}\n                    </Button>\n                )}\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default GatewayAddServersModal;\n","import React, { useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Cell,\n    Form,\n    Icon,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    Table,\n    TableBody,\n    TableCell,\n    TableRow,\n    useModalTwoStatic,\n} from '@proton/components/components';\nimport { MAX_IPS_ADDON } from '@proton/shared/lib/constants';\nimport range from '@proton/utils/range';\n\nimport { Gateway } from './Gateway';\nimport GatewayAddServersModal from './GatewayAddServersModal';\nimport { GatewayLogical } from './GatewayLogical';\nimport { GatewayUser } from './GatewayUser';\nimport { getCountryFlagAndName } from './getCountryFlagAndName';\nimport { getFormattedLoad, getSuffix, getTotalAdded } from './helpers';\n\ninterface Props extends ModalProps<typeof Form> {\n    gateway: Gateway;\n    language: string | readonly string[];\n    countries: readonly string[];\n    deletedInCountries: Record<string, number>;\n    users: readonly GatewayUser[];\n    ownedCount: number;\n    usedCount: number;\n    showDeleted?: boolean;\n    showIPv4?: boolean;\n    showIPv6?: boolean;\n    showLoad?: boolean;\n    showCancelButton?: boolean;\n    singleServer?: boolean;\n    isDeleted: (logical: GatewayLogical) => boolean;\n    onSubmitDone: (deletedLogicalIds: readonly string[], addedQuantities: Record<string, number>) => Promise<void>;\n    onUpsell: () => void;\n}\n\nconst GatewayServersModal = ({\n    gateway,\n    language,\n    countries,\n    deletedInCountries,\n    users,\n    ownedCount,\n    usedCount,\n    showDeleted = false,\n    showIPv4 = true,\n    showIPv6 = true,\n    showLoad = true,\n    showCancelButton = false,\n    singleServer = false,\n    isDeleted,\n    onSubmitDone,\n    onUpsell,\n    ...rest\n}: Props) => {\n    const [addServersModal, showAddServersModal] = useModalTwoStatic(GatewayAddServersModal);\n    const [deleted, setDeleted] = useState<Record<string, boolean>>({});\n    const [added, setAdded] = useState<Record<string, number>>({});\n    const [loading, setLoading] = useState(false);\n    const remainingCount = ownedCount - usedCount;\n    const previousServers = gateway.Logicals.filter((l) => !l.Servers?.length || l.Visible);\n    const previousNumberOfServers = previousServers.length;\n    const deletedServers = previousServers.filter((l) => deleted[l.ID]);\n    const deletedServerCount = deletedServers.length;\n    const addedServerCount = Object.entries(added).reduce((total, [, quantity]) => total + quantity, 0);\n    const availableAddedCount = remainingCount + deletedServerCount - addedServerCount;\n    const newNumberOfServers = previousNumberOfServers + addedServerCount - deletedServerCount;\n    const showIP = showIPv4 || showIPv6;\n\n    const decreaseQuantities = (quantities: Record<string, number>) => {\n        const newAdded = { ...added };\n\n        Object.entries(quantities).forEach(([country, quantity]) => {\n            const newQuantity = (newAdded[country] || 0) - quantity;\n\n            if (newQuantity) {\n                newAdded[country] = newQuantity;\n\n                return;\n            }\n\n            delete newAdded[country];\n        });\n\n        setAdded(newAdded);\n    };\n\n    const addQuantities = (quantities: Record<string, number>) => {\n        const entries = Object.entries(quantities);\n\n        if (!entries.length) {\n            return;\n        }\n\n        const newAdded = { ...added };\n        let deletedIds = Object.keys(deleted).filter((id) => deleted[id]);\n\n        entries.forEach(([country, quantity]) => {\n            const serversFromTrash = gateway.Logicals.filter((l) => l.ExitCountry === country && l.ID && deleted[l.ID])\n                .map((l) => l.ID)\n                .slice(0, quantity);\n            const recoverableQuantity = serversFromTrash.length;\n\n            if (recoverableQuantity) {\n                deletedIds = deletedIds.filter((id) => serversFromTrash.indexOf(id) === -1);\n            }\n\n            const addedQuantity = quantity - recoverableQuantity;\n\n            if (addedQuantity > 0) {\n                newAdded[country] = (newAdded[country] || 0) + addedQuantity;\n            }\n        });\n\n        const newDeleted: Record<string, true> = {};\n\n        deletedIds.forEach((id) => {\n            newDeleted[id] = true;\n        });\n\n        setAdded(newAdded);\n        setDeleted(newDeleted);\n    };\n\n    const addServers = () =>\n        showAddServersModal({\n            countries,\n            deletedInCountries,\n            ownedCount,\n            usedCount: usedCount - deletedServerCount + addedServerCount,\n            users,\n            language,\n            singleServer,\n            showCancelButton,\n            onSubmitDone: addQuantities,\n            onUpsell,\n        });\n\n    const handleDelete = (logical: GatewayLogical) => async () => {\n        if (added[logical.ExitCountry] > 0) {\n            decreaseQuantities({ [logical.ExitCountry]: 1 });\n\n            return;\n        }\n\n        setDeleted({\n            ...deleted,\n            [logical.ID]: !deleted[logical.ID],\n        });\n    };\n\n    const handleSubmit = async () => {\n        const idsToDelete = Object.keys(deleted).filter((id) => deleted[id]);\n\n        if (getTotalAdded(added) < 1 && idsToDelete.length < 1) {\n            rest.onClose?.();\n\n            return;\n        }\n\n        try {\n            setLoading(true);\n            await onSubmitDone(idsToDelete, added);\n            rest.onClose?.();\n        } finally {\n            setLoading(false);\n        }\n    };\n\n    return (\n        <>\n            <ModalTwo size=\"xlarge\" {...rest} as={Form} onSubmit={handleSubmit}>\n                <ModalTwoHeader title={c('Title').t`Edit servers`} />\n                <ModalTwoContent>\n                    <Table className=\"my-2\">\n                        <thead>\n                            <tr>\n                                <TableCell key=\"country\" type=\"header\">{c('Header').t`Country`}</TableCell>\n                                <TableCell key=\"server\" type=\"header\" className=\"w-1/10\">\n                                    {c('Header').t`Server`}\n                                </TableCell>\n                                <TableCell key=\"status\" type=\"header\" className=\"w-1/6\">\n                                    {c('Header').t`Status`}\n                                </TableCell>\n                                {showIP && (\n                                    <TableCell key=\"ip\" type=\"header\" className=\"w-1/6\">\n                                        {c('Header').t`IP address`}\n                                    </TableCell>\n                                )}\n                                {showLoad && (\n                                    <TableCell key=\"load\" type=\"header\" className=\"w-1/6\">\n                                        {c('Header').t`Server load`}\n                                    </TableCell>\n                                )}\n                                <TableCell key=\"manage\" type=\"header\" className=\"w-1/10\">\n                                    &nbsp;\n                                </TableCell>\n                            </tr>\n                        </thead>\n                        <TableBody colSpan={4 + Number(showIP) + Number(showLoad)} loading={loading}>\n                            {gateway.Logicals.filter((l) => l.Servers?.length && l.Visible).map((logical) => (\n                                <TableRow\n                                    key={'logical-' + logical.ID}\n                                    className={deleted[logical.ID] ? 'opacity-50' : undefined}\n                                    cells={[\n                                        getCountryFlagAndName(language, logical.ExitCountry, undefined, {\n                                            className: 'mb-1',\n                                            key: `country-logical-${logical.ID}-${logical.ExitCountry}`,\n                                        }),\n                                        getSuffix(logical.Name),\n                                        <span className=\"py-1 px-2 rounded text-uppercase bg-success\">{\n                                            /** translator: status of the server: people can connect to it */\n                                            c('Server-Info').t`active`\n                                        }</span>,\n                                        ...(showIP\n                                            ? [\n                                                  <>\n                                                      {[\n                                                          showIPv4 && logical.Servers[0].ExitIPv4,\n                                                          showIPv6 && logical.Servers[0].ExitIPv6,\n                                                      ]\n                                                          .filter(Boolean)\n                                                          .map((ip) => (\n                                                              <div\n                                                                  key={'ip-' + ip}\n                                                                  className=\"text-ellipsis\"\n                                                                  title={ip || undefined}\n                                                              >\n                                                                  {ip}\n                                                              </div>\n                                                          ))}\n                                                  </>,\n                                              ]\n                                            : []),\n                                        ...(showLoad ? [getFormattedLoad(logical.Servers)] : []),\n                                        <Button icon size=\"small\" key=\"delete\" onClick={handleDelete(logical)}>\n                                            <Icon name=\"trash\" />\n                                        </Button>,\n                                    ]}\n                                />\n                            ))}\n                            {showDeleted &&\n                                gateway.Logicals.filter((l) => l.Servers?.length && !l.Visible).map((logical) => (\n                                    <TableRow\n                                        key={'logical-' + logical.ID}\n                                        className=\"opacity-50\"\n                                        cells={[\n                                            getCountryFlagAndName(language, logical.ExitCountry, undefined, {\n                                                className: 'mb-1',\n                                                key: 'country-logical-' + logical.ID + '-' + logical.ExitCountry,\n                                            }),\n                                            getSuffix(logical.Name),\n                                            <span className=\"py-1 px-2 rounded text-uppercase bg-weak color-weak\">{\n                                                /** translator: status of the server: people cannot connect to it */\n                                                c('Server-Info').t`inactive`\n                                            }</span>,\n                                            ...(showIP\n                                                ? [\n                                                      <>\n                                                          {[logical.Servers[0].ExitIPv4, logical.Servers[0].ExitIPv6]\n                                                              .filter(Boolean)\n                                                              .map((ip) => (\n                                                                  <div key={'ip-' + ip}>{ip}</div>\n                                                              ))}\n                                                      </>,\n                                                  ]\n                                                : []),\n                                            ...(showLoad ? [getFormattedLoad(logical.Servers)] : []),\n                                            '',\n                                        ]}\n                                    />\n                                ))}\n                            {gateway.Logicals.filter((l) => !l.Servers?.length).map((logical) => (\n                                <TableRow\n                                    key={'logical-' + logical.ID}\n                                    className={deleted[logical.ID] ? 'opacity-50' : undefined}\n                                    cells={[\n                                        getCountryFlagAndName(language, logical.ExitCountry, undefined, {\n                                            className: 'mb-1',\n                                            key: 'country-logical-' + logical.ID + '-' + logical.ExitCountry,\n                                        }),\n                                        getSuffix(logical.Name),\n                                        <span className=\"py-1 px-2 rounded text-uppercase bg-info\">{\n                                            /** translator: status of the server: people cannot yet use it */\n                                            c('Server-Info').t`pending`\n                                        }</span>,\n                                        ...(showIP ? ['-'] : []),\n                                        ...(showLoad ? ['-'] : []),\n                                        <Button icon size=\"small\" key=\"delete\" onClick={handleDelete(logical)}>\n                                            <Icon name=\"trash\" />\n                                        </Button>,\n                                    ]}\n                                />\n                            ))}\n                            {Object.keys(added).map((country) =>\n                                range(0, added[country]).map((index) => (\n                                    <TableRow\n                                        key={'future-logical-' + country + '-' + index}\n                                        cells={[\n                                            getCountryFlagAndName(language, country, undefined, {\n                                                className: 'mb-1',\n                                                key: 'country-future-logical-' + country + '-' + index,\n                                            }),\n                                            '',\n                                            new Cell(\n                                                (\n                                                    <span className=\"py-1 px-2 rounded text-uppercase bg-weak\">{\n                                                        /** translator: status of the server: will be created when user click \"Save\" */\n                                                        c('Server-Info').t`to be created`\n                                                    }</span>\n                                                ),\n                                                1 + Number(showIP) + Number(showLoad)\n                                            ),\n                                            <Button\n                                                icon\n                                                size=\"small\"\n                                                key=\"delete\"\n                                                onClick={() => {\n                                                    decreaseQuantities({ [country]: 1 });\n                                                }}\n                                            >\n                                                <Icon name=\"trash\" />\n                                            </Button>,\n                                        ]}\n                                    />\n                                ))\n                            )}\n                        </TableBody>\n                    </Table>\n                    {availableAddedCount >= 1 ? (\n                        <Button shape=\"ghost\" className=\"color-primary\" onClick={addServers}>\n                            <Icon name=\"plus-circle-filled\" className=\"mr-2\" />\n                            {c('Info').ngettext(\n                                msgid`Add server (${availableAddedCount} available)`,\n                                `Add server (${availableAddedCount} available)`,\n                                availableAddedCount\n                            )}\n                        </Button>\n                    ) : (\n                        ownedCount < MAX_IPS_ADDON && (\n                            <Button\n                                shape=\"ghost\"\n                                className=\"color-primary\"\n                                onClick={() => {\n                                    onUpsell();\n                                    rest.onClose?.();\n                                }}\n                            >\n                                <Icon name=\"plus-circle-filled\" className=\"mr-2\" />\n                                {c('Action').t`Get more servers`}\n                            </Button>\n                        )\n                    )}\n                </ModalTwoContent>\n                <ModalTwoFooter>\n                    {showCancelButton ? (\n                        <Button color=\"weak\" onClick={rest.onClose}>\n                            {c('Action').t`Cancel`}\n                        </Button>\n                    ) : (\n                        <div />\n                    )}\n                    <Button color={newNumberOfServers ? 'norm' : 'danger'} type=\"submit\" loading={loading}>\n                        {newNumberOfServers ? c('Action').t`Save` : c('Action').t`Delete Gateway`}\n                    </Button>\n                </ModalTwoFooter>\n            </ModalTwo>\n            {addServersModal}\n        </>\n    );\n};\n\nexport default GatewayServersModal;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    Form,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n} from '@proton/components/components';\n\nimport { GatewayDto } from './GatewayDto';\nimport { GatewayModel } from './GatewayModel';\nimport { GatewayUser } from './GatewayUser';\nimport { GatewayUserSelection } from './GatewayUserSelection';\n\ntype PartialGateway = Pick<GatewayDto, 'features' | 'userIds'>;\n\ninterface Props extends ModalProps<typeof Form> {\n    model: PartialGateway;\n    users: readonly GatewayUser[];\n    showCancelButton?: boolean;\n    onSubmitDone: (gateway: Pick<GatewayModel, 'Features' | 'UserIds'>) => Promise<void>;\n}\n\nconst GatewayUsersModal = ({ model: initialModel, users, showCancelButton = false, onSubmitDone, ...rest }: Props) => {\n    const [model, setModel] = useState<PartialGateway>({ ...initialModel });\n    const [loading, setLoading] = useState(false);\n\n    const changeModel = (diff: Partial<PartialGateway>) => setModel((model) => ({ ...model, ...diff }));\n\n    const handleSubmit = async () => {\n        const dtoBody = {\n            Features: model.features,\n            UserIds: model.userIds,\n        };\n\n        try {\n            setLoading(true);\n            await onSubmitDone(dtoBody);\n            rest.onClose?.();\n        } finally {\n            setLoading(false);\n        }\n    };\n\n    return (\n        <ModalTwo size=\"xlarge\" {...rest} as={Form} onSubmit={handleSubmit}>\n            <ModalTwoHeader title={c('Title').t`Edit users`} />\n            <ModalTwoContent>\n                <GatewayUserSelection loading={loading} users={users} model={model} changeModel={changeModel} />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                {showCancelButton ? (\n                    <Button color=\"weak\" onClick={rest.onClose}>\n                        {c('Action').t`Cancel`}\n                    </Button>\n                ) : (\n                    <div />\n                )}\n                <Button color=\"norm\" type=\"submit\" loading={loading}>\n                    {c('Action').t`Save`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default GatewayUsersModal;\n","import { GatewayIpModel } from '@proton/components/containers/vpn/gateways/GatewayIpModel';\n\nimport { GatewayModel } from './GatewayModel';\n\nexport const queryVPNGateways = () => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'get',\n});\n\nexport const createVPNGateway = (data: GatewayModel) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'post',\n    data,\n});\n\nexport const addIpInVPNGateway = (data: GatewayIpModel) => ({\n    url: 'vpn/v1/business/gateways/ip',\n    method: 'post',\n    data,\n});\n\nexport const deleteVPNGateway = (ids: readonly string[]) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'delete',\n    data: {\n        LogicalIds: ids,\n    },\n});\n\nexport const renameVPNGateway = (currentName: string, newName: string) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'put',\n    data: {\n        CurrentName: currentName,\n        NewName: newName,\n    },\n});\n\nexport const updateVPNGatewayUsers = (currentName: string, features: number, userIds?: readonly string[] | null) => ({\n    url: 'vpn/v1/business/gateways',\n    method: 'put',\n    data: {\n        CurrentName: currentName,\n        NewName: currentName,\n        Features: features,\n        UserIds: userIds ?? null,\n    },\n});\n","import { c, msgid } from 'ttag';\n\nimport { useApiResult } from '@proton/components/hooks';\n\nimport { Gateway } from './Gateway';\nimport { GatewayUser } from './GatewayUser';\nimport { queryVPNGateways } from './api';\n\ninterface TableConfig {\n    Name: boolean;\n    Status: boolean;\n    Country: boolean;\n    IPv4: boolean;\n    IPv6: boolean;\n    Load: boolean;\n    Deleted?: boolean;\n}\n\ninterface GatewayConfig {\n    Table: TableConfig;\n    ServerTable: TableConfig;\n    Provisioning: {\n        TranslatedDuration: string;\n    };\n}\n\nexport const useGateways = () => {\n    const {\n        loading,\n        result,\n        request: refresh,\n    } = useApiResult<\n        {\n            Config: GatewayConfig;\n            Countries: readonly string[];\n            Gateways: readonly Gateway[];\n            Users: readonly GatewayUser[];\n        },\n        typeof queryVPNGateways\n    >(queryVPNGateways, []);\n\n    const nbDay = 7;\n\n    return {\n        loading: !result || loading,\n        config: result?.Config || {\n            Table: {\n                Name: false,\n                Status: true,\n                Country: true,\n                IPv4: true,\n                IPv6: false,\n                Load: false,\n            },\n            ServerTable: {\n                Name: false,\n                Status: true,\n                Country: true,\n                IPv4: true,\n                IPv6: false,\n                Load: true,\n            },\n            Provisioning: {\n                TranslatedDuration: c('Label').ngettext(msgid`${nbDay} day`, `${nbDay} days`, nbDay),\n            },\n        },\n        countries: result?.Countries,\n        gateways: result?.Gateways,\n        users: result?.Users || [],\n        refresh,\n    };\n};\n\nexport default useGateways;\n","import React, { useMemo, useState } from 'react';\n\nimport { c, msgid } from 'ttag';\n\nimport { Button, Href } from '@proton/atoms';\nimport { EmptyViewContainer, SUBSCRIPTION_STEPS, useSubscriptionModal } from '@proton/components/containers';\nimport { PLANS, SERVER_FEATURES, SORT_DIRECTION } from '@proton/shared/lib/constants';\nimport { getNonEmptyErrorMessage } from '@proton/shared/lib/helpers/error';\nimport { getVPNDedicatedIPs, hasVpnBusiness } from '@proton/shared/lib/helpers/subscription';\nimport { Organization } from '@proton/shared/lib/interfaces';\nimport gatewaySvg from '@proton/styles/assets/img/illustrations/gateway.svg';\nimport gatewaysEmptyStateAdminsSvg from '@proton/styles/assets/img/illustrations/gateways-empty-state-admins.svg';\nimport gatewaysEmptyStateUsersSvg from '@proton/styles/assets/img/illustrations/gateways-empty-state-users.svg';\n\nimport { Loader, Row, Table, TableBody, TableCell, useModalTwoStatic } from '../../../components';\nimport { useApi, useNotifications, useSortedList, useSubscription, useUser, useUserSettings } from '../../../hooks';\nimport { Gateway } from './Gateway';\nimport { GatewayLogical } from './GatewayLogical';\nimport GatewayModal from './GatewayModal';\nimport { GatewayModel } from './GatewayModel';\nimport GatewayRenameModal from './GatewayRenameModal';\nimport GatewayRow from './GatewayRow';\nimport GatewayServersModal from './GatewayServersModal';\nimport GatewayUsersModal from './GatewayUsersModal';\nimport { addIpInVPNGateway, createVPNGateway, deleteVPNGateway, renameVPNGateway, updateVPNGatewayUsers } from './api';\nimport { useGateways } from './useGateways';\n\ninterface Props {\n    organization?: Organization;\n    showCancelButton?: boolean;\n}\n\nconst getFeaturesAndUserIds = (data: Partial<GatewayModel>): [number, readonly string[] | null] => {\n    const features = data.Features || 0;\n\n    return [features, features & SERVER_FEATURES.DOUBLE_RESTRICTION ? data.UserIds || [] : null];\n};\n\nconst GatewaysSection = ({ organization, showCancelButton = true }: Props) => {\n    const api = useApi();\n    const [createModal, showCreateModal] = useModalTwoStatic(GatewayModal);\n    const [renameModal, showRenameModal] = useModalTwoStatic(GatewayRenameModal);\n    const [usersModal, showUsersModal] = useModalTwoStatic(GatewayUsersModal);\n    const [serversModal, showServersModal] = useModalTwoStatic(GatewayServersModal);\n    const [user] = useUser();\n    const { createNotification } = useNotifications();\n    const [userSettings] = useUserSettings();\n    const [subscription] = useSubscription();\n    const [deletedLogicals, setDeletedLogicals] = useState<Record<string, boolean>>({});\n    const [deletingLogicals, setDeletingLogicals] = useState<readonly string[]>([]);\n    const [createdGateways, setCreatedGateways] = useState<Gateway[]>([]);\n    const [updatedLogicals, setUpdatedLogicals] = useState<Record<string, GatewayLogical>>({});\n    const {\n        config: {\n            Table: { IPv4, IPv6, Load, Deleted },\n            ServerTable: serverTableConfig,\n            Provisioning: { TranslatedDuration: provisioningDuration },\n        },\n        users,\n        countries,\n        gateways,\n        refresh,\n    } = useGateways();\n    const refreshList = async () => {\n        setCreatedGateways([]);\n        setUpdatedLogicals({});\n        await refresh();\n    };\n    const allGateways = useMemo<readonly Gateway[]>(() => {\n        const ids: Record<string, true> = {};\n\n        return [...createdGateways, ...(gateways || [])]\n            .map((gateway) => ({\n                ...gateway,\n                Logicals: gateway.Logicals.filter((l) => !deletedLogicals[l.ID]).map((l) => updatedLogicals[l.ID] || l),\n            }))\n            .filter((gateway) => {\n                if (ids[gateway.Name]) {\n                    return false;\n                }\n\n                if (gateway.Logicals.length) {\n                    ids[gateway.Name] = true;\n\n                    return true;\n                }\n\n                return false;\n            });\n    }, [createdGateways, gateways, updatedLogicals, deletedLogicals]);\n    const { sortedList } = useSortedList(allGateways as Gateway[], { key: 'Name', direction: SORT_DIRECTION.ASC });\n    const [openSubscriptionModal] = useSubscriptionModal();\n\n    if (!organization || !user || !subscription || !gateways || !countries) {\n        return <Loader />;\n    }\n\n    const createGateway = async (apiRequest: any): Promise<Gateway> => {\n        const createdGateway = (await api<{ Gateway: Gateway }>(apiRequest))?.Gateway;\n\n        const newDeletedLogicals = { ...deletedLogicals };\n        const newUpdatedLogicals = { ...updatedLogicals };\n        let touched = false;\n\n        createdGateway.Logicals?.forEach((logical) => {\n            if ((newUpdatedLogicals[logical.ID] || newDeletedLogicals[logical.ID]) && logical.Visible) {\n                touched = true;\n\n                newUpdatedLogicals[logical.ID] = logical;\n                delete newDeletedLogicals[logical.ID];\n            }\n        });\n\n        if (touched) {\n            setDeletedLogicals(newDeletedLogicals);\n            setUpdatedLogicals(newUpdatedLogicals);\n        }\n\n        return createdGateway;\n    };\n\n    const getCustomizeSubscriptionOpener = (source: 'dashboard' | 'upsells') => () =>\n        openSubscriptionModal({\n            metrics: {\n                source,\n            },\n            step: SUBSCRIPTION_STEPS.CHECKOUT_WITH_CUSTOMIZATION,\n            plan: PLANS.VPN_BUSINESS,\n        });\n\n    const isAdmin = user.isAdmin && !user.isSubUser;\n\n    if (!hasVpnBusiness(subscription) && !(organization && organization.PlanName === PLANS.VPN_BUSINESS)) {\n        const boldDedicatedServers = (\n            <b key=\"bold-dedicated-servers\">{\n                // translator: Full sentence \"With a Business or Enterprise plan, you can purchase dedicated servers for your organization, and set up Gateways to control which users can access them\"\n                c('Info').t`dedicated servers`\n            }</b>\n        );\n        const boldGateways = (\n            <b key=\"bold-gateways\">{\n                // translator: Full sentence \"With a Business or Enterprise plan, you can purchase dedicated servers for your organization, and set up Gateways to control which users can access them\"\n                c('Info').t`Gateways`\n            }</b>\n        );\n\n        return (\n            <>\n                <Row className=\"rounded-lg\" style={{ 'background-color': 'var(--interaction-norm-minor-1)' }}>\n                    <div className=\"m-5 mt-6\" style={{ minWidth: '38px' }}>\n                        <img\n                            key=\"gateway-upgrade-image\"\n                            className=\"h-auto\"\n                            src={gatewaySvg}\n                            alt=\"\"\n                            width={96}\n                            height={96}\n                        />\n                    </div>\n                    <div className=\"m-4\">\n                        <p className=\"mb-2\">\n                            <b>{c('Info').t`Enhance your network security`}</b>\n                        </p>\n                        <p className=\"mt-2\">\n                            {\n                                // translator: Full sentence \"With a Business or Enterprise plan, you can purchase dedicated servers for your organization, and set up Gateways to control which users can access them\"\n                                c('Info')\n                                    .jt`With a Business or Enterprise plan, you can purchase ${boldDedicatedServers} for your organization, and set up ${boldGateways} to control which users can access them.`\n                            }{' '}\n                            <Href\n                                href=\"https://protonvpn.com/support/manage-vpn-servers-organization\"\n                                title={c('Info').t`Lean more about gateways`}\n                            >{c('Link').t`Learn more`}</Href>\n                        </p>\n                    </div>\n                    {isAdmin && (\n                        <div className=\"m-4 mr-6 shrink-0 self-center\">\n                            <Button\n                                color=\"norm\"\n                                onClick={getCustomizeSubscriptionOpener('upsells')}\n                                title={c('Title').t`Setup dedicated servers by upgrading to Business`}\n                            >\n                                {c('Action').t`Upgrade to Business`}\n                            </Button>\n                        </div>\n                    )}\n                </Row>\n            </>\n        );\n    }\n\n    const isDeleted = (logical: GatewayLogical): boolean => !logical.Visible && logical.Servers?.length > 0;\n\n    const ipAddresses = getVPNDedicatedIPs(subscription);\n    const deletedInCountries: Record<string, number> = {};\n    const ipCount = allGateways.reduce((total, gateway) => {\n        return (\n            total +\n            gateway.Logicals.reduce((sum, logical) => {\n                if (isDeleted(logical)) {\n                    deletedInCountries[gateway.ExitCountry] = (deletedInCountries[gateway.ExitCountry] || 0) + 1;\n\n                    return sum;\n                }\n\n                return sum + Math.max(1, logical.Servers?.length || 0);\n            }, 0)\n        );\n    }, 0);\n    const canAdd = ipAddresses > ipCount;\n    const language = userSettings.Locale || navigator.languages;\n\n    const createServersSequentially = async (\n        data: GatewayModel,\n        initialGateway?: Gateway,\n        key = 'gateway-creation',\n        getNotificationMessage?: (serverNumber: number, total: number) => string\n    ): Promise<Gateway | undefined> => {\n        const quantities = data.Quantities;\n\n        if (!quantities) {\n            return;\n        }\n\n        const countries = Object.keys(quantities);\n        const total = countries.reduce((total, country) => total + (quantities[country] || 0), 0);\n        let gatewayHost: Gateway | undefined = initialGateway;\n        let serverNumber = 0;\n\n        for (let i = 0; i < countries.length; i++) {\n            const country = countries[i];\n\n            for (let j = 0; j < quantities[country]; j++) {\n                ++serverNumber;\n\n                createNotification({\n                    key,\n                    text: getNotificationMessage\n                        ? getNotificationMessage(serverNumber, total)\n                        : /*\n                        translator: \"Creating gateway servers\" refers to the whole operation, so pluralization uses ${total}, not ${serverNumber}, \"Creating gateway servers: 1 / 3\" is plural in English because we are creating a gateway of 3 servers\n                        translator: This message appears when starting to creating a gateway that will contain ${total} server in the end (total is always an integer and at least 2, so for any language with \"One\" form < 2, don't care much about singular)\n                        */ c('Info').ngettext(\n                              msgid`Creating gateway server: ${serverNumber} / ${total}`,\n                              `Creating gateway servers: ${serverNumber} / ${total}`,\n                              total\n                          ),\n                    type: 'info',\n                });\n\n                if (!gatewayHost) {\n                    const [features, usersIds] = getFeaturesAndUserIds(data);\n\n                    gatewayHost = await createGateway(\n                        createVPNGateway({\n                            Name: data.Name,\n                            Country: country,\n                            Features: features,\n                            UserIds: usersIds,\n                        })\n                    );\n\n                    continue;\n                }\n\n                try {\n                    gatewayHost = await createGateway(\n                        addIpInVPNGateway({\n                            Name: gatewayHost.Name,\n                            Country: country,\n                        })\n                    );\n                } catch (error) {\n                    createNotification({\n                        key,\n                        text: getNonEmptyErrorMessage(error),\n                        type: 'warning',\n                    });\n\n                    return gatewayHost;\n                }\n            }\n        }\n\n        return gatewayHost;\n    };\n\n    const buildGateway = async (data: GatewayModel): Promise<Gateway | undefined> => {\n        if (data.Quantities) {\n            return createServersSequentially(data);\n        }\n\n        const [features, usersIds] = getFeaturesAndUserIds(data);\n\n        return createGateway(\n            createVPNGateway({\n                Name: data.Name,\n                Country: data.Country,\n                Features: features,\n                UserIds: usersIds,\n            })\n        );\n    };\n\n    const addGateway = () =>\n        showCreateModal({\n            showCancelButton,\n            countries,\n            deletedInCountries,\n            ownedCount: ipAddresses,\n            usedCount: ipCount,\n            users,\n            language,\n            onSubmitDone: async (data: GatewayModel) => {\n                const gateway = await buildGateway(data);\n\n                if (!gateway) {\n                    createNotification({\n                        text: c('Error').t`Impossible to create the gateway`,\n                        type: 'error',\n                    });\n\n                    return;\n                }\n\n                setCreatedGateways([...createdGateways, gateway]);\n            },\n            onUpsell: getCustomizeSubscriptionOpener('dashboard'),\n        });\n\n    const editGatewayServers = (gateway: Gateway) => () =>\n        showServersModal({\n            language,\n            showCancelButton,\n            gateway,\n            countries,\n            deletedInCountries,\n            users,\n            ownedCount: ipAddresses,\n            usedCount: ipCount,\n            showDeleted: serverTableConfig.Deleted,\n            showIPv4: serverTableConfig.IPv4,\n            showIPv6: serverTableConfig.IPv6,\n            showLoad: serverTableConfig.Load,\n            isDeleted,\n            onSubmitDone: async (deletedLogicalIds: readonly string[], addedQuantities: Record<string, number>) => {\n                const deletedServerCount = deletedLogicalIds.length;\n                const addedServerCount = Object.entries(addedQuantities).reduce(\n                    (total, [, quantity]) => total + quantity,\n                    0\n                );\n\n                if (deletedServerCount && addedServerCount) {\n                    createNotification({\n                        key: 'gateway-servers-editions',\n                        text: c('Info').ngettext(\n                            msgid`Deleting ${deletedServerCount} gateway server`,\n                            `Deleting ${deletedServerCount} gateway servers`,\n                            deletedServerCount\n                        ),\n                        type: 'info',\n                    });\n                }\n\n                if (deletedServerCount) {\n                    await api(deleteVPNGateway(deletedLogicalIds));\n                }\n\n                if (deletedServerCount && addedServerCount) {\n                    createNotification({\n                        key: 'gateway-servers-editions',\n                        text: c('Info').ngettext(\n                            msgid`Adding ${addedServerCount} gateway server`,\n                            `Adding ${addedServerCount} gateway servers`,\n                            addedServerCount\n                        ),\n                        type: 'info',\n                    });\n                }\n\n                if (addedServerCount) {\n                    await createServersSequentially(\n                        {\n                            Name: gateway.Name,\n                            Features: gateway.Logicals[0]?.Features,\n                            UserIds: gateway.Logicals[0]?.Users,\n                            Quantities: addedQuantities,\n                        },\n                        gateway,\n                        'gateway-servers-editions',\n                        (serverNumber: number, total: number) =>\n                            /*\n                            translator: \"Creating gateway servers\" refers to the whole operation, so pluralization uses ${total}, not ${serverNumber}, \"Creating gateway servers: 1 / 3\" is plural in English because we are creating a gateway of 3 servers\n                            translator: This message appears when starting to creating a gateway that will contain ${total} server in the end (total is always an integer and at least 2, so for any language with \"One\" form < 2, don't care much about singular)\n                            */ c('Info').ngettext(\n                                msgid`Adding gateway server: ${serverNumber} / ${total}`,\n                                `Adding gateway servers: ${serverNumber} / ${total}`,\n                                total\n                            )\n                    );\n                }\n\n                await refreshList();\n            },\n            onUpsell: getCustomizeSubscriptionOpener('dashboard'),\n        });\n\n    const editGatewayUsers = (gateway: Gateway, logical: GatewayLogical) => () =>\n        showUsersModal({\n            showCancelButton,\n            model: {\n                features: logical.Features,\n                userIds: logical.Users,\n            },\n            users,\n            onSubmitDone: async (data: GatewayModel) => {\n                const [features, usersIds] = getFeaturesAndUserIds(data);\n\n                const update = await api<{ Gateway: Gateway }>(updateVPNGatewayUsers(gateway.Name, features, usersIds));\n\n                if (!update?.Gateway) {\n                    createNotification({\n                        text: c('Error').t`Impossible to edit the gateway`,\n                        type: 'error',\n                    });\n\n                    return;\n                }\n\n                await refreshList();\n            },\n        });\n\n    const renameGateway = (id: string, currentName: string) => () => {\n        if (deletingLogicals.indexOf(id) !== -1) {\n            return;\n        }\n\n        showRenameModal({\n            showCancelButton,\n            currentName,\n            onSubmitDone: async ({ Name: newName }: { Name: string }) => {\n                const gateway = await api<{ Gateway: Gateway }>(renameVPNGateway(currentName, newName));\n\n                if (!gateway?.Gateway) {\n                    createNotification({\n                        text: c('Error').t`Impossible to rename the gateway`,\n                        type: 'error',\n                    });\n\n                    return;\n                }\n\n                await refreshList();\n            },\n        });\n    };\n\n    const deleteGateway = (gateway: Gateway) => async () => {\n        const ids = gateway.Logicals.map(({ ID }) => ID);\n\n        if (deletingLogicals.some((id) => ids.indexOf(id) !== -1)) {\n            return;\n        }\n\n        setDeletingLogicals([...deletingLogicals, ...ids]);\n\n        try {\n            const { Logicals: logicals } = await api<{ Logicals: GatewayLogical[] }>(deleteVPNGateway(ids));\n            const update = { ...updatedLogicals };\n            const kept: Record<string, boolean> = {};\n\n            logicals.forEach((logical) => {\n                kept[logical.ID] = true;\n                update[logical.ID] = logical;\n            });\n\n            setUpdatedLogicals(update);\n\n            if (ids.length !== Object.keys(kept).length) {\n                const removed: Record<string, boolean> = { ...deletedLogicals };\n\n                ids.forEach((id) => {\n                    if (!kept[id]) {\n                        removed[id] = true;\n                    }\n                });\n\n                setDeletedLogicals(removed);\n            }\n        } finally {\n            setDeletingLogicals(deletingLogicals.filter((deletingId) => ids.indexOf(deletingId) === -1));\n        }\n    };\n\n    return (\n        <>\n            {isAdmin && (\n                <>\n                    {createModal}\n                    {renameModal}\n                    {serversModal}\n                    {usersModal}\n                    <div className=\"mb-4 flex items-center gap-2\">\n                        <span className=\"color-weak\">\n                            {c('Info').ngettext(\n                                msgid`You are currently using ${ipCount} of your ${ipAddresses} available dedicated server.`,\n                                `You are currently using ${ipCount} of your ${ipAddresses} available dedicated servers.`,\n                                ipAddresses\n                            )}\n                        </span>\n                        <Button\n                            size=\"small\"\n                            color=\"norm\"\n                            shape={canAdd ? 'outline' : 'solid'}\n                            onClick={getCustomizeSubscriptionOpener('dashboard')}\n                            title={c('Title').t`Customize the number of IP addresses in your plan`}\n                        >\n                            {c('Action').t`Get more servers`}\n                        </Button>\n                    </div>\n                </>\n            )}\n\n            {sortedList.length ? (\n                <>\n                    {isAdmin && (\n                        <div className=\"mb-4\">\n                            <Button\n                                color=\"norm\"\n                                disabled={!canAdd}\n                                onClick={addGateway}\n                                title={c('Title').t`Create a new Gateway`}\n                            >\n                                {c('Action').t`Create Gateway`}\n                            </Button>\n                        </div>\n                    )}\n\n                    <Table className=\"my-2\">\n                        <thead>\n                            <tr>\n                                <TableCell key=\"name\" type=\"header\">{c('Header').t`Name`}</TableCell>\n                                <TableCell key=\"status\" type=\"header\" className=\"w-1/10\">\n                                    {c('Header').t`Status`}\n                                </TableCell>\n                                <TableCell key=\"servers\" type=\"header\">{c('Header').t`Servers`}</TableCell>\n                                {isAdmin && (\n                                    <>\n                                        <TableCell key=\"members\" type=\"header\">{c('Header').t`Members`}</TableCell>\n                                        <TableCell\n                                            key=\"manage\"\n                                            type=\"header\"\n                                            className=\"w-custom\"\n                                            style={{ '--w-custom': '12rem' }}\n                                        >\n                                            &nbsp;\n                                        </TableCell>\n                                    </>\n                                )}\n                            </tr>\n                        </thead>\n                        <TableBody colSpan={3 + (isAdmin ? 2 : 0)}>\n                            {sortedList.map((gateway) => (\n                                <GatewayRow\n                                    key={'gateway-' + gateway.Name}\n                                    isAdmin={isAdmin}\n                                    showDeleted={Deleted}\n                                    showIPv4={IPv4}\n                                    showIPv6={IPv6}\n                                    showLoad={Load}\n                                    gateway={gateway}\n                                    isDeleted={isDeleted}\n                                    users={users ?? []}\n                                    language={language}\n                                    provisioningDuration={provisioningDuration}\n                                    renameGateway={renameGateway}\n                                    editGatewayServers={editGatewayServers}\n                                    editGatewayUsers={editGatewayUsers}\n                                    deleteGateway={deleteGateway}\n                                    deletingLogicals={deletingLogicals}\n                                    deletedLogicals={deletedLogicals}\n                                />\n                            ))}\n                        </TableBody>\n                    </Table>\n                </>\n            ) : (\n                <EmptyViewContainer\n                    key=\"no-gateways-container\"\n                    imageProps={{\n                        src: isAdmin ? gatewaysEmptyStateAdminsSvg : gatewaysEmptyStateUsersSvg,\n                        title: c('Info').t`No gateways`,\n                        key: 'no-gateways-image',\n                    }}\n                >\n                    <h3 className=\"text-bold\">\n                        {isAdmin ? c('Info').t`Create your first Gateway` : c('Info').t`No Gateways yet`}\n                    </h3>\n                    <p className=\"color-weak\">\n                        {isAdmin\n                            ? c('Info')\n                                  .t`Organize your dedicated servers into Gateways and decide which members can access them.`\n                            : c('Info').t`Ask your organisation admin to setup Gateways.`}\n                    </p>\n\n                    {isAdmin && (\n                        <div>\n                            <Button\n                                color=\"norm\"\n                                disabled={!canAdd}\n                                onClick={addGateway}\n                                title={c('Title').t`Create a new gateway`}\n                            >\n                                {c('Action').t`Create Gateway`}\n                            </Button>\n                        </div>\n                    )}\n                </EmptyViewContainer>\n            )}\n        </>\n    );\n};\n\nexport default GatewaysSection;\n","import {\n    PrivateMainArea,\n    SettingsPageTitle,\n    SettingsParagraph,\n    SettingsSection,\n    SettingsSectionTitle,\n} from '@proton/components';\n\nconst PrivateMainAreaLoading = () => {\n    return (\n        <PrivateMainArea>\n            <div className=\"container-section-sticky\">\n                <SettingsPageTitle className=\"my-14 settings-loading-page-title\" />\n                <section className=\"container-section-sticky-section\">\n                    <SettingsSectionTitle className=\"settings-loading-section-title\" />\n                    <SettingsSection>\n                        <SettingsParagraph className=\"mb-4\">\n                            <span className=\"block settings-loading-paragraph-line\" />\n                            <span className=\"block settings-loading-paragraph-line\" />\n                            <span className=\"block settings-loading-paragraph-line\" />\n                        </SettingsParagraph>\n                    </SettingsSection>\n                </section>\n            </div>\n        </PrivateMainArea>\n    );\n};\nexport default PrivateMainAreaLoading;\n","import { c, msgid } from 'ttag';\n\nimport { Card } from '@proton/atoms';\nimport { useMembers } from '@proton/components';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { Loader } from '../../components';\n\ninterface Props {\n    organization?: Organization;\n}\n\nconst OrganizationTwoFAHeader = ({ organization }: Props) => {\n    const [members] = useMembers();\n\n    if (!organization || !members) {\n        return <Loader />;\n    }\n\n    const twoFAMembers = members.filter((member) => member['2faStatus'] !== 0) || [];\n\n    // translator: the variables here are numbers, e.g. \"2/4 of your organization members use two-factor authentication.\"\n    const cardContent = c('Loading info').ngettext(\n        msgid`${twoFAMembers.length}/${members.length} of your organization member use two-factor authentication.`,\n        `${twoFAMembers.length}/${members.length} of your organization members use two-factor authentication.`,\n        members.length\n    );\n\n    return (\n        <Card rounded background bordered={false} className=\"max-w-custom\" style={{ '--max-w-custom': '43em' }}>\n            {cardContent}\n        </Card>\n    );\n};\n\nexport default OrganizationTwoFAHeader;\n","import { c } from 'ttag';\n\nimport { Avatar, Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { sendEmailReminderTwoFA } from '@proton/shared/lib/api/organization';\nimport { MEMBER_ROLE } from '@proton/shared/lib/constants';\nimport { getInitials } from '@proton/shared/lib/helpers/string';\nimport { Address, Member, PartialMemberAddress } from '@proton/shared/lib/interfaces';\nimport noop from '@proton/utils/noop';\n\nimport {\n    Badge,\n    Form,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../components';\nimport { useApi, useEventManager, useNotifications } from '../../hooks';\n\ninterface Props extends ModalProps {\n    members: Member[];\n    memberAddressesMap: { [key: string]: (Address | PartialMemberAddress)[] | undefined };\n}\n\nconst SendEmailReminderTwoFAModal = ({ onClose, members, memberAddressesMap, ...rest }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const { onFormSubmit } = useFormErrors();\n    const [loading, withLoading] = useLoading();\n\n    const handleSubmit = async () => {\n        await api(sendEmailReminderTwoFA());\n        await call();\n        createNotification({ text: c('Notification').t`Reminder has been sent` });\n        onClose?.();\n    };\n\n    const handleClose = loading ? noop : onClose;\n\n    return (\n        <Modal\n            as={Form}\n            onSubmit={() => {\n                if (!onFormSubmit()) {\n                    return;\n                }\n                void withLoading(handleSubmit());\n            }}\n            onClose={handleClose}\n            {...rest}\n        >\n            <ModalHeader title={c('Title').t`Send email reminders?`} />\n            <ModalContent>\n                <p>{c('Info')\n                    .t`The following members will receive an email prompting them to enable two-factor authentication as soon as possible.`}</p>\n                <ul className=\"unstyled\">\n                    {members\n                        .filter(function (member) {\n                            const memberAddresses = memberAddressesMap?.[member.ID] || [];\n                            return memberAddresses.length > 0;\n                        })\n                        .map((member) => {\n                            const memberAddresses = memberAddressesMap?.[member.ID] || [];\n                            return (\n                                <li className=\"py-2 flex flex-nowrap items-center border-bottom\" title={member.Name}>\n                                    <Avatar className=\"mr-2 shrink-0\">{getInitials(member.Name)}</Avatar>\n                                    <div>\n                                        <div className=\"text-ellipsis max-100\" title={member.Name}>\n                                            {member.Name}\n                                        </div>\n                                        <div className=\"max-w-full flex\">\n                                            <span className=\"flex-1 mr-2 text-ellipsis\">\n                                                {memberAddresses[0]?.Email}\n                                            </span>\n                                            {member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN && (\n                                                <span className=\"shrink-0\">\n                                                    <Badge type=\"light\">{c('Admin').t`admin`}</Badge>\n                                                </span>\n                                            )}\n                                        </div>\n                                    </div>\n                                </li>\n                            );\n                        })}\n                </ul>\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={handleClose} disabled={loading}>\n                    {c('Action').t`Cancel`}\n                </Button>\n                <Button loading={loading} type=\"submit\" color=\"norm\" disabled={loading}>\n                    {c('Action').t`Send reminder`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default SendEmailReminderTwoFAModal;\n","import { c } from 'ttag';\n\nimport { useMemberAddresses } from '@proton/account';\nimport { Button } from '@proton/atoms/Button';\nimport { Info, useConfig, useMembers, useModalState } from '@proton/components';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { Label, Loader, Row } from '../../components';\nimport { SettingsParagraph } from '../account';\nimport SendEmailReminderTwoFAModal from './SendEmailReminderTwoFAModal';\n\ninterface Props {\n    organization?: Organization;\n}\n\nconst OrganizationTwoFARemindersSection = ({ organization }: Props) => {\n    const { APP_NAME } = useConfig();\n    const [modalProps, setModal, renderModal] = useModalState();\n    const [members] = useMembers();\n    const noTwoFAMembers =\n        members?.filter((member) => (member.State === undefined || member.State === 1) && member['2faStatus'] === 0) ||\n        [];\n\n    const { value: memberAddressesMap } = useMemberAddresses({ members, partial: true });\n\n    if (!organization || !members) {\n        return <Loader />;\n    }\n\n    return (\n        <>\n            {renderModal && (\n                <SendEmailReminderTwoFAModal\n                    {...modalProps}\n                    members={noTwoFAMembers}\n                    memberAddressesMap={memberAddressesMap}\n                />\n            )}\n            <SettingsParagraph\n                learnMoreUrl={\n                    APP_NAME === APPS.PROTONVPN_SETTINGS\n                        ? 'https://protonvpn.com/support/require-2fa-organization'\n                        : getKnowledgeBaseUrl('/two-factor-authentication-organization')\n                }\n            >\n                {c('Info').t`Send emails to encourage your members to protect their accounts with 2FA.`}\n            </SettingsParagraph>\n            <Row className=\"mt-1\">\n                <Label>\n                    <span className=\"mr-0.5\">{c('Label').t`Email`}</span>\n                    <span className=\"hidden md:inline\">\n                        <Info\n                            title={c('Tooltip')\n                                .t`Members who do not use 2FA will get an email asking them to enable it as soon as possible.`}\n                        />\n                    </span>\n                </Label>\n                <div className=\"flex items-center\">\n                    <Button\n                        id=\"send-email-reminder-button\"\n                        onClick={() => setModal(true)}\n                        disabled={noTwoFAMembers.length === 0}\n                    >{c('Action').t`Send email reminder`}</Button>\n                </div>\n            </Row>\n        </>\n    );\n};\n\nexport default OrganizationTwoFARemindersSection;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Info, useApi } from '@proton/components';\nimport { queryEnforceTwoFA, queryRemoveTwoFA } from '@proton/shared/lib/api/organization';\nimport { APPS, ORGANIZATION_TWOFA_SETTING } from '@proton/shared/lib/constants';\nimport { hasTwoFARequiredForAdminOnly, hasTwoFARequiredForAll } from '@proton/shared/lib/helpers/organization';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { Loader, Toggle } from '../../components';\nimport { useConfig, useNotifications } from '../../hooks';\nimport { SettingsLayout, SettingsLayoutLeft, SettingsLayoutRight, SettingsParagraph } from '../account';\n\ninterface Props {\n    organization?: Organization;\n}\n\nconst OrganizationTwoFAEnforcementSection = ({ organization }: Props) => {\n    const api = useApi();\n    const { APP_NAME } = useConfig();\n\n    const [isTwoFARequiredForAdminOnlyChecked, setIsTwoFARequiredForAdminOnlyChecked] = useState(\n        hasTwoFARequiredForAdminOnly(organization)\n    );\n    const [isTwoFARequiredForAllChecked, setIsTwoFARequiredForAllChecked] = useState(\n        hasTwoFARequiredForAll(organization)\n    );\n    const { createNotification } = useNotifications();\n\n    if (!organization) {\n        return <Loader />;\n    }\n\n    const handleEnforceTwoFA = async (require: number) => {\n        await api(queryEnforceTwoFA(require));\n        if (require === ORGANIZATION_TWOFA_SETTING.REQUIRED_ADMIN_ONLY) {\n            setIsTwoFARequiredForAdminOnlyChecked(true);\n            setIsTwoFARequiredForAllChecked(false);\n            createNotification({\n                text: c('Notification').t`Two-factor authentication has been enforced for administrators`,\n            });\n            return;\n        }\n        setIsTwoFARequiredForAdminOnlyChecked(true);\n        setIsTwoFARequiredForAllChecked(true);\n        createNotification({\n            text: c('Notification').t`Two-factor authentication has been enforced for all members`,\n        });\n    };\n\n    const handleRemoveTwoFA = async () => {\n        await api(queryRemoveTwoFA());\n        setIsTwoFARequiredForAdminOnlyChecked(false);\n        setIsTwoFARequiredForAllChecked(false);\n        createNotification({\n            text: c('Notification').t`Two-factor authentication is not required anymore`,\n        });\n    };\n\n    return (\n        <>\n            <SettingsParagraph>\n                {c('Info')\n                    .t`We recommend notifying the organization members and asking them to set up 2FA for their accounts before enforcing the use of 2FA.`}\n            </SettingsParagraph>\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"two-fa-admin\" className=\"text-semibold\">\n                        <span className=\"mr-0.5\">{c('Label').t`Require 2FA for administrators`}</span>\n                        <Info\n                            url={\n                                APP_NAME === APPS.PROTONVPN_SETTINGS\n                                    ? 'https://protonvpn.com/support/require-2fa-organization'\n                                    : getKnowledgeBaseUrl('/two-factor-authentication-2fa')\n                            }\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight isToggleContainer>\n                    <Toggle\n                        id=\"two-fa-admin\"\n                        checked={isTwoFARequiredForAdminOnlyChecked || isTwoFARequiredForAllChecked}\n                        disabled={isTwoFARequiredForAllChecked}\n                        onChange={() =>\n                            !isTwoFARequiredForAdminOnlyChecked\n                                ? handleEnforceTwoFA(ORGANIZATION_TWOFA_SETTING.REQUIRED_ADMIN_ONLY)\n                                : handleRemoveTwoFA()\n                        }\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"two-fa-member\" className=\"text-semibold\">\n                        <span className=\"mr-0.5\">{c('Label').t`Require 2FA for everyone`}</span>\n                        <Info\n                            url={\n                                APP_NAME === APPS.PROTONVPN_SETTINGS\n                                    ? 'https://protonvpn.com/support/require-2fa-organization'\n                                    : getKnowledgeBaseUrl('/two-factor-authentication-2fa')\n                            }\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight isToggleContainer>\n                    <Toggle\n                        id=\"two-fa-member\"\n                        checked={isTwoFARequiredForAllChecked}\n                        onChange={() =>\n                            !isTwoFARequiredForAllChecked\n                                ? handleEnforceTwoFA(ORGANIZATION_TWOFA_SETTING.REQUIRED_ALL)\n                                : handleRemoveTwoFA()\n                        }\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n        </>\n    );\n};\n\nexport default OrganizationTwoFAEnforcementSection;\n","import { createHooks } from '@proton/redux-utilities';\n\nimport { samlSSOThunk, selectSamlSSO } from './index';\n\nconst hooks = createHooks(samlSSOThunk, selectSamlSSO);\n\nexport const useSamlSSO = hooks.useValue;\nexport const useGetSamlSSO = hooks.useGet;\n","import { DragEvent, DragEventHandler } from 'react';\n\nexport const isDragFile = (event: DragEvent) => event.dataTransfer?.types?.includes('Files');\n\nexport const onlyDragFiles = (eventHandler: DragEventHandler) => (event: DragEvent) => {\n    if (isDragFile(event)) {\n        return eventHandler(event);\n    }\n};\n","import { DragEvent, DragEventHandler, useState } from 'react';\n\ninterface Options {\n    onDragOver?: (event: DragEvent) => void;\n    onDragEnter?: (event: DragEvent) => void;\n    onDragLeave?: (event: DragEvent) => void;\n    onDrop?: (event: DragEvent) => void;\n}\n\ntype DragOverReturn = [\n    dragsOver: boolean,\n    dragHandlers: {\n        onDragEnter: DragEventHandler;\n        onDragLeave: DragEventHandler;\n        onDragOver: DragEventHandler;\n        onDrop: DragEventHandler;\n    },\n];\n\n/**\n * Hooks to manage a dragOver flag\n * Takes an optional filter function to accept only specific drag content\n * Returns the flag and the handlers to pass to the element you want to drag on\n */\nconst useDragOver = (\n    dragFilter: (event: DragEvent) => boolean = () => true,\n    dropEffect: 'none' | 'copy' | 'link' | 'move' = 'move',\n    { onDragOver, onDragEnter, onDragLeave, onDrop }: Options = {}\n): DragOverReturn => {\n    const [dragOver, setDragOver] = useState(0);\n\n    const handleDragEnter = (event: DragEvent) => {\n        if (dragFilter(event)) {\n            event.preventDefault();\n            if (dragOver === 0) {\n                onDragEnter?.(event);\n            }\n            setDragOver((old) => old + 1);\n        }\n    };\n    const handleDragLeave = (event: DragEvent) => {\n        if (dragFilter(event)) {\n            event.preventDefault();\n            if (dragOver === 1) {\n                onDragLeave?.(event);\n            }\n            setDragOver((old) => old - 1);\n        }\n    };\n    const handleDragOver = (event: DragEvent) => {\n        if (dragFilter(event)) {\n            if (event.dataTransfer.effectAllowed === 'all') {\n                event.dataTransfer.dropEffect = dropEffect;\n            }\n            event.preventDefault();\n            onDragOver?.(event);\n        }\n    };\n\n    const handleDrop = (event: DragEvent) => {\n        event.preventDefault();\n        setDragOver(0);\n        onDrop?.(event);\n    };\n\n    return [\n        dragOver > 0,\n        { onDragEnter: handleDragEnter, onDragLeave: handleDragLeave, onDragOver: handleDragOver, onDrop: handleDrop },\n    ];\n};\n\nexport default useDragOver;\n","import { c } from 'ttag';\n\nimport dragAndDrop from '@proton/styles/assets/img/illustrations/drag-and-drop-img.svg';\nimport clsx from '@proton/utils/clsx';\n\nimport { DropzoneProps } from './Dropzone';\n\nexport interface DropzoneContentProps\n    extends Pick<\n        DropzoneProps,\n        'size' | 'shape' | 'rounded' | 'border' | 'customContent' | 'className' | 'contentTitle' | 'contentSubText'\n    > {\n    /** Embedded in iframe */\n    embedded?: boolean;\n}\n\nconst DropzoneContent = ({\n    border,\n    className,\n    customContent,\n    rounded,\n    shape,\n    size,\n    embedded = false,\n    contentTitle = c('Info').t`Drop to import`,\n    contentSubText,\n}: DropzoneContentProps) => {\n    const isSmallDropView = size === 'small';\n    const isLargeDropView = size === 'large';\n\n    const isTransparentShape = shape === 'transparent';\n    const isFlashyShape = shape === 'flashy';\n    const isWhite = shape === 'white';\n\n    const getSubText = () => {\n        if (contentSubText) {\n            return contentSubText;\n        } else {\n            if (isLargeDropView) {\n                return c('Info').t`Your files will be encrypted and then saved`;\n            } else {\n                return c('Info').t`Drop file here to upload`;\n            }\n        }\n    };\n\n    const subText = getSubText();\n\n    /** Prefix css classes with `proton-` for iframe embedded situation */\n    const prefixClasses = (classes: string) =>\n        embedded\n            ? classes\n                  .split(' ')\n                  .map((className) => `proton-${className}`)\n                  .join(' ')\n            : classes;\n\n    return (\n        <div\n            className={clsx(\n                'dropzone-content dropzone-content--hovered',\n                prefixClasses('flex justify-center items-center'),\n                embedded ? 'dropzone-content--embedded' : 'h-full w-full absolute inset-0',\n                rounded && prefixClasses('rounded-xl'),\n                border && 'dropzone--bordered',\n                isTransparentShape && 'dropzone-content--transparent',\n                isFlashyShape && 'dropzone-content--flashy',\n                isWhite && 'dropzone-content--white',\n                className\n            )}\n        >\n            {customContent ? (\n                customContent\n            ) : (\n                <div className={prefixClasses('text-center')}>\n                    {!isSmallDropView && (\n                        <img src={dragAndDrop} alt=\"\" aria-hidden=\"true\" className={prefixClasses('mb-4')} />\n                    )}\n                    {isLargeDropView ? (\n                        <p className={prefixClasses('mb-0 mt-5')}>\n                            <span className={prefixClasses('text-xl text-bold')}>{contentTitle}</span>\n                            <br />\n                            <span className={!isFlashyShape ? prefixClasses('color-weak') : undefined}>{subText}</span>\n                        </p>\n                    ) : (\n                        <p className={clsx(prefixClasses('m-0'), !isFlashyShape && prefixClasses('color-weak'))}>\n                            {subText}\n                        </p>\n                    )}\n                </div>\n            )}\n        </div>\n    );\n};\n\nexport default DropzoneContent;\n","import { ComponentPropsWithoutRef, DragEvent as ReactDragEvent, ReactNode, cloneElement } from 'react';\n\nimport { isDragFile } from '@proton/components/components';\nimport { useDragOver } from '@proton/components/hooks';\n\nimport DropzoneContent from './DropzoneContent';\n\nimport './Dropzone.scss';\n\nexport type DropzoneSize = 'small' | 'medium' | 'large';\nexport type DropzoneShape = 'norm' | 'transparent' | 'flashy' | 'white' | 'invisible';\n\nexport interface DropzoneProps extends Omit<ComponentPropsWithoutRef<'div'>, 'onDrop'> {\n    /**\n     * Action to trigger when dropping files on top of the dropzone\n     */\n    onDrop: (files: File[]) => void;\n    /**\n     * Content to display when no hover\n     */\n    children: JSX.Element;\n    /**\n     * Custom content to show when dragging over the Dropzone\n     */\n    customContent?: ReactNode;\n    /**\n     * Dropzone's size : small | medium | large\n     */\n    size?: DropzoneSize;\n    /**\n     * Dropzone has a border\n     */\n    border?: boolean;\n    /**\n     * Dropzone's border is rounded\n     */\n    rounded?: boolean;\n    /**\n     * Dropzone's shade : norm | transparent | flashy | white | invisible\n     */\n    shape?: DropzoneShape;\n    /**\n     * Dropzone is always on dragOver state, content is always displayed\n     */\n    showDragOverState?: boolean;\n    /**\n     * Dropzone has no dragOver state, and onDrop cannot be triggered\n     */\n    disabled?: boolean;\n    /**\n     * Prevents setting the Dropzone's children div to position \"relative\"\n     */\n    isStatic?: boolean;\n    /**\n     * Title displayed under the illustration in \"large\" Dropzones (without custom content). Default text is \"Drop to import\"\n     */\n    contentTitle?: string;\n    /**\n     * Sub text displayed under the illustration in Dropzones (without custom content).\n     * Default text is \"Drop file here to upload\" for \"small\" and \"medium\" Dropzones,\n     * and \"Your files will be encrypted and then saved\" for \"large\" Dropzones\n     */\n    contentSubText?: string;\n}\n\nconst Dropzone = ({\n    className,\n    children,\n    customContent,\n    onDrop,\n    disabled = false,\n    showDragOverState = false,\n    size = 'medium',\n    rounded = true,\n    border = true,\n    shape = 'norm',\n    isStatic = false,\n    contentTitle,\n    contentSubText,\n    ...rest\n}: DropzoneProps) => {\n    const handleDrop = (event: ReactDragEvent) => {\n        if (!disabled) {\n            onDrop([...event.dataTransfer.files]);\n        }\n    };\n\n    const [hovering, dragProps] = useDragOver(isDragFile, 'move', { onDrop: handleDrop });\n\n    const isInvisible = shape === 'invisible';\n\n    // We need to display the dropzone content when:\n    // - We are on dragOver state\n    // - We force to always display the dragOver state\n    // BUT, we don't want to show it when:\n    // - Dropzone is completely disabled\n    // - The dropzone is invisible (we always show the children)\n    const shouldDisplayDropzoneContent = (hovering || showDragOverState) && !disabled && !isInvisible;\n\n    const dropzoneContent = shouldDisplayDropzoneContent ? (\n        <DropzoneContent\n            border={border}\n            className={className}\n            customContent={customContent}\n            rounded={rounded}\n            shape={shape}\n            size={size}\n            contentTitle={contentTitle}\n            contentSubText={contentSubText}\n        />\n    ) : null;\n\n    /**\n     * Warning:\n     * To display this dropzone we had two solutions\n     * 1. Add a container, wrapping the child and the content\n     * 2. Clone the element and update some props\n     *\n     * The first solution is easier to implement and to use, however in some cases (mostly CSS), adding this container could break the UI\n     * The developer would then need to do tricky CSS manipulation in order to get a working dropzone.\n     *\n     * To avoid having a container div which would contain the children and the content, we clone the children element.\n     * However, the Dropzone children might need some configuration to work properly:\n     * Because we're adding the dropzone content as a new children, and we're adding some props to the children element,\n     * you'll need to spread the rest operator in the wrapping div AND render the children.\n     */\n    return cloneElement(children, {\n        ...children.props,\n        ...dragProps,\n        ...rest,\n        style:\n            shouldDisplayDropzoneContent && !isStatic\n                ? { position: 'relative', ...children.props.style }\n                : { ...children.props.style },\n        children: (\n            <>\n                {children.props.children}\n                {dropzoneContent}\n            </>\n        ),\n    });\n};\n\nexport default Dropzone;\n","import { c } from 'ttag';\n\nimport { Input } from '@proton/atoms/Input';\nimport { Copy, InputFieldTwo } from '@proton/components/components';\nimport { InputFieldProps } from '@proton/components/components/v2/field/InputField';\nimport { useNotifications } from '@proton/components/hooks';\nimport clsx from '@proton/utils/clsx';\n\ninterface Props extends Omit<InputFieldProps<typeof Input>, 'readonly' | 'unstyled'> {}\n\nconst ReadonlyFieldWithCopy = ({ value, inputContainerClassName, ...rest }: Props) => {\n    const { createNotification } = useNotifications();\n\n    const onCopy = () => {\n        createNotification({ text: c('Info').t`Copied to clipboard` });\n    };\n\n    return (\n        <InputFieldTwo\n            value={value}\n            readOnly\n            inputContainerClassName={clsx('w-full', inputContainerClassName)}\n            suffix={<Copy size=\"small\" shape=\"ghost\" color=\"weak\" value={`${value}`} onCopy={onCopy} />}\n            {...rest}\n        />\n    );\n};\n\nexport default ReadonlyFieldWithCopy;\n","import { c } from 'ttag';\n\nimport { Href } from '@proton/atoms/Href';\nimport { VPN_APP_NAME } from '@proton/shared/lib/constants';\n\nimport ReadonlyFieldWithCopy from './ReadonlyFieldWithCopy';\n\nexport interface IdentityProviderEndpointsContentProps {\n    issuerID: string;\n    callbackURL: string;\n}\n\nconst IdentityProviderEndpointsContent = ({ issuerID, callbackURL }: IdentityProviderEndpointsContentProps) => {\n    // Using a function here so that we can extend to other applications without requiring retranslation of this string\n    const getDescriptionString = (appName: typeof VPN_APP_NAME) => {\n        // translator: variable here is an application name. Example full sentence \"When enabling SAML for Proton VPN in your identity provider, you might be prompted to use the callback (ACS) URL and issuer ID. Just copy-paste the data below into your identity provider fields.\"\n        return c('Info')\n            .t`When enabling SAML for ${appName} in your identity provider, you might be prompted to use the callback (ACS) URL and issuer ID. Just copy-paste the data below into your identity provider fields.`;\n    };\n\n    return (\n        <div className=\"flex flex-column gap-4\">\n            <div>\n                {getDescriptionString(VPN_APP_NAME)}\n                <br />\n                <Href href=\"https://protonvpn.com/support/sso\">{c('Info').t`Learn more`}</Href>\n            </div>\n            <ReadonlyFieldWithCopy\n                label={c('Label').t`Assertion Consumer Service URL`}\n                value={callbackURL}\n                assistiveText={c('Info')\n                    .t`Copy and paste this URL into the ACS (Assertion Consumer Service) URL field of your identity provider`}\n            />\n            <ReadonlyFieldWithCopy\n                label={c('Label').t`Issuer ID`}\n                value={issuerID}\n                assistiveText={c('Info').t`Copy and paste this URL into the entity ID field of your identity provider`}\n            />\n        </div>\n    );\n};\n\nexport default IdentityProviderEndpointsContent;\n","import { Button } from '@proton/atoms/Button';\nimport { Icon } from '@proton/components/components';\nimport { shortHumanSize } from '@proton/shared/lib/helpers/humanSize';\n\ninterface Props {\n    file: File;\n    onRemoveClick: () => void;\n}\n\nconst UploadedXmlFile = ({ file, onRemoveClick }: Props) => {\n    return (\n        <div className=\"rounded border border-weak flex flex-nowrap items-center max-w-full\">\n            <div className=\"p-1.5 flex flex-nowrap items-center gap-2\" title={file.name}>\n                <div className=\"p-1 bg-strong rounded-sm flex shrink-0\">\n                    <Icon name=\"code\" />\n                </div>\n                <span className=\"text-ellipsis\">{file.name}</span>\n                <span className=\"color-weak shrink-0\">{shortHumanSize(file.size)}</span>\n            </div>\n            <Button className=\"shrink-0\" icon shape=\"ghost\" onClick={onRemoveClick}>\n                <Icon name=\"cross-big\" />\n            </Button>\n        </div>\n    );\n};\n\nexport default UploadedXmlFile;\n","import { ReactNode, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button, Href } from '@proton/atoms';\nimport TextArea from '@proton/components/components/v2/input/TextArea';\nimport { useApi, useEventManager, useNotifications } from '@proton/components/hooks';\nimport useLoading from '@proton/hooks/useLoading';\nimport metrics, { observeApiError } from '@proton/metrics';\nimport { setupSAMLFields, setupSAMLUrl, setupSAMLXml } from '@proton/shared/lib/api/samlSSO';\nimport { VPN_APP_NAME } from '@proton/shared/lib/constants';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Domain } from '@proton/shared/lib/interfaces';\nimport dragAndDrop from '@proton/styles/assets/img/illustrations/drag-and-drop-img.svg';\n\nimport {\n    Dropzone,\n    Form,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    RadioGroup,\n    useFormErrors,\n} from '../../../components';\nimport IdentityProviderEndpointsContent, {\n    IdentityProviderEndpointsContentProps,\n} from './IdentityProviderEndpointsContent';\nimport UploadedXmlFile from './UploadedXmlFile';\n\nenum STEP {\n    IDP_VALUES,\n    SAML_METADATA,\n}\n\nenum METADATA_METHOD {\n    URL,\n    XML,\n    TEXT,\n}\n\ninterface MetadataState {\n    [METADATA_METHOD.URL]: {\n        value: string;\n    };\n    [METADATA_METHOD.XML]: {\n        file: File | null;\n    };\n    [METADATA_METHOD.TEXT]: {\n        url: string;\n        entityId: string;\n        certificate: string;\n    };\n}\n\nconst defaultMetadataState: MetadataState = {\n    [METADATA_METHOD.URL]: {\n        value: '',\n    },\n    [METADATA_METHOD.XML]: {\n        file: null,\n    },\n    [METADATA_METHOD.TEXT]: {\n        url: '',\n        entityId: '',\n        certificate: '',\n    },\n};\n\ninterface Props extends ModalProps, IdentityProviderEndpointsContentProps {\n    domain: Domain;\n    onClose: () => void;\n}\n\nconst ConfigureSamlModal = ({ domain, onClose, issuerID, callbackURL, ...rest }: Props) => {\n    const [step, setStep] = useState(STEP.IDP_VALUES);\n\n    const { createNotification } = useNotifications();\n\n    const api = useApi();\n    const { call } = useEventManager();\n    const [submitting, withSubmitting] = useLoading();\n    const { validator, onFormSubmit, reset } = useFormErrors();\n\n    const [metadataMethod, setMetadataMethod] = useState<METADATA_METHOD>(METADATA_METHOD.URL);\n    const [metadata, setMetadata] = useState<MetadataState>(defaultMetadataState);\n\n    useEffect(() => {\n        const stepLabel = (() => {\n            if (step === STEP.IDP_VALUES) {\n                return 'idpvalues';\n            }\n\n            return 'metadata';\n        })();\n        void metrics.core_sso_saml_setup_modal_load_total.increment({ step: stepLabel });\n    }, [step]);\n\n    const {\n        title,\n        content,\n        footer,\n        onSubmit,\n    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {\n        if (step === STEP.IDP_VALUES) {\n            return {\n                onSubmit: () => setStep(STEP.SAML_METADATA),\n                title: c('Title').t`Enter endpoints into your identity provider`,\n                content: <IdentityProviderEndpointsContent issuerID={issuerID} callbackURL={callbackURL} />,\n                footer: (\n                    <>\n                        <div />\n                        <Button type=\"submit\" color=\"norm\">\n                            {c('Action').t`Continue`}\n                        </Button>\n                    </>\n                ),\n            };\n        }\n\n        if (step === STEP.SAML_METADATA) {\n            const handleSubmit = async () => {\n                if (!onFormSubmit()) {\n                    return;\n                }\n\n                if (metadataMethod === METADATA_METHOD.URL) {\n                    try {\n                        await api(\n                            setupSAMLUrl({\n                                DomainID: domain.ID,\n                                MetadataURL: metadata[METADATA_METHOD.URL].value.trim(),\n                            })\n                        );\n\n                        metrics.core_sso_saml_setup_total.increment({\n                            status: 'success',\n                            method: 'url',\n                        });\n                    } catch (error) {\n                        observeApiError(error, (status) =>\n                            metrics.core_sso_saml_setup_total.increment({\n                                status,\n                                method: 'url',\n                            })\n                        );\n                        throw error;\n                    }\n                } else if (metadataMethod === METADATA_METHOD.XML) {\n                    try {\n                        const xmlFileAsString = (await metadata[METADATA_METHOD.XML].file?.text()) || '';\n\n                        await api(\n                            setupSAMLXml({\n                                DomainID: domain.ID,\n                                XML: btoa(xmlFileAsString),\n                            })\n                        );\n\n                        metrics.core_sso_saml_setup_total.increment({\n                            status: 'success',\n                            method: 'xml',\n                        });\n                    } catch (error) {\n                        observeApiError(error, (status) =>\n                            metrics.core_sso_saml_setup_total.increment({\n                                status,\n                                method: 'xml',\n                            })\n                        );\n                        throw error;\n                    }\n                } else if (metadataMethod === METADATA_METHOD.TEXT) {\n                    try {\n                        const { url, entityId, certificate } = metadata[METADATA_METHOD.TEXT];\n                        await api(\n                            setupSAMLFields({\n                                DomainID: domain.ID,\n                                SSOURL: url.trim(),\n                                SSOEntityID: entityId.trim(),\n                                Certificate: certificate,\n                            })\n                        );\n\n                        metrics.core_sso_saml_setup_total.increment({\n                            status: 'success',\n                            method: 'text',\n                        });\n                    } catch (error) {\n                        observeApiError(error, (status) =>\n                            metrics.core_sso_saml_setup_total.increment({\n                                status,\n                                method: 'text',\n                            })\n                        );\n                        throw error;\n                    }\n                }\n\n                await call();\n                onClose();\n            };\n\n            const handleFileUpload = async (files: File[]) => {\n                if (files.length === 0) {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Unable to upload file`,\n                    });\n                    return;\n                }\n\n                if (files.length > 1) {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Please upload only 1 file`,\n                    });\n                    return;\n                }\n\n                const file = files[0];\n\n                if (file.type !== 'text/xml') {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Please upload an xml file`,\n                    });\n                    return;\n                }\n\n                setMetadata((metadata) => ({\n                    ...metadata,\n                    [METADATA_METHOD.XML]: {\n                        file,\n                    },\n                }));\n            };\n\n            const selectFileButton = (\n                <label\n                    key=\"select-file-button\"\n                    className=\"link link-focus align-baseline text-left\"\n                    htmlFor=\"file-input\"\n                >\n                    <input\n                        id=\"file-input\"\n                        type=\"file\"\n                        accept=\".xml\"\n                        className=\"sr-only\"\n                        onChange={async (e) => {\n                            const files = Array.from(e.target.files as FileList);\n                            await handleFileUpload(files);\n                        }}\n                    />\n                    {c('Action').t`Select file`}\n                </label>\n            );\n\n            // Using a function here so that we can extend to other applications without requiring retranslation of this string\n            const getDescriptionString = (appName: typeof VPN_APP_NAME) => {\n                // translator: variable here is an application name. Example full sentence \"Go to your identity provider, get the SAML metadata for Proton VPN and import it here.\"\n                return c('Info')\n                    .t`Go to your identity provider, get the SAML metadata for ${appName} and import it here.`;\n            };\n\n            // Using a function here so that we can extend to other applications without requiring retranslation of this string\n            const getUrlLabelString = (appName: typeof VPN_APP_NAME) => {\n                // translator: variable here is an application name. Example full sentence \"Metadata URL for Proton VPN\"\n                return c('Label').t`Metadata URL for ${appName}`;\n            };\n\n            // Using a function here so that we can extend to other applications without requiring retranslation of this string\n            const getFileLabelString = (appName: typeof VPN_APP_NAME) => {\n                // translator: variable here is an application name. Example full sentence \"Metadata file for Proton VPN\"\n                return c('Label').t`Metadata file for ${appName}`;\n            };\n\n            return {\n                title: c('Title').t`Enter SAML metadata`,\n                onSubmit: () => withSubmitting(handleSubmit),\n                content: (\n                    <div>\n                        <div className=\"mb-4\">\n                            {getDescriptionString(VPN_APP_NAME)}\n                            <br />\n                            <Href href=\"https://protonvpn.com/support/sso\">{c('Link').t`Learn more`}</Href>\n                        </div>\n                        <div className=\"text-semibold mb-1\">{c('Label').t`Method for importing metadata`}</div>\n                        <RadioGroup\n                            className=\"mb-4\"\n                            name=\"metadata-method\"\n                            onChange={(v) => {\n                                reset();\n                                setMetadataMethod(v);\n                            }}\n                            value={metadataMethod}\n                            disableChange={submitting}\n                            options={[\n                                {\n                                    value: METADATA_METHOD.URL,\n                                    label: 'URL',\n                                },\n                                {\n                                    value: METADATA_METHOD.XML,\n                                    label: 'XML file',\n                                },\n                                {\n                                    value: METADATA_METHOD.TEXT,\n                                    label: 'Text fields',\n                                },\n                            ]}\n                        />\n                        <div className=\"min-h-custom\" style={{ '--min-h-custom': '12rem' }}>\n                            {metadataMethod === METADATA_METHOD.URL && (\n                                <>\n                                    <InputFieldTwo\n                                        autoFocus\n                                        label={getUrlLabelString(VPN_APP_NAME)}\n                                        placeholder={c('Placeholder')\n                                            .t`e.g. https://example.com/app/protonvpn/XXXXX/sso/metadata`}\n                                        value={metadata[METADATA_METHOD.URL].value}\n                                        onValue={(value: string) =>\n                                            setMetadata((metadata) => ({\n                                                ...metadata,\n                                                [METADATA_METHOD.URL]: {\n                                                    value,\n                                                },\n                                            }))\n                                        }\n                                        error={validator([requiredValidator(metadata[METADATA_METHOD.URL].value)])}\n                                    />\n                                </>\n                            )}\n                            {metadataMethod === METADATA_METHOD.XML && (\n                                <>\n                                    <div className=\"text-semibold mb-1\">{getFileLabelString(VPN_APP_NAME)}</div>\n                                    <Dropzone\n                                        onDrop={handleFileUpload}\n                                        shape=\"flashy\"\n                                        customContent={\n                                            <div className=\"w-full h-full flex flex-column items-center justify-center text-center\">\n                                                <img\n                                                    src={dragAndDrop}\n                                                    alt=\"\"\n                                                    aria-hidden=\"true\"\n                                                    className=\"mb-4 max-w-custom\"\n                                                    style={{ '--max-w-custom': '4rem' }}\n                                                />\n                                                <div>{c('Info').t`Drop file here to upload`}</div>\n                                            </div>\n                                        }\n                                    >\n                                        <div\n                                            className=\"rounded-xl border-dashed border-weak p-4 flex flex-column items-center justify-center min-h-custom\"\n                                            style={{ '--min-h-custom': '10.5rem' }}\n                                        >\n                                            {metadata[METADATA_METHOD.XML].file === null ? (\n                                                <div className=\"color-weak text-center\">\n                                                    <div>{c('Info').t`Drop file here to upload`}</div>\n                                                    <div>{c('Info').jt`or ${selectFileButton}`}</div>\n                                                </div>\n                                            ) : (\n                                                <UploadedXmlFile\n                                                    file={metadata[METADATA_METHOD.XML].file}\n                                                    onRemoveClick={() =>\n                                                        setMetadata((metadata) => ({\n                                                            ...metadata,\n                                                            [METADATA_METHOD.XML]: {\n                                                                file: null,\n                                                            },\n                                                        }))\n                                                    }\n                                                />\n                                            )}\n                                        </div>\n                                    </Dropzone>\n                                </>\n                            )}\n                            {metadataMethod === METADATA_METHOD.TEXT && (\n                                <div className=\"flex flex-col gap-4\">\n                                    <InputFieldTwo\n                                        autoFocus\n                                        label={c('Label').t`Single sign-on URL`}\n                                        placeholder={c('Placeholder').t`e.g. https://idp.example.com/sso/saml`}\n                                        value={metadata[METADATA_METHOD.TEXT].url}\n                                        onValue={(value: string) =>\n                                            setMetadata((metadata) => ({\n                                                ...metadata,\n                                                [METADATA_METHOD.TEXT]: {\n                                                    ...metadata[METADATA_METHOD.TEXT],\n                                                    url: value,\n                                                },\n                                            }))\n                                        }\n                                        error={validator([requiredValidator(metadata[METADATA_METHOD.TEXT].url)])}\n                                        assistiveText={c('Info')\n                                            .t`Endpoint URL received from your identity provider (e.g. https://idp.example.com/sso/saml).`}\n                                    />\n                                    <InputFieldTwo\n                                        label={c('Label').t`Single sign-on entity ID`}\n                                        placeholder={c('Placeholder').t`e.g. https://idp.example.com/XXXXX`}\n                                        value={metadata[METADATA_METHOD.TEXT].entityId}\n                                        onValue={(value: string) =>\n                                            setMetadata((metadata) => ({\n                                                ...metadata,\n                                                [METADATA_METHOD.TEXT]: {\n                                                    ...metadata[METADATA_METHOD.TEXT],\n                                                    entityId: value,\n                                                },\n                                            }))\n                                        }\n                                        error={validator([requiredValidator(metadata[METADATA_METHOD.TEXT].entityId)])}\n                                        assistiveText={c('Info')\n                                            .t`Unique ID generated by your identity provider, usually in the form of a URL that contains the identity provider’s name within it (e.g. https://idp.example.com/XXXXX).`}\n                                    />\n                                    <InputFieldTwo\n                                        as={TextArea}\n                                        label={c('Label').t`Public certificate (X.509)`}\n                                        value={metadata[METADATA_METHOD.TEXT].certificate}\n                                        onValue={(value: string) =>\n                                            setMetadata((metadata) => ({\n                                                ...metadata,\n                                                [METADATA_METHOD.TEXT]: {\n                                                    ...metadata[METADATA_METHOD.TEXT],\n                                                    certificate: value,\n                                                },\n                                            }))\n                                        }\n                                        error={validator([\n                                            requiredValidator(metadata[METADATA_METHOD.TEXT].certificate),\n                                        ])}\n                                        assistiveText={c('Info')\n                                            .t`Identity provider’s public key to sign authentication assertions. There should be a place to download or copy the certificate hash from the identity provider. Just paste the certificate hash in the text area field.`}\n                                    />\n                                </div>\n                            )}\n                        </div>\n                    </div>\n                ),\n                footer: (\n                    <>\n                        <Button onClick={() => setStep(STEP.IDP_VALUES)}>{c('Action').t`Back`}</Button>\n                        <Button type=\"submit\" loading={submitting} color=\"norm\">\n                            {c('Action').t`Done`}\n                        </Button>\n                    </>\n                ),\n            };\n        }\n\n        throw new Error('No step found');\n    })();\n\n    return (\n        <Modal as={Form} onSubmit={onSubmit} size=\"large\" onClose={onClose} {...rest}>\n            <ModalHeader title={title} />\n            <ModalContent>{content}</ModalContent>\n            <ModalFooter>{footer}</ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ConfigureSamlModal;\n","import { c } from 'ttag';\n\nimport { Href } from '@proton/atoms/Href';\nimport { Domain } from '@proton/shared/lib/interfaces';\n\nimport ReadonlyFieldWithCopy from './ReadonlyFieldWithCopy';\n\ninterface ReadOnlyInputFieldProps {\n    label: string;\n    value: string;\n}\n\nconst ReadOnlyInputField: React.FC<ReadOnlyInputFieldProps> = ({ label, value }: ReadOnlyInputFieldProps) => {\n    return (\n        <ReadonlyFieldWithCopy\n            label={label}\n            value={value}\n            assistContainerClassName=\"hidden\"\n            rootClassName=\"flex items-center flex-nowrap gap-2\"\n            labelContainerClassName=\"w-1/6 m-0\"\n        />\n    );\n};\n\ninterface Props {\n    domain: Domain;\n    includeTimeInformation?: boolean;\n}\n\nconst TXTSection = ({ domain, includeTimeInformation }: Props) => {\n    const boldDomainName = <b key={domain.ID}>{domain.DomainName}</b>;\n\n    return (\n        <div>\n            <div>\n                {c('Info')\n                    .jt`To allow the domain ${boldDomainName} to use SAML SSO, you must verify ownership of it by adding the following DNS TXT record to your domain in your DNS provider.`}\n            </div>\n            <Href href=\"https://protonvpn.com/support/sso\">{c('Link').t`Learn more`}</Href>\n\n            <h3 className=\"text-semibold text-rg mt-4 mb-1\">{c('Info').t`DNS TXT record`}</h3>\n            <div className=\"rounded border border-weak flex flex-column gap-2 p-4\">\n                <ReadOnlyInputField label={c('Label').t`Type`} value=\"TXT\" />\n                <ReadOnlyInputField label={c('Label').t`Name`} value=\"@\" />\n                <ReadOnlyInputField label={c('Label').t`Value`} value={domain.VerifyCode} />\n            </div>\n            <p className=\"color-weak text-sm mt-1\">\n                {c('Hint').t`Add this record to your domain in the control panel of your domain name registrar`}\n            </p>\n            {includeTimeInformation && (\n                <div>{c('Info')\n                    .t`This verification can take up to one hour. You can safely continue to the next steps.`}</div>\n            )}\n        </div>\n    );\n};\n\nexport default TXTSection;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { Domain } from '@proton/shared/lib/interfaces';\n\nimport {\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n} from '../../../components';\nimport TXTSection from './TXTSection';\n\ninterface Props extends ModalProps {\n    domain: Domain;\n}\n\nconst TXTRecordModal = ({ domain, ...rest }: Props) => {\n    return (\n        <Modal size=\"large\" {...rest}>\n            <ModalHeader title={c('Info').t`Verify domain`} />\n            <ModalContent>\n                <TXTSection domain={domain} includeTimeInformation />\n            </ModalContent>\n            <ModalFooter className=\"justify-end\">\n                <Button color=\"norm\" onClick={rest.onClose}>{c('Action').t`Done`}</Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default TXTRecordModal;\n","import { c } from 'ttag';\n\nimport { InlineLinkButton } from '@proton/atoms';\nimport { Icon, IconName, useModalState } from '@proton/components/components';\nimport { DOMAIN_STATE, Domain } from '@proton/shared/lib/interfaces';\nimport clsx from '@proton/utils/clsx';\n\nimport TXTRecordModal from './TXTRecordModal';\n\ninterface Props {\n    domain: Domain;\n}\n\nconst { DOMAIN_STATE_DEFAULT, DOMAIN_STATE_VERIFIED, DOMAIN_STATE_WARN } = DOMAIN_STATE;\n\nconst DomainVerificationState = ({ domain }: Props) => {\n    const [txtRecordModalProps, setTXTRecordModalOpen, renderTXTRecordModal] = useModalState();\n\n    const showTXT = () => {\n        setTXTRecordModalOpen(true);\n    };\n\n    const domainStateMap: { [key in DOMAIN_STATE]: { text: string; className: string; iconName: IconName } } = {\n        [DOMAIN_STATE_DEFAULT]: {\n            text: c('Info').t`Domain ownership not verified.`,\n            className: 'color-warning',\n            iconName: 'cross-circle-filled',\n        },\n        [DOMAIN_STATE_VERIFIED]: {\n            text: c('Info').t`Domain ownership verified.`,\n            className: 'color-success',\n            iconName: 'checkmark-circle-filled',\n        },\n        [DOMAIN_STATE_WARN]: {\n            text: c('Info').t`Domain ownership failed verification.`,\n            className: 'color-error',\n            iconName: 'cross-circle-filled',\n        },\n    };\n\n    const domainStateProperties = domainStateMap[domain.State];\n\n    if (!domainStateProperties) {\n        return null;\n    }\n\n    const { text, className, iconName } = domainStateProperties;\n\n    return (\n        <>\n            {renderTXTRecordModal && <TXTRecordModal domain={domain} {...txtRecordModalProps} />}\n\n            <div className=\"flex gap-1 flex-nowrap\">\n                <Icon className={clsx('shrink-0', className)} type=\"warning\" name={iconName} />\n                <span>\n                    {text}{' '}\n                    <InlineLinkButton className=\"color-inherit\" onClick={() => showTXT()}>\n                        {c('Action').t`See DNS TXT record`}\n                    </InlineLinkButton>\n                </span>\n            </div>\n        </>\n    );\n};\n\nexport default DomainVerificationState;\n","import { useEffect } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport metrics, { observeApiError } from '@proton/metrics';\nimport { deleteDomain } from '@proton/shared/lib/api/domains';\nimport { Domain } from '@proton/shared/lib/interfaces';\n\nimport { Prompt, PromptProps } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\n\ninterface Props extends Omit<PromptProps, 'title' | 'buttons' | 'children'> {\n    domain: Domain;\n}\n\nconst RemoveSSODomain = ({ domain, ...rest }: Props) => {\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n\n    useEffect(() => {\n        void metrics.core_sso_remove_domain_modal_load_total.increment({ step: 'remove-domain' });\n    }, []);\n\n    const handleConfirmDelete = async () => {\n        try {\n            await api(deleteDomain(domain.ID));\n            await call();\n            rest.onClose?.();\n            createNotification({ text: c('Success message').t`Domain deleted` });\n\n            metrics.core_sso_remove_domain_total.increment({\n                status: 'success',\n            });\n        } catch (error) {\n            observeApiError(error, (status) =>\n                metrics.core_sso_remove_domain_total.increment({\n                    status,\n                })\n            );\n            throw error;\n        }\n    };\n\n    const boldDomain = <b key=\"remove-sso-domain-name\">{domain.DomainName}</b>;\n\n    return (\n        <Prompt\n            title={c('Title').t`Remove domain`}\n            buttons={[\n                <Button\n                    color=\"danger\"\n                    onClick={() => {\n                        void withLoading(handleConfirmDelete());\n                    }}\n                    loading={loading}\n                >{c('Action').t`Remove`}</Button>,\n                <Button onClick={rest.onClose} disabled={loading}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            {...rest}\n        >\n            <div>{c('Info').jt`Are you sure you want to remove the domain ${boldDomain}?`}</div>\n        </Prompt>\n    );\n};\n\nexport default RemoveSSODomain;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport {\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    useApi,\n    useEventManager,\n    useNotifications,\n} from '@proton/components';\nimport useLoading from '@proton/hooks/useLoading';\nimport { removeSAMLConfig } from '@proton/shared/lib/api/samlSSO';\nimport { SSO } from '@proton/shared/lib/interfaces';\nimport errorImg from '@proton/styles/assets/img/errors/error-generic-triangle.svg';\n\ninterface Props extends ModalProps {\n    sso: SSO;\n}\n\nconst RemoveSSOModal = ({ sso, onClose, ...rest }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n\n    const removeSSO = async () => {\n        await api(removeSAMLConfig(sso.ID));\n        await call();\n\n        createNotification({\n            text:\n                // translator: refers to removing the SSO configuration\n                c('Info').t`Single sign-on removed`,\n        });\n\n        onClose?.();\n    };\n\n    const boldSSOUserInformation = (\n        <b key=\"bold-sso-information\">\n            {\n                // translator: full sentence 'SSO users (provided by your Identity Provider) will be deleted and you will have to create them manually to add them back to your organization.'\n                c('Info').t`SSO users (provided by your Identity Provider) will be deleted`\n            }\n        </b>\n    );\n\n    return (\n        <ModalTwo onClose={onClose} size=\"small\" {...rest}>\n            <ModalTwoHeader title={c('Title').t`Remove single sign-on for your organization?`} />\n            <ModalTwoContent>\n                <div className=\"text-center my-8\">\n                    <img className=\"m-auto w-custom\" style={{ '--w-custom': '6rem' }} src={errorImg} alt=\"\" />\n                </div>\n                <p className=\"m-0 text-bold\">{c('Info')\n                    .t`The credentials from your Identity Provider will be deleted.`}</p>\n                <p className=\"my-4\">{c('Info').t`Once single sign-on is disabled for your organization:`}</p>\n                <ul className=\"mt-0\">\n                    <li>\n                        {\n                            // translator: full sentence 'SSO users (provided by your Identity Provider) will be deleted and you will have to create them manually to add them back to your organization.'\n                            c('Info')\n                                .jt`${boldSSOUserInformation} and you will have to create them manually to add them back to your organization`\n                        }\n                    </li>\n                    <li>\n                        {c('Info')\n                            .t`Non-SSO users (created manually, not provided by your Identity Provider) can still log in to your organization`}\n                    </li>\n                </ul>\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button color=\"danger\" onClick={() => withLoading(removeSSO)} loading={loading}>\n                    {c('Action').t`Remove single sign-on`}\n                </Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default RemoveSSOModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms/Button';\nimport { Domain, SSO } from '@proton/shared/lib/interfaces';\n\nimport { useModalState } from '../../../components';\nimport { SettingsParagraph, SettingsSection } from '../../account';\nimport RemoveSSOModal from './RemoveSSOModal';\n\ninterface Props {\n    domain: Domain;\n    ssoConfig: SSO;\n}\n\nconst RemoveSSOSection = ({ domain, ssoConfig }: Props) => {\n    const [removeSSOModalProps, setRemoveSSOModalOpen, renderRemoveSSOModal] = useModalState();\n\n    const removeSSO = () => {\n        setRemoveSSOModalOpen(true);\n    };\n\n    const boldDomainName = <b key={domain.ID}>{domain.DomainName}</b>;\n\n    return (\n        <>\n            {renderRemoveSSOModal && <RemoveSSOModal sso={ssoConfig} {...removeSSOModalProps} />}\n            <SettingsSection>\n                <SettingsParagraph learnMoreUrl=\"https://protonvpn.com/support/sso\">\n                    {c('Info').jt`This will remove SSO for ${boldDomainName}.`}\n                </SettingsParagraph>\n\n                <Button color=\"danger\" onClick={removeSSO}>\n                    {c('Action').t`Stop using single sign-on`}\n                </Button>\n            </SettingsSection>\n        </>\n    );\n};\n\nexport default RemoveSSOSection;\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms/Button';\nimport useLoading from '@proton/hooks/useLoading';\nimport metrics, { observeApiError } from '@proton/metrics';\nimport { updateSAMLConfig } from '@proton/shared/lib/api/samlSSO';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Domain, SSO } from '@proton/shared/lib/interfaces';\n\nimport { Info, InputFieldTwo, TextAreaTwo, useFormErrors } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\nimport { SettingsLayout, SettingsLayoutLeft, SettingsLayoutRight } from '../../account';\nimport { IdentityProviderEndpointsContentProps } from './IdentityProviderEndpointsContent';\nimport ReadonlyFieldWithCopy from './ReadonlyFieldWithCopy';\n\ninterface SSOInfo {\n    url: string;\n    entity: string;\n    certificate: string;\n}\n\ninterface Props extends IdentityProviderEndpointsContentProps {\n    domain: Domain;\n    sso: SSO;\n    onImportSamlClick: () => void;\n}\n\nconst SSOInfoForm = ({ domain, sso, issuerID, callbackURL, onImportSamlClick }: Props) => {\n    const { onFormSubmit, validator } = useFormErrors();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const api = useApi();\n\n    const ssoInfo: SSOInfo = {\n        url: sso.SSOURL,\n        entity: sso.SSOEntityID,\n        certificate: sso.Certificate,\n    };\n\n    const [ssoDiff, setSsoDiff] = useState<Partial<SSOInfo>>({});\n    const isFormDirty = Object.keys(ssoDiff).length;\n\n    const [submitting, withSubmitting] = useLoading();\n\n    const onChange = (key: keyof SSOInfo) => (value: string) => {\n        setSsoDiff((diff) => {\n            if (value === ssoInfo[key]) {\n                delete diff[key];\n                return { ...diff };\n            }\n            return {\n                ...diff,\n                [key]: value,\n            };\n        });\n    };\n\n    const url = ssoDiff.url ?? ssoInfo.url;\n    const entity = ssoDiff.entity ?? ssoInfo.entity;\n    const certificate = ssoDiff.certificate ?? ssoInfo.certificate;\n\n    useEffect(() => {\n        void metrics.core_sso_saml_info_page_load_total.increment({});\n    }, []);\n\n    const handleSubmit = async () => {\n        if (!onFormSubmit()) {\n            return;\n        }\n\n        try {\n            await api(\n                updateSAMLConfig(sso.ID, {\n                    DomainID: domain.ID,\n                    SSOURL: url,\n                    SSOEntityID: entity,\n                    Certificate: certificate,\n                })\n            );\n\n            await call();\n            setSsoDiff({});\n\n            createNotification({ text: c('Info').t`SAML configuration saved` });\n\n            metrics.core_sso_saml_update_info_total.increment({ status: 'success' });\n        } catch (error) {\n            observeApiError(error, (status) => {\n                metrics.core_sso_saml_update_info_total.increment({ status });\n            });\n        }\n    };\n\n    return (\n        <form\n            onSubmit={(e) => {\n                e.preventDefault();\n                void withSubmitting(handleSubmit());\n            }}\n        >\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"ssoUrl\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Single sign-on URL`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Endpoint URL from identity provider (e.g. https://idp.example.com/sso/saml)`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <InputFieldTwo\n                        id=\"ssoUrl\"\n                        value={url}\n                        onValue={onChange('url')}\n                        error={validator([requiredValidator(url)])}\n                        disableChange={submitting}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"ssoEntity\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Single sign-on entity ID`}</span>\n                        <Info\n                            title={c('Tooltip').t`Usually an URL that contains the identity provider's name within`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <InputFieldTwo\n                        id=\"ssoEntity\"\n                        value={entity}\n                        onValue={onChange('entity')}\n                        error={validator([requiredValidator(entity)])}\n                        disableChange={submitting}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"ssoCertificate\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Public certificate (X.509)`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Identity provider’s public key to sign authentication assertions. Get the certificate hash from your identity provider.`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <InputFieldTwo\n                        id=\"ssoCertificate\"\n                        as={TextAreaTwo}\n                        rows={12}\n                        value={certificate}\n                        onValue={onChange('certificate')}\n                        error={validator([requiredValidator(certificate)])}\n                        disableChange={submitting}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"acsUrl\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Reply (ACS) URL`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Copy and paste this URL into the ACS (Assertion Consumer Service) URL field of your identity provider`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <ReadonlyFieldWithCopy id=\"acsUrl\" value={callbackURL} />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"acsUrl\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Issuer ID`}</span>\n                        <Info\n                            title={c('Tooltip')\n                                .t`Copy and paste this URL into the entity ID field of your identity provider`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full\">\n                    <ReadonlyFieldWithCopy id=\"acsUrl\" value={issuerID} />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <div className=\"flex gap-4\">\n                <Button onClick={onImportSamlClick}>{c('Action').t`Import new SAML metadata`}</Button>\n                <Button color=\"norm\" disabled={!isFormDirty} loading={submitting} type=\"submit\">\n                    {c('Action').t`Save SAML configuration`}\n                </Button>\n            </div>\n        </form>\n    );\n};\n\nexport default SSOInfoForm;\n","import { ReactNode, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useApi, useEventManager } from '@proton/components/hooks';\nimport useLoading from '@proton/hooks/useLoading';\nimport metrics, { observeApiError } from '@proton/metrics/index';\nimport { addDomain } from '@proton/shared/lib/api/domains';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Domain } from '@proton/shared/lib/interfaces';\n\nimport {\n    Form,\n    Icon,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../../components';\nimport TXTSection from './TXTSection';\n\nenum STEP {\n    DOMAIN_INPUT,\n    TXT_RECORD,\n}\n\ninterface Props extends ModalProps {\n    onContinue: () => void;\n}\n\nconst SetupSSODomainModal = ({ onContinue, onClose, ...rest }: Props) => {\n    const [step, setStep] = useState(STEP.DOMAIN_INPUT);\n    const [domainName, setDomainName] = useState('');\n    const [domain, setDomain] = useState<Domain>();\n\n    useEffect(() => {\n        const stepLabel = (() => {\n            if (step === STEP.TXT_RECORD) {\n                return 'txt-record';\n            }\n\n            return 'domain-input';\n        })();\n\n        void metrics.core_sso_setup_domain_modal_load_total.increment({ step: stepLabel });\n    }, [step]);\n\n    const api = useApi();\n    const { call } = useEventManager();\n    const [submitting, withSubmitting] = useLoading();\n    const { validator, onFormSubmit } = useFormErrors();\n\n    const {\n        title,\n        content,\n        footer,\n        onSubmit,\n    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {\n        if (step === STEP.DOMAIN_INPUT) {\n            const handleSubmit = async () => {\n                if (!onFormSubmit()) {\n                    return;\n                }\n\n                try {\n                    const { Domain } = await api<{ Domain: Domain }>(\n                        addDomain({ Name: domainName, AllowedForMail: false, AllowedForSSO: true })\n                    );\n                    setDomain(Domain);\n\n                    await call();\n                    setStep(STEP.TXT_RECORD);\n                } catch (error) {\n                    observeApiError(error, (status) =>\n                        metrics.core_sso_setup_domain_total.increment({\n                            status,\n                        })\n                    );\n\n                    throw error;\n                }\n            };\n            return {\n                title: c('Info').t`Add domain`,\n                onSubmit: () => withSubmitting(handleSubmit),\n                content: (\n                    <>\n                        <div className=\"mb-6\">\n                            {c('Info').t`Specify the domain which is allowed to authenticate with SAML SSO.`}\n                        </div>\n                        <InputFieldTwo\n                            id=\"domain\"\n                            prefix={<Icon name=\"globe\" />}\n                            label={c('Label').t`Allowed domain`}\n                            placeholder={c('Label').t`e.g. example.com`}\n                            error={validator([requiredValidator(domainName)])}\n                            autoFocus\n                            disableChange={submitting}\n                            value={domainName}\n                            onValue={setDomainName}\n                        />\n                    </>\n                ),\n                footer: (\n                    <>\n                        <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                        <Button type=\"submit\" loading={submitting} color=\"norm\">\n                            {c('Action').t`Add domain`}\n                        </Button>\n                    </>\n                ),\n            };\n        }\n\n        if (step === STEP.TXT_RECORD && domain) {\n            return {\n                title: c('Info').t`Verify domain`,\n                content: <TXTSection domain={domain} />,\n                footer: (\n                    <>\n                        <Button onClick={onClose}>{c('Action').t`Close`}</Button>\n                        <Button onClick={onContinue} color=\"norm\">\n                            {c('Action').t`Continue`}\n                        </Button>\n                    </>\n                ),\n            };\n        }\n\n        throw new Error('No step found');\n    })();\n\n    return (\n        <Modal as={onSubmit ? Form : undefined} onSubmit={onSubmit} size=\"large\" onClose={onClose} {...rest}>\n            <ModalHeader title={title} />\n            <ModalContent>{content}</ModalContent>\n            <ModalFooter>{footer}</ModalFooter>\n        </Modal>\n    );\n};\n\nexport default SetupSSODomainModal;\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms/Button';\nimport { getSAMLStaticInfo } from '@proton/shared/lib/api/samlSSO';\nimport { Domain, SSO } from '@proton/shared/lib/interfaces';\n\nimport { SubSettingsSection } from '../..';\nimport { Info, InputFieldTwo, Loader, ModalStateProps, useModalState } from '../../../components';\nimport { useApi, useCustomDomains, useSamlSSO } from '../../../hooks';\nimport {\n    SettingsLayout,\n    SettingsLayoutLeft,\n    SettingsLayoutRight,\n    SettingsParagraph,\n    SettingsSectionWide,\n} from '../../account';\nimport ConfigureSamlModal from './ConfigureSamlModal';\nimport DomainVerificationState from './DomainVerificationState';\nimport { IdentityProviderEndpointsContentProps } from './IdentityProviderEndpointsContent';\nimport RemoveSSODomain from './RemoveSSODomain';\nimport RemoveSSOSection from './RemoveSSOSection';\nimport SSOInfoForm from './SSOInfoForm';\nimport SetupSSODomainModal from './SetupSSODomainModal';\n\nconst getSsoConfigForDomain = (ssoConfigs: SSO[], domain: Domain) => {\n    return ssoConfigs.find(({ DomainID }) => DomainID === domain.ID);\n};\n\nconst ConfigureSamlContent = ({\n    domain,\n    ssoConfigs,\n    configureSamlModalProps,\n    setConfigureSamlModalOpen,\n    renderConfigureSamlModal,\n    identityProviderEndpointsContentProps,\n}: {\n    domain: Domain;\n    ssoConfigs: SSO[];\n    configureSamlModalProps: ModalStateProps;\n    setConfigureSamlModalOpen: (newValue: boolean) => void;\n    renderConfigureSamlModal: boolean | undefined;\n    identityProviderEndpointsContentProps: IdentityProviderEndpointsContentProps;\n}) => {\n    const [removeSSODomainProps, setRemoveSSODomainOpen, renderRemoveSSODomain] = useModalState();\n\n    const ssoConfigForDomain = getSsoConfigForDomain(ssoConfigs, domain);\n\n    return (\n        <>\n            {renderConfigureSamlModal && (\n                <ConfigureSamlModal\n                    domain={domain}\n                    {...configureSamlModalProps}\n                    {...identityProviderEndpointsContentProps}\n                />\n            )}\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"domainName\" className=\"text-semibold flex items-center gap-2\">\n                        <span>{c('Label').t`Allowed Domain`}</span>\n                        <Info\n                            title={c('Tooltip').t`Specify the domain which is allowed to authenticate with SAML SSO`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"w-full max-w-custom\" style={{ '--max-w-custom': '25rem' }}>\n                    <InputFieldTwo\n                        id=\"domainName\"\n                        value={domain.DomainName}\n                        readOnly\n                        assistiveText={<DomainVerificationState domain={domain} />}\n                    />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n            {ssoConfigForDomain ? (\n                <SSOInfoForm\n                    domain={domain}\n                    sso={ssoConfigForDomain}\n                    onImportSamlClick={() => setConfigureSamlModalOpen(true)}\n                    {...identityProviderEndpointsContentProps}\n                />\n            ) : (\n                <div className=\"flex gap-4\">\n                    <Button\n                        color=\"norm\"\n                        onClick={() => {\n                            setConfigureSamlModalOpen(true);\n                        }}\n                    >\n                        {c('Action').t`Configure SAML`}\n                    </Button>\n\n                    {renderRemoveSSODomain && <RemoveSSODomain domain={domain} {...removeSSODomainProps} />}\n                    <Button\n                        color=\"danger\"\n                        shape=\"outline\"\n                        onClick={() => {\n                            setRemoveSSODomainOpen(true);\n                        }}\n                    >\n                        {c('Action').t`Remove domain`}\n                    </Button>\n                </div>\n            )}\n        </>\n    );\n};\n\nconst RemoveSSOSettingsSection = ({ domain, ssoConfigs }: { domain: Domain; ssoConfigs: SSO[] }) => {\n    const ssoConfigForDomain = getSsoConfigForDomain(ssoConfigs, domain);\n\n    if (!ssoConfigForDomain) {\n        return null;\n    }\n\n    return (\n        <SubSettingsSection\n            id=\"remove-sso\"\n            title={c('Title').t`Remove single sign-on`}\n            className=\"container-section-sticky-section\"\n        >\n            <SettingsSectionWide>\n                <RemoveSSOSection domain={domain} ssoConfig={ssoConfigForDomain} />\n            </SettingsSectionWide>\n        </SubSettingsSection>\n    );\n};\n\nconst SsoPage = () => {\n    const [customDomains] = useCustomDomains();\n    const [ssoConfigs] = useSamlSSO();\n    const api = useApi();\n\n    const [setupSSODomainModalProps, setSetupSSODomainModalOpen, renderSetupSSODomainModal] = useModalState();\n    const [configureSamlModalProps, setConfigureSamlModalOpen, renderConfigureSamlModal] = useModalState();\n    const [samlStaticInfo, setSamlStaticInfo] = useState<IdentityProviderEndpointsContentProps>();\n\n    useEffect(() => {\n        const fetchData = async () => {\n            const response = await api<{ EntityID: string; CallbackURL: string }>(getSAMLStaticInfo());\n            setSamlStaticInfo({\n                issuerID: response.EntityID,\n                callbackURL: response.CallbackURL,\n            });\n        };\n\n        void fetchData();\n    }, []);\n\n    if (!customDomains || !ssoConfigs || !samlStaticInfo) {\n        return <Loader />;\n    }\n\n    return (\n        <>\n            {renderSetupSSODomainModal && (\n                <SetupSSODomainModal\n                    onContinue={() => {\n                        setupSSODomainModalProps.onClose();\n                        setConfigureSamlModalOpen(true);\n                    }}\n                    {...setupSSODomainModalProps}\n                />\n            )}\n\n            <SubSettingsSection\n                id=\"saml-authentication\"\n                title={c('Title').t`SAML authentication`}\n                beta\n                className=\"container-section-sticky-section\"\n            >\n                <SettingsSectionWide>\n                    <SettingsParagraph learnMoreUrl=\"https://protonvpn.com/support/sso\">\n                        {c('Info')\n                            .t`Configure SAML authentication for your organization through an identity provider (IdP). This will enable SAML for the whole organization.`}\n                    </SettingsParagraph>\n\n                    {customDomains.length > 0 ? (\n                        <ConfigureSamlContent\n                            domain={customDomains[0]}\n                            ssoConfigs={ssoConfigs}\n                            configureSamlModalProps={configureSamlModalProps}\n                            setConfigureSamlModalOpen={setConfigureSamlModalOpen}\n                            renderConfigureSamlModal={renderConfigureSamlModal}\n                            identityProviderEndpointsContentProps={samlStaticInfo}\n                        />\n                    ) : (\n                        <Button\n                            color=\"norm\"\n                            onClick={() => {\n                                setSetupSSODomainModalOpen(true);\n                            }}\n                        >\n                            {c('Action').t`Configure SAML`}\n                        </Button>\n                    )}\n                </SettingsSectionWide>\n            </SubSettingsSection>\n\n            {customDomains.length > 0 && <RemoveSSOSettingsSection domain={customDomains[0]} ssoConfigs={ssoConfigs} />}\n        </>\n    );\n};\n\nexport default SsoPage;\n","import { encodeBase64URL, uint8ArrayToString } from '@proton/shared/lib/helpers/encoding';\nimport { RegisteredKey } from '@proton/shared/lib/webauthn/interface';\n\nexport const getId = (registeredKey: RegisteredKey) => {\n    return encodeBase64URL(uint8ArrayToString(new Uint8Array(registeredKey.CredentialID)));\n};\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { CircleLoader } from '@proton/atoms';\nimport physicalKey from '@proton/styles/assets/img/illustrations/physical-key.svg';\n\nimport Banner, { BannerBackgroundColor } from '../../../components/banner/Banner';\n\ninterface Props {\n    loading?: boolean;\n    error?: boolean;\n    checkbox: ReactNode;\n}\n\nconst RegisterSecurityKeyContent = ({ loading, error, checkbox }: Props) => {\n    return (\n        <>\n            <div className=\"flex justify-center mt-4 mb-6 relative\">\n                {loading && (\n                    <div className=\"text-center absolute inset-center\">\n                        <CircleLoader className=\"color-primary\" />\n                    </div>\n                )}\n                <img\n                    className={loading ? 'visibility-hidden' : undefined}\n                    src={physicalKey}\n                    alt={c('fido2: Info').t`Security key`}\n                />\n            </div>\n            <div>{c('fido2: Info').t`Insert your security key into your device's USB port.`}</div>\n            {checkbox && <div className=\"mt-2\">{checkbox}</div>}\n            {error && (\n                <div className=\"mt-4\">\n                    <Banner icon=\"exclamation-circle\" backgroundColor={BannerBackgroundColor.WEAK}>\n                        {c('fido2: Error').t`Something went wrong registering your security key. Please try again.`}\n                    </Banner>\n                </div>\n            )}\n        </>\n    );\n};\n\nexport default RegisterSecurityKeyContent;\n","import { arrayToBinaryString, encodeBase64 } from '@proton/crypto/lib/utils';\n\nimport {\n    PublicKeyCredentialCreationOptionsSerialized,\n    RegisterCredentials,\n    RegisterCredentialsPayload,\n} from './interface';\n\nexport * from './interface';\n\nconst convertCreationToExpectedFormat = (\n    publicKey: PublicKeyCredentialCreationOptionsSerialized\n): CredentialCreationOptions => {\n    const { challenge, user, excludeCredentials, ...rest } = publicKey;\n\n    return {\n        publicKey: {\n            ...rest,\n            challenge: new Uint8Array(challenge).buffer,\n            user: {\n                ...user,\n                id: new Uint8Array(user.id),\n            },\n            excludeCredentials: excludeCredentials?.map((credentials) => ({\n                ...credentials,\n                id: new Uint8Array(credentials.id),\n            })),\n        },\n    };\n};\n\nexport const getCreatePayload = async (\n    registerCredentials: RegisterCredentials\n): Promise<RegisterCredentialsPayload> => {\n    const credentialCreationOptions = convertCreationToExpectedFormat(\n        registerCredentials.RegistrationOptions.publicKey\n    );\n    const credentials = await navigator.credentials.create(credentialCreationOptions);\n    const publicKeyCredentials = credentials as PublicKeyCredential;\n    if (!credentials || !('rawId' in credentials) || !('attestationObject' in publicKeyCredentials.response)) {\n        throw new Error('No credentials received');\n    }\n    const response = publicKeyCredentials.response as AuthenticatorAttestationResponse & {\n        getTransports: () => string[];\n    };\n    return {\n        RegistrationOptions: registerCredentials.RegistrationOptions,\n        ClientData: response.clientDataJSON\n            ? encodeBase64(arrayToBinaryString(new Uint8Array(response.clientDataJSON)))\n            : null!,\n        AttestationObject: response.attestationObject\n            ? encodeBase64(arrayToBinaryString(new Uint8Array(response.attestationObject)))\n            : null!,\n        Transports: response.getTransports?.() || [],\n        Name: '',\n    };\n};\n","import { FormEvent, useRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport RegisterSecurityKeyContent from '@proton/components/containers/account/fido/RegisterSecurityKeyContent';\nimport { useLoading } from '@proton/hooks';\nimport { getSecurityKeyChallenge, registerSecurityKey } from '@proton/shared/lib/api/settings';\nimport { lockSensitiveSettings, unlockPasswordChanges } from '@proton/shared/lib/api/user';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { captureMessage } from '@proton/shared/lib/helpers/sentry';\nimport { RegisterCredentialsPayload, getCreatePayload } from '@proton/shared/lib/webauthn/create';\nimport { RegisterCredentials } from '@proton/shared/lib/webauthn/interface';\nimport physicalKeyRegistered from '@proton/styles/assets/img/illustrations/physical-key-registered.svg';\n\nimport {\n    Checkbox,\n    Form,\n    Info,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../../components';\nimport { useApi, useErrorHandler, useEventManager } from '../../../hooks';\nimport AuthModal from '../../password/AuthModal';\nimport { maxSecurityKeyNameLength } from './constants';\n\nenum Steps {\n    Tutorial,\n    Name,\n    Ok,\n}\n\nconst RegisteredContent = () => {\n    return (\n        <>\n            <div className=\"flex justify-center mt-4 mb-6 relative\">\n                <img src={physicalKeyRegistered} alt={c('fido2: Info').t`Security key`} />\n            </div>\n            <div className=\"text-center\">{c('fido2: Info').t`Your two-factor authentication key is ready to use.`}</div>\n        </>\n    );\n};\n\nconst AddSecurityKeyModal = ({ onClose, ...rest }: ModalProps) => {\n    const [step, setStep] = useState(Steps.Tutorial);\n    const [behind, setBehind] = useState(false);\n    const [loading, withLoading] = useLoading();\n    const normalApi = useApi();\n    const errorHandler = useErrorHandler();\n    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });\n    const { call } = useEventManager();\n    const { validator, onFormSubmit, reset } = useFormErrors();\n    const [name, setName] = useState('');\n    const [fidoError, setFidoError] = useState(false);\n    const registrationPayloadRef = useRef<RegisterCredentialsPayload>();\n    const [allowPlatformKeys, setAllowPlatformKeys] = useState(false);\n\n    const getRegistrationPayload = () => {\n        const run = async () => {\n            let response: RegisterCredentials;\n            try {\n                response = await silentApi<RegisterCredentials>(getSecurityKeyChallenge(!allowPlatformKeys));\n            } catch (e) {\n                errorHandler(e);\n                return;\n            }\n            try {\n                setFidoError(false);\n                setBehind(true);\n                registrationPayloadRef.current = await getCreatePayload(response);\n                setBehind(false);\n            } catch (error) {\n                setFidoError(true);\n                setBehind(false);\n                captureMessage('Security key registration', {\n                    level: 'error',\n                    extra: { error },\n                });\n                // Purposefully logging the error for somewhat easier debugging\n                console.error(error);\n                return;\n            }\n            reset();\n            setStep(Steps.Name);\n        };\n        void withLoading(run());\n    };\n\n    const handleRegister = () => {\n        const payload = registrationPayloadRef.current;\n        if (!payload) {\n            throw new Error('Missing payload ref');\n        }\n        const run = async () => {\n            try {\n                await silentApi(registerSecurityKey({ ...payload, Name: name }));\n                await silentApi(lockSensitiveSettings());\n                await call();\n            } catch (e) {\n                errorHandler(e);\n                return;\n            }\n            reset();\n            setStep(Steps.Ok);\n        };\n        void withLoading(run());\n    };\n\n    const [authed, setAuthed] = useState(false);\n\n    if (!authed) {\n        return (\n            <AuthModal\n                config={unlockPasswordChanges()}\n                {...rest}\n                onCancel={onClose}\n                onSuccess={async () => {\n                    setAuthed(true);\n                    reset();\n                }}\n                prioritised2FAItem=\"totp\"\n            />\n        );\n    }\n\n    const handleClose = () => {\n        void silentApi(lockSensitiveSettings());\n        onClose?.();\n    };\n\n    return (\n        <Modal\n            as={Form}\n            onSubmit={(event: FormEvent<HTMLFormElement>) => {\n                if (step === Steps.Tutorial) {\n                    getRegistrationPayload();\n                    return;\n                }\n                if (!onFormSubmit(event.currentTarget)) {\n                    return;\n                }\n                if (step === Steps.Name) {\n                    handleRegister();\n                }\n            }}\n            onClose={handleClose}\n            size=\"small\"\n            behind={behind}\n            {...rest}\n        >\n            <ModalHeader\n                title={(() => {\n                    if (step === Steps.Ok) {\n                        return c('fido2: Title').t`Security key registered`;\n                    }\n                    if (step === Steps.Name) {\n                        return c('fido2: Title').t`Name your security key`;\n                    }\n                    return c('fido2: Title').t`Register your security key`;\n                })()}\n            />\n            <ModalContent>\n                {step === Steps.Tutorial && (\n                    <RegisterSecurityKeyContent\n                        error={fidoError}\n                        checkbox={\n                            <>\n                                <Checkbox\n                                    id=\"allow-platform-keys\"\n                                    checked={allowPlatformKeys}\n                                    onChange={(e) => setAllowPlatformKeys(e.target.checked)}\n                                >\n                                    {c('fido2: Info').t`Allow platform keys`}\n                                </Checkbox>\n                                <Info\n                                    className=\"ml-1\"\n                                    title={c('fido2: Info')\n                                        .t`Allows you to register built-in security keys (like Windows Hello, Face ID, Touch ID, or internal TPMs)`}\n                                />\n                            </>\n                        }\n                    />\n                )}\n                {step === Steps.Name && (\n                    <>\n                        <InputFieldTwo\n                            autoFocus\n                            maxLength={maxSecurityKeyNameLength}\n                            label={c('fido2: Label').t`Key name`}\n                            error={validator([requiredValidator(name)])}\n                            value={name}\n                            onValue={setName}\n                        />\n                        <div>{c('fido2: Info').t`Add a name to identify your security key with.`}</div>\n                    </>\n                )}\n                {step === Steps.Ok && <RegisteredContent />}\n            </ModalContent>\n            {step === Steps.Ok ? (\n                <ModalFooter>\n                    <div />\n                    <Button onClick={handleClose} color=\"norm\">\n                        {c('Action').t`Done`}\n                    </Button>\n                </ModalFooter>\n            ) : (\n                <ModalFooter>\n                    <Button onClick={handleClose} disabled={loading}>\n                        {c('Action').t`Cancel`}\n                    </Button>\n                    <Button loading={loading} type=\"submit\" color=\"norm\">\n                        {c('Action').t`Continue`}\n                    </Button>\n                </ModalFooter>\n            )}\n        </Modal>\n    );\n};\n\nexport default AddSecurityKeyModal;\n","export const maxSecurityKeyNameLength = 128;\nexport const maxSecurityKeyLength = 10;\n","import { FormEvent, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { renameSecurityKey } from '@proton/shared/lib/api/settings';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\n\nimport {\n    Form,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../../components';\nimport { useApi, useErrorHandler, useEventManager, useNotifications } from '../../../hooks';\nimport { maxSecurityKeyNameLength } from './constants';\n\ninterface Props extends ModalProps {\n    id: string;\n    name: string;\n}\n\nconst EditSecurityKeyModal = ({ id, name, onClose, ...rest }: Props) => {\n    const [loading, withLoading] = useLoading();\n    const normalApi = useApi();\n    const errorHandler = useErrorHandler();\n    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });\n    const { call } = useEventManager();\n    const { validator, onFormSubmit } = useFormErrors();\n    const [newName, setNewName] = useState(name);\n    const { createNotification } = useNotifications();\n\n    const handleUpdate = () => {\n        const run = async () => {\n            try {\n                await silentApi(renameSecurityKey(id, { Name: newName }));\n                await call();\n                createNotification({\n                    text: c('fido2: Info').t`Security key updated`,\n                });\n                onClose?.();\n            } catch (e) {\n                errorHandler(e);\n                return;\n            }\n        };\n        withLoading(run());\n    };\n\n    return (\n        <Modal\n            as={Form}\n            onSubmit={(event: FormEvent<HTMLFormElement>) => {\n                if (!onFormSubmit(event.currentTarget)) {\n                    return;\n                }\n                handleUpdate();\n            }}\n            onClose={onClose}\n            size=\"small\"\n            {...rest}\n        >\n            <ModalHeader title={c('fido2: Title').t`Name your security key`} />\n            <ModalContent>\n                <InputFieldTwo\n                    autoFocus\n                    maxLength={maxSecurityKeyNameLength}\n                    label={c('fido2: Label').t`Key name`}\n                    error={validator([requiredValidator(newName)])}\n                    value={newName}\n                    onValue={setNewName}\n                />\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={onClose} disabled={loading}>\n                    {c('Action').t`Cancel`}\n                </Button>\n                <Button loading={loading} type=\"submit\" color=\"norm\">\n                    {c('Action').t`Save`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default EditSecurityKeyModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { removeSecurityKey } from '@proton/shared/lib/api/settings';\nimport { lockSensitiveSettings, unlockPasswordChanges } from '@proton/shared/lib/api/user';\nimport noop from '@proton/utils/noop';\n\nimport { ModalProps, Prompt, useModalState } from '../../../components';\nimport { useApi, useEventManager, useNotifications } from '../../../hooks';\nimport AuthModal from '../../password/AuthModal';\n\ninterface Key {\n    id: string;\n    name: string;\n}\n\ninterface Props extends ModalProps {\n    type: 'single' | 'all';\n    keys: Key[];\n}\n\nconst RemoveSecurityKeyModal = ({ onClose, type, keys, ...rest }: Props) => {\n    const [loading, withLoading] = useLoading();\n    const api = useApi();\n    const { call } = useEventManager();\n    const [authModalProps, setAuthModalOpen, renderAuthModal] = useModalState();\n    const { createNotification } = useNotifications();\n\n    const name = (\n        <span className=\"text-bold text-break\" key=\"name\">\n            {keys[0].name}\n        </span>\n    );\n\n    return (\n        <>\n            {renderAuthModal && (\n                <AuthModal\n                    config={unlockPasswordChanges()}\n                    {...authModalProps}\n                    onCancel={undefined}\n                    onSuccess={async () => {\n                        await Promise.all(\n                            keys.map((key) => {\n                                return api(removeSecurityKey(key.id)).catch(noop);\n                            })\n                        );\n                        await api(lockSensitiveSettings());\n                        await withLoading(\n                            call().then(() => {\n                                if (type === 'single') {\n                                    createNotification({ text: c('fido2: Info').t`Security key removed` });\n                                } else if (type === 'all') {\n                                    createNotification({ text: c('fido2: Info').t`2FA via security key disabled` });\n                                }\n                                onClose?.();\n                            })\n                        );\n                    }}\n                />\n            )}\n            <Prompt\n                {...rest}\n                title={\n                    type === 'all'\n                        ? c('fido2: Title').t`Disable 2FA via security key?`\n                        : c('fido2: Title').t`Delete security key?`\n                }\n                onClose={onClose}\n                buttons={[\n                    <Button\n                        loading={loading}\n                        color=\"danger\"\n                        onClick={() => {\n                            setAuthModalOpen(true);\n                        }}\n                    >\n                        {type === 'all' && c('Action').t`Disable`}\n                        {type === 'single' && c('fido2: Action').t`Delete key`}\n                    </Button>,\n                    <Button disabled={loading} onClick={onClose}>\n                        {c('Action').t`Cancel`}\n                    </Button>,\n                ]}\n            >\n                {type === 'all' && c('fido2: Info').t`This will delete all security keys linked to your account.`}\n                {type === 'single' && c('fido2: Info').jt`Are you sure you want to delete security key ${name}?`}\n            </Prompt>\n        </>\n    );\n};\n\nexport default RemoveSecurityKeyModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { disableTotp } from '@proton/shared/lib/api/settings';\n\nimport { ModalProps, Prompt, useModalState } from '../../../components';\nimport { useEventManager, useNotifications } from '../../../hooks';\nimport AuthModal from '../../password/AuthModal';\n\nconst DisableTOTPModal = ({ onClose, ...rest }: ModalProps) => {\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [loading, withLoading] = useLoading();\n    const [authModalProps, setAuthModalOpen, renderAuthModal] = useModalState();\n\n    return (\n        <>\n            {renderAuthModal && (\n                <AuthModal\n                    config={disableTotp()}\n                    {...authModalProps}\n                    onCancel={undefined}\n                    onSuccess={async () => {\n                        await withLoading(call());\n                        onClose?.();\n                        createNotification({ text: c('Info').t`Two-factor authentication disabled` });\n                    }}\n                />\n            )}\n            <Prompt\n                {...rest}\n                title={c('Title').t`Disable two-factor authentication`}\n                onClose={onClose}\n                buttons={[\n                    <Button\n                        loading={loading}\n                        color=\"danger\"\n                        onClick={() => {\n                            setAuthModalOpen(true);\n                        }}\n                    >\n                        {c('Action').t`Disable`}\n                    </Button>,\n                    <Button disabled={loading} onClick={onClose}>\n                        {c('Action').t`Cancel`}\n                    </Button>,\n                ]}\n            >\n                {c('Info').t`Are you sure you want to disable two-factor authentication?`}\n            </Prompt>\n        </>\n    );\n};\n\nexport default DisableTOTPModal;\n","import { FormEvent, ReactNode, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button, Href, InlineLinkButton } from '@proton/atoms';\nimport { useLoading } from '@proton/hooks';\nimport { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';\nimport { TOTP_WRONG_ERROR, setupTotp } from '@proton/shared/lib/api/settings';\nimport { unlockPasswordChanges } from '@proton/shared/lib/api/user';\nimport { APPS, BRAND_NAME } from '@proton/shared/lib/constants';\nimport downloadFile from '@proton/shared/lib/helpers/downloadFile';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { getTOTPData } from '@proton/shared/lib/settings/twoFactor';\nimport noop from '@proton/utils/noop';\n\nimport {\n    Copy,\n    Form,\n    InputFieldTwo,\n    Loader,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    QRCode,\n    TotpInput,\n    useFormErrors,\n} from '../../../components';\nimport { useApi, useConfig, useEventManager, useNotifications, useUser } from '../../../hooks';\nimport AuthModal from '../../password/AuthModal';\n\ninterface ModalProperties {\n    section: ReactNode;\n    cancelButtonText?: string | null;\n    onCancel?: () => void;\n    submitButtonText?: string | null;\n    onSubmit?: (event: FormEvent<HTMLFormElement>) => void;\n}\n\ninterface SetupTOTPResponse {\n    TwoFactorRecoveryCodes: string[];\n}\n\nconst STEPS = {\n    INFO: 1,\n    SCAN_CODE: 2,\n    CONFIRM_CODE: 3,\n    RECOVERY_CODES: 4,\n};\n\nconst EnableTOTPModal = ({ onClose, ...rest }: ModalProps) => {\n    const { APP_NAME } = useConfig();\n    const [user] = useUser();\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [{ sharedSecret, uri = '', period, digits }] = useState(() => {\n        return getTOTPData(user.Email || user.Name);\n    });\n    const [step, setStep] = useState(STEPS.INFO);\n    const [manualCode, setManualCode] = useState(false);\n    const [recoveryCodes, setRecoveryCodes] = useState<string[]>([]);\n    const [confirmationCode, setConfirmationCode] = useState('');\n    const [totpError, setTotpError] = useState('');\n    const [loading, withLoading] = useLoading();\n    const { validator, onFormSubmit } = useFormErrors();\n\n    const handleClose = loading ? noop : onClose;\n\n    const [authed, setAuthed] = useState(false);\n\n    if (!authed) {\n        return (\n            <AuthModal\n                config={unlockPasswordChanges()}\n                {...rest}\n                onCancel={onClose}\n                onSuccess={async () => {\n                    setAuthed(true);\n                }}\n            />\n        );\n    }\n\n    const {\n        section,\n        cancelButtonText,\n        onCancel = handleClose,\n        submitButtonText,\n        onSubmit,\n    } = ((): ModalProperties => {\n        if (!sharedSecret) {\n            return {\n                section: <Loader />,\n            };\n        }\n\n        if (step === STEPS.INFO) {\n            const twoFactorAuthLink =\n                APP_NAME === APPS.PROTONVPN_SETTINGS\n                    ? 'https://protonvpn.com/support/two-factor-authentication'\n                    : getKnowledgeBaseUrl('/two-factor-authentication-2fa');\n\n            // translator: complete sentence is: If you have never used two-factor authentication before, we strongly recommend you <link>read our two-factor authentication guide first</link>.\n            const guideButton = (\n                <Href key=\"0\" href={twoFactorAuthLink}>{c('Info')\n                    .t`read our two-factor authentication guide first`}</Href>\n            );\n\n            const BRAND_NAME_TWO = BRAND_NAME;\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb-4\">\n                            {c('Info')\n                                .t`This wizard will enable Two-Factor Authentication (2FA) on your ${BRAND_NAME} account. Two-factor authentication will make your ${BRAND_NAME_TWO} account more secure so we recommend enabling it.`}\n                        </div>\n                        <div className=\"mb-4\">\n                            {\n                                // translator: complete sentence is: If you have never used two-factor authentication before, we strongly recommend you <link>read our two-factor authentication guide first</link>.\n                                c('Info')\n                                    .jt`If you have never used two-factor authentication before, we strongly recommend you ${guideButton}.`\n                            }\n                        </div>\n                    </>\n                ),\n                onSubmit() {\n                    setStep(STEPS.SCAN_CODE);\n                },\n            };\n        }\n\n        const handleSubmitScan = () => {\n            setStep(STEPS.CONFIRM_CODE);\n        };\n\n        if (step === STEPS.SCAN_CODE && !manualCode) {\n            // made button explicitly focusable to fix an issue for a blind user\n            const switchButton = (\n                <InlineLinkButton\n                    tabIndex={0}\n                    data-testid=\"totp:manual-button\"\n                    key=\"0\"\n                    onClick={() => setManualCode(true)}\n                >\n                    {c('Info').t`Enter key manually instead`}\n                </InlineLinkButton>\n            );\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb-4\">\n                            {c('Info')\n                                .jt`Scan this code with your two-factor authentication device to set up your account. ${switchButton}.`}\n                        </div>\n                        <div className=\"text-center\">\n                            <QRCode value={uri} size={200} />\n                        </div>\n                    </>\n                ),\n                onSubmit: handleSubmitScan,\n            };\n        }\n\n        if (step === STEPS.SCAN_CODE && manualCode) {\n            const switchButton = (\n                <InlineLinkButton key=\"0\" onClick={() => setManualCode(false)}>\n                    {c('Info').t`Scan QR code instead`}\n                </InlineLinkButton>\n            );\n\n            // added spaces to get a better vocalization for blind users\n            const labelCode = sharedSecret.split('').join(' ');\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb-4\">\n                            {c('Info')\n                                .jt`Manually enter this information into your two-factor authentication device to set up your account. ${switchButton}.`}\n                        </div>\n                        <div>\n                            <div className=\"flex flex-column sm:flex-row sm:items-center flex-nowrap max-w-full mb-2\">\n                                <div className=\"sm:w-1/5 my-auto\" id=\"label-key-desc\">{c('Label').t`Key`}</div>\n                                <div className=\"sm:w-4/5 flex items-center text-bold\">\n                                    {/* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */}\n                                    <code\n                                        className=\"text-ellipsis flex-1 py-2\"\n                                        data-testid=\"totp:secret-key\"\n                                        aria-label={labelCode}\n                                        aria-describedby=\"label-key-desc\"\n                                        tabIndex={0}\n                                        title={sharedSecret}\n                                    >\n                                        {sharedSecret}\n                                    </code>\n                                    <Copy\n                                        className=\"ml-2 shrink-0\"\n                                        tooltipText={c('Action').t`Copy key to the clipboard`}\n                                        value={sharedSecret}\n                                        onCopy={() =>\n                                            createNotification({\n                                                text: c('Notification').t`Key copied to the clipboard`,\n                                            })\n                                        }\n                                    />\n                                </div>\n                            </div>\n                            <div className=\"flex flex-column sm:flex-row sm:items-center flex-nowrap max-w-full  mb-4\">\n                                <div className=\"sm:w-1/5 my-auto\">{c('Label').t`Interval`}</div>\n                                <div className=\"sm:w-4/5 text-bold\">\n                                    <code>{period}</code>\n                                </div>\n                            </div>\n                            <div className=\"flex flex-column sm:flex-row sm:items-center flex-nowrap max-w-full  mb-4\">\n                                <div className=\"sm:w-1/5 my-auto\">{c('Label').t`Digits`}</div>\n                                <div className=\"sm:w-4/5 text-bold\">\n                                    <code>{digits}</code>\n                                </div>\n                            </div>\n                        </div>\n                    </>\n                ),\n                onSubmit: handleSubmitScan,\n            };\n        }\n\n        if (step === STEPS.CONFIRM_CODE) {\n            const handleSubmit = async () => {\n                try {\n                    const result = await api<SetupTOTPResponse>(setupTotp(sharedSecret, confirmationCode));\n                    await call();\n                    createNotification({ text: c('Info').t`Two-factor authentication enabled` });\n                    setRecoveryCodes(result.TwoFactorRecoveryCodes);\n                    setStep(STEPS.RECOVERY_CODES);\n                } catch (error: any) {\n                    const { code, message } = getApiError(error);\n                    if (code === TOTP_WRONG_ERROR) {\n                        setTotpError(message);\n                    }\n                }\n            };\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb-4\">{c('Info').t`Enter the code from your authenticator app`}</div>\n                        <InputFieldTwo\n                            as={TotpInput}\n                            autoFocus\n                            length={6}\n                            autoComplete=\"one-time-code\"\n                            id=\"totp\"\n                            value={confirmationCode}\n                            disableChange={loading}\n                            onValue={(value: string) => {\n                                setConfirmationCode(value);\n                                setTotpError('');\n                            }}\n                            error={validator([requiredValidator(confirmationCode), totpError])}\n                        />\n                    </>\n                ),\n                cancelButtonText: c('Action').t`Back`,\n                onCancel: () => {\n                    setStep(STEPS.SCAN_CODE);\n                },\n                submitButtonText: c('Action').t`Submit`,\n                onSubmit(event: FormEvent<HTMLFormElement>) {\n                    if (!onFormSubmit(event.currentTarget)) {\n                        return;\n                    }\n                    void withLoading(handleSubmit());\n                },\n            };\n        }\n\n        if (step === STEPS.RECOVERY_CODES) {\n            return {\n                section: (\n                    <>\n                        <div className=\"mb-4\">\n                            <span className=\"text-bold\">{c('Info')\n                                .t`Important: Please make sure you save the recovery codes. Otherwise you can permanently lose access to your account if you lose your two-factor authentication device.`}</span>\n                            <br />\n                            <br />\n                            {c('Info')\n                                .t`If you lose your two-factor-enabled device, these codes can be used instead of the 6-digit two-factor authentication code to sign in to your account. Each code can only be used once.`}\n                        </div>\n                        <div className=\"flex text-center\">\n                            {recoveryCodes.map((code) => {\n                                return (\n                                    <code\n                                        data-testid=\"totp:recovery-code\"\n                                        key={code}\n                                        className=\"w-custom p-2\"\n                                        style={{ '--w-custom': '49%' }}\n                                    >\n                                        {code}\n                                    </code>\n                                );\n                            })}\n                        </div>\n                        <div className=\"text-center\">\n                            <Button\n                                color=\"norm\"\n                                onClick={() => {\n                                    const blob = new Blob([recoveryCodes.join('\\r\\n')], {\n                                        type: 'text/plain;charset=utf-8',\n                                    });\n                                    const filename = 'proton_recovery_codes.txt';\n                                    downloadFile(blob, filename);\n                                }}\n                            >\n                                {c('Action').t`Download`}\n                            </Button>\n                        </div>\n                    </>\n                ),\n                submitButtonText: null,\n                onSubmit() {\n                    onClose?.();\n                },\n                cancelButtonText: c('Action').t`Close`,\n            };\n        }\n\n        throw new Error('Unknown step');\n    })();\n\n    return (\n        <Modal as={Form} onSubmit={onSubmit} onClose={handleClose} size=\"medium\" {...rest}>\n            <ModalHeader title={c('Title').t`Set up two-factor authentication`} />\n            <ModalContent>{section}</ModalContent>\n            <ModalFooter>\n                {cancelButtonText !== null ? (\n                    <Button onClick={onCancel} disabled={loading}>\n                        {cancelButtonText || c('Action').t`Cancel`}\n                    </Button>\n                ) : (\n                    // Maintain submit button positioning\n                    <div />\n                )}\n                {submitButtonText !== null && (\n                    <Button loading={loading} type=\"submit\" color=\"norm\">\n                        {submitButtonText || c('Action').t`Next`}\n                    </Button>\n                )}\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default EnableTOTPModal;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { getHasFIDO2SettingEnabled, getHasTOTPSettingEnabled } from '@proton/shared/lib/settings/twoFactor';\nimport { getHasFIDO2Support } from '@proton/shared/lib/webauthn/helper';\nimport { getId } from '@proton/shared/lib/webauthn/id';\nimport clsx from '@proton/utils/clsx';\n\nimport { ButtonGroup, Icon, Info, Toggle, Tooltip, useModalState } from '../../components';\nimport { useConfig, useNotifications, useUserSettings } from '../../hooks';\nimport SettingsLayout from './SettingsLayout';\nimport SettingsLayoutLeft from './SettingsLayoutLeft';\nimport SettingsLayoutRight from './SettingsLayoutRight';\nimport SettingsParagraph from './SettingsParagraph';\nimport SettingsSection from './SettingsSection';\nimport AddSecurityKeyModal from './fido/AddSecurityKeyModal';\nimport EditSecurityKeyModal from './fido/EditSecurityKeyModal';\nimport RemoveSecurityKeyModal from './fido/RemoveSecurityKeyModal';\nimport { maxSecurityKeyLength } from './fido/constants';\nimport DisableTOTPModal from './totp/DisableTOTPModal';\nimport EnableTOTPModal from './totp/EnableTOTPModal';\n\nconst defaultTmpRemove = { keys: [], type: 'all' as const };\n\nconst TwoFactorSection = () => {\n    const { APP_NAME } = useConfig();\n    const [userSettings] = useUserSettings();\n    const { createNotification } = useNotifications();\n    const [enableTOTPModal, setEnableTOTPModalOpen, renderEnableTOTPModal] = useModalState();\n    const [disableTOTPModal, setDisableTOTPModalOpen, renderDisableTOTPModal] = useModalState();\n    const [addSecurityKeyModal, setAddSecurityKeyModal, renderAddSecurityKeyModal] = useModalState();\n    const [removeSecurityKeyModal, setRemoveSecurityKeyModal, renderRemoveSecurityKeyModal] = useModalState();\n    const [editSecurityKeyModal, setEditSecurityKeyModal, renderEditSecurityKeyModal] = useModalState();\n    const [tmpRemove, setTmpRemove] = useState<{ keys: { name: string; id: string }[]; type: 'all' | 'single' }>(\n        defaultTmpRemove\n    );\n    const [tmpEdit, setTmpEdit] = useState<{ name: string; id: string } | undefined>(undefined);\n\n    const hasTOTPEnabled = getHasTOTPSettingEnabled(userSettings);\n    const hasFIDO2Enabled = getHasFIDO2SettingEnabled(userSettings);\n\n    const registeredKeys = userSettings['2FA']?.RegisteredKeys || [];\n    const canEnableFido2 = hasTOTPEnabled;\n\n    const canDisableTOTP = hasTOTPEnabled && !registeredKeys.length;\n\n    const handleChangeTOTP = () => {\n        if (hasTOTPEnabled) {\n            if (!canDisableTOTP) {\n                createNotification({\n                    text: c('fido2: Error').t`Please disable 2FA via security key before disabling TOTP`,\n                    type: 'error',\n                });\n                return;\n            }\n            setDisableTOTPModalOpen(true);\n        } else {\n            setEnableTOTPModalOpen(true);\n        }\n    };\n\n    const handleChangeKey = () => {\n        const keys = registeredKeys.map((RegisteredKey) => ({ id: getId(RegisteredKey), name: RegisteredKey.Name }));\n        if (hasFIDO2Enabled && keys.length) {\n            setTmpRemove({ keys, type: 'all' });\n            setRemoveSecurityKeyModal(true);\n            return;\n        }\n        setAddSecurityKeyModal(true);\n    };\n\n    const twoFactorAuthLink =\n        APP_NAME === APPS.PROTONVPN_SETTINGS\n            ? 'https://protonvpn.com/support/two-factor-authentication'\n            : getKnowledgeBaseUrl('/two-factor-authentication-2fa');\n\n    const hasSecurityKeySupport = getHasFIDO2Support(APP_NAME, location.hostname);\n\n    return (\n        <SettingsSection>\n            {renderEnableTOTPModal && <EnableTOTPModal {...enableTOTPModal} />}\n            {renderDisableTOTPModal && <DisableTOTPModal {...disableTOTPModal} />}\n            <SettingsParagraph>\n                {c('Info')\n                    .t`Add another layer of security to your account. You’ll need to verify yourself with 2FA every time you sign in.`}\n            </SettingsParagraph>\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"twoFactorToggle\" className=\"text-semibold\">\n                        <span className=\"mr-2\">{c('Label').t`Authenticator app`}</span>\n                        <Info\n                            url={twoFactorAuthLink}\n                            title={c('Info')\n                                .t`Verify your identity with a time-based one-time password from an authenticator app`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight isToggleContainer>\n                    <Toggle checked={hasTOTPEnabled} id=\"twoFactorToggle\" onChange={handleChangeTOTP} />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n            {hasSecurityKeySupport && (\n                <>\n                    {renderAddSecurityKeyModal && <AddSecurityKeyModal {...addSecurityKeyModal} />}\n                    {renderRemoveSecurityKeyModal && tmpRemove.keys.length && (\n                        <RemoveSecurityKeyModal\n                            keys={tmpRemove.keys}\n                            type={tmpRemove.type}\n                            {...removeSecurityKeyModal}\n                            onExit={() => {\n                                removeSecurityKeyModal.onExit();\n                                setTmpRemove(defaultTmpRemove);\n                            }}\n                        />\n                    )}\n                    {renderEditSecurityKeyModal && tmpEdit && (\n                        <EditSecurityKeyModal\n                            id={tmpEdit.id}\n                            name={tmpEdit.name}\n                            {...editSecurityKeyModal}\n                            onExit={() => {\n                                editSecurityKeyModal.onExit();\n                                setTmpEdit(undefined);\n                            }}\n                        />\n                    )}\n                    <SettingsLayout>\n                        <SettingsLayoutLeft>\n                            <label htmlFor=\"twoFactorKeyToggle\" className=\"text-semibold\">\n                                <span className={clsx(['mr-2', !canEnableFido2 && 'color-weak'])}>\n                                    {c('fido2: Info').t`Security key`}\n                                </span>\n                                <Info\n                                    url={twoFactorAuthLink}\n                                    title={c('fido2: Info')\n                                        .t`Verify your identity with a physical U2F or FIDO2 security key`}\n                                />\n                            </label>\n                        </SettingsLayoutLeft>\n                        <SettingsLayoutRight isToggleContainer>\n                            <Tooltip\n                                title={\n                                    !canEnableFido2\n                                        ? c('fido2: Info')\n                                              .t`To turn on 2FA via security key, you'll need to activate 2FA via authenticator app`\n                                        : ''\n                                }\n                            >\n                                <span className=\"inline-flex\">\n                                    <Toggle\n                                        checked={hasFIDO2Enabled}\n                                        id=\"twoFactorKeyToggle\"\n                                        onChange={handleChangeKey}\n                                        disabled={!canEnableFido2}\n                                    />\n                                </span>\n                            </Tooltip>\n                        </SettingsLayoutRight>\n                    </SettingsLayout>\n                    {registeredKeys.length > 0 && (\n                        <div className=\"mb-4\">\n                            <div>\n                                <Button\n                                    disabled={registeredKeys.length >= maxSecurityKeyLength}\n                                    onClick={() => {\n                                        setAddSecurityKeyModal(true);\n                                    }}\n                                    className=\"flex flex-nowrap items-center\"\n                                >\n                                    <Icon name=\"plus\" className=\"mr-2\" />\n                                    {c('fido2: Action').t`Add security key`}\n                                </Button>\n                            </div>\n                            <div className=\"mt-4 w-full\">\n                                <div className=\"text-bold pb-2 border-bottom\">\n                                    {c('fido2: Title').t`Registered security keys`}\n                                </div>\n                                {registeredKeys.map((registeredKey) => {\n                                    const id = getId(registeredKey);\n                                    return (\n                                        <div key={id} className=\"flex items-center py-2 border-bottom\">\n                                            <div className=\"flex-1 text-break mr-2\">{registeredKey.Name}</div>\n                                            <ButtonGroup size=\"small\">\n                                                <Button\n                                                    icon\n                                                    onClick={() => {\n                                                        setTmpEdit({\n                                                            id,\n                                                            name: registeredKey.Name,\n                                                        });\n                                                        setEditSecurityKeyModal(true);\n                                                    }}\n                                                >\n                                                    <Icon name=\"pen\" />\n                                                </Button>\n                                                <Button\n                                                    icon\n                                                    onClick={() => {\n                                                        setTmpRemove({\n                                                            keys: [{ id, name: registeredKey.Name }],\n                                                            type: 'single',\n                                                        });\n                                                        setRemoveSecurityKeyModal(true);\n                                                    }}\n                                                >\n                                                    <Icon name=\"trash\" />\n                                                </Button>\n                                            </ButtonGroup>\n                                        </div>\n                                    );\n                                })}\n                            </div>\n                        </div>\n                    )}\n                </>\n            )}\n        </SettingsSection>\n    );\n};\n\nexport default TwoFactorSection;\n","import React, { MutableRefObject, useEffect, useImperativeHandle, useRef, useState } from 'react';\n\nimport { addHours } from 'date-fns';\nimport { c } from 'ttag';\n\nimport * as sessionStorageWrapper from '@proton/shared/lib/helpers/sessionStorage';\nimport * as localStorageWrapper from '@proton/shared/lib/helpers/storage';\nimport { getApiSubdomainUrl } from '@proton/shared/lib/helpers/url';\nimport { UserModel } from '@proton/shared/lib/interfaces';\n\nimport { useNotifications } from '../../hooks';\n\n// The sizes for these are hardcoded since the widget calculates it based on the viewport, and since it's in\n// an iframe it needs to have something reasonable.\n// The main chat widget.\nconst OPENED_SIZE = {\n    height: `${572 / 16}rem`,\n    width: `${374 / 16}rem`,\n};\n// The small button to toggle the chat.\nconst CLOSED_SIZE = {\n    height: `${70 / 16}rem`,\n    width: `${140 / 16}rem`,\n};\n\nconst SINGLE_CHAT_KEY = 'zk_state';\nconst SINGLE_CHAT_TIMEOUT = 10000;\n\nconst getIframeUrl = (zendeskKey: string) => {\n    const url = getApiSubdomainUrl('/core/v4/resources/zendesk', window.location.origin);\n    url.searchParams.set('Key', zendeskKey);\n    return url;\n};\n\nexport const getIsSelfChat = () => {\n    return sessionStorageWrapper.getItem(SINGLE_CHAT_KEY);\n};\nconst removeSelfActiveMarker = () => {\n    return sessionStorageWrapper.removeItem(SINGLE_CHAT_KEY);\n};\nconst getIsActiveInAnotherWindow = () => {\n    return !getIsSelfChat() && +(localStorageWrapper.getItem(SINGLE_CHAT_KEY) || 0) > Date.now();\n};\nconst setActiveMarker = () => {\n    localStorageWrapper.setItem(SINGLE_CHAT_KEY, `${+Date.now() + SINGLE_CHAT_TIMEOUT}`);\n    sessionStorageWrapper.setItem(SINGLE_CHAT_KEY, '1');\n};\n\nconst clearPaidMarkers = () => {\n    if (!localStorageWrapper.hasStorage()) {\n        return;\n    }\n    for (let i = 0; i < localStorage.length; i++) {\n        const key = localStorage.key(i);\n        if (key?.startsWith('LiveChat')) {\n            if (+(localStorage.getItem(key) || 0) < Date.now()) {\n                localStorage.removeItem(key);\n            }\n        }\n    }\n};\nconst setPaidMarker = (userID: string) => {\n    return localStorageWrapper.setItem(`LiveChat-${userID}`, addHours(new Date(), 24).getTime().toString());\n};\nconst getPaidMarker = (userID: string) => {\n    return +(localStorageWrapper.getItem(`LiveChat-${userID}`) || 0);\n};\n\nexport const useCanEnableChat = (user: UserModel) => {\n    const hasCachedChat = getPaidMarker(user.ID) > Date.now();\n    const canEnableChat = user.hasPaidVpn || hasCachedChat;\n\n    useEffect(() => {\n        clearPaidMarkers();\n        if (!user.hasPaidVpn) {\n            return;\n        }\n        const setMarker = () => {\n            // Clear old items\n            clearPaidMarkers();\n            // Enable the user to access chat 24 hours after in case she unsubscribes\n            setPaidMarker(user.ID);\n        };\n        setMarker();\n        const handle = window.setInterval(setMarker, 60000);\n        return () => window.clearInterval(handle);\n    }, [user.hasPaidVpn]);\n\n    return canEnableChat;\n};\n\nexport interface ZendeskRef {\n    run: (data: object) => void;\n    toggle: () => void;\n}\n\ninterface Props {\n    zendeskKey: string;\n    zendeskRef?: MutableRefObject<ZendeskRef | undefined>;\n    name?: string;\n    email?: string;\n    onLoaded: () => void;\n    onUnavailable: () => void;\n    locale: string;\n    tags: string[];\n}\n\nconst LiveChatZendesk = ({ zendeskKey, zendeskRef, name, email, onLoaded, onUnavailable, locale, tags }: Props) => {\n    const [style, setStyle] = useState({\n        position: 'absolute',\n        bottom: 0,\n        right: 0,\n        maxHeight: '100%',\n        maxWidth: '100%',\n        zIndex: '999999',\n        ...CLOSED_SIZE,\n    });\n    const [state, setState] = useState({ loaded: false, connected: false });\n    const stateRef = useRef({ loaded: false, connected: false });\n    const iframeRef = useRef<HTMLIFrameElement>(null);\n    const pendingLoadingRef = useRef<{ toggle?: boolean; locale?: string }>({});\n\n    const iframeUrl = getIframeUrl(zendeskKey);\n\n    const src = iframeUrl.toString();\n    const targetOrigin = iframeUrl.origin;\n\n    const handleRun = (args: any) => {\n        const contentWindow = iframeRef.current?.contentWindow;\n        if (!contentWindow || !stateRef.current.loaded) {\n            return;\n        }\n        contentWindow.postMessage({ args }, targetOrigin);\n    };\n\n    const handleToggle = () => {\n        // Using the ref instead of state to not have to wait for re-render\n        if (!stateRef.current.connected) {\n            onUnavailable();\n            return;\n        }\n        pendingLoadingRef.current.toggle = true;\n        handleRun(['webWidget', 'toggle']);\n    };\n\n    useImperativeHandle(zendeskRef, () => ({\n        run: handleRun,\n        toggle: handleToggle,\n    }));\n\n    useEffect(() => {\n        if (!state.loaded) {\n            return;\n        }\n        handleRun([\n            'webWidget',\n            'prefill',\n            {\n                name: { value: name, readOnly: false },\n                email: { value: email, readOnly: Boolean(email) },\n            },\n        ]);\n    }, [state.loaded, name, email]);\n\n    useEffect(() => {\n        if (!state.loaded) {\n            return;\n        }\n        handleRun(['webWidget', 'setLocale', locale]);\n    }, [state.loaded, locale]);\n\n    useEffect(() => {\n        if (!state.loaded || !tags.length) {\n            return;\n        }\n        handleRun(['webWidget', 'chat:addTags', tags]);\n        return () => {\n            handleRun(['webWidget', 'chat:removeTags', tags]);\n        };\n    }, [state.loaded, tags]);\n\n    useEffect(() => {\n        if (!state.loaded || !pendingLoadingRef.current) {\n            return;\n        }\n        const oldPending = pendingLoadingRef.current;\n        pendingLoadingRef.current = {};\n        if (oldPending.toggle) {\n            handleToggle();\n        }\n    }, [state.loaded]);\n\n    useEffect(() => {\n        let globalId = 1;\n        const handlers: { [key: string]: [(value: any) => void, (reason?: any) => void, number] } = {};\n\n        const sendMessage = (contentWindow: Window, args: any) => {\n            contentWindow.postMessage({ args }, targetOrigin);\n        };\n\n        const sendMessageWithReply = <T,>(contentWindow: Window, args: any): Promise<T> => {\n            const id = globalId++;\n            contentWindow.postMessage({ id, args }, targetOrigin);\n            return new Promise((resolve, reject) => {\n                const intervalId = window.setTimeout(() => {\n                    delete handlers[id];\n                }, 30000);\n                handlers[id] = [resolve, reject, intervalId];\n            });\n        };\n\n        const handleMessage = (event: MessageEvent) => {\n            const contentWindow = iframeRef.current?.contentWindow;\n            const { origin, data, source } = event;\n            if (!contentWindow || origin !== targetOrigin || !data || source !== contentWindow) {\n                return;\n            }\n\n            const departmentName = 'Support';\n\n            if (data.type === 'on') {\n                if (data.payload?.event === 'open') {\n                    setStyle((oldStyle) => ({ ...oldStyle, ...OPENED_SIZE }));\n                }\n\n                if (data.payload?.event === 'close') {\n                    setStyle((oldStyle) => ({ ...oldStyle, ...CLOSED_SIZE }));\n                }\n\n                if (data.payload?.event === 'chat:connected') {\n                    sendMessage(contentWindow, [\n                        'webWidget',\n                        'updateSettings',\n                        {\n                            webWidget: {\n                                chat: {\n                                    departments: {\n                                        enabled: [departmentName],\n                                        select: departmentName,\n                                    },\n                                },\n                            },\n                        },\n                    ]);\n\n                    sendMessageWithReply<any>(contentWindow, ['webWidget:get', 'chat:department', departmentName])\n                        .then((result) => {\n                            const connected = result?.status === 'online';\n                            stateRef.current = { loaded: true, connected };\n                            setState({ loaded: true, connected });\n                            onLoaded();\n                        })\n                        .catch(() => {\n                            stateRef.current = { loaded: true, connected: false };\n                            setState({ loaded: true, connected: false });\n                            onLoaded();\n                        });\n                }\n\n                if (data.payload?.event === 'chat:departmentStatus') {\n                    const { chatDepartment } = data.payload;\n                    if (!chatDepartment) {\n                        return;\n                    }\n                    const connected = chatDepartment?.status === 'online';\n                    stateRef.current = { loaded: true, connected };\n                    setState({ loaded: true, connected });\n                }\n            }\n\n            if (data.type === 'response') {\n                if (data.payload.id !== undefined) {\n                    const handler = handlers[data.payload.id];\n                    if (handler) {\n                        delete handlers[data.payload.id];\n                        handler[0](data.payload.result);\n                    }\n                }\n            }\n\n            if (data.type === 'loaded') {\n                sendMessage(contentWindow, [\n                    'webWidget',\n                    'updateSettings',\n                    {\n                        webWidget: {\n                            color: {\n                                launcher: '#6d4aff',\n                                button: '#6d4aff',\n                                header: '#261b57',\n                            },\n                        },\n                    },\n                ]);\n            }\n        };\n\n        window.addEventListener('message', handleMessage, false);\n\n        return () => {\n            window.removeEventListener('message', handleMessage, false);\n\n            for (const handlerKey of Object.keys(handlers)) {\n                const handler = handlers[handlerKey];\n                handler[1](new Error('Unmount'));\n                window.clearTimeout(handler[2]);\n                delete handlers[handlerKey];\n            }\n        };\n    }, []);\n\n    return (\n        <div className={!state.connected ? 'hidden' : ''}>\n            <iframe\n                title=\"Zendesk\"\n                src={src}\n                style={style}\n                ref={iframeRef}\n                sandbox=\"allow-scripts allow-same-origin allow-popups allow-forms\"\n            />\n        </div>\n    );\n};\n\nconst LiveChatZendeskSingleton = ({ zendeskRef, ...rest }: Props) => {\n    const { createNotification } = useNotifications();\n    const [isActive, setIsActive] = useState(() => !getIsActiveInAnotherWindow());\n    const actualZendeskRef = useRef<ZendeskRef>();\n\n    useEffect(() => {\n        const interval = window.setInterval(() => {\n            if (getIsActiveInAnotherWindow()) {\n                return;\n            }\n            setIsActive(true);\n            setActiveMarker();\n        }, SINGLE_CHAT_TIMEOUT / 2);\n\n        return () => {\n            clearInterval(interval);\n            removeSelfActiveMarker();\n        };\n    }, []);\n\n    useImperativeHandle(zendeskRef, () => ({\n        run: (...args) => actualZendeskRef.current?.run(...args),\n        toggle: (...args) => {\n            if (getIsActiveInAnotherWindow()) {\n                createNotification({\n                    text: c('Info')\n                        .t`You can only have one chat instance open at a time. Please close previous conversations before starting a new one.`,\n                    type: 'error',\n                });\n                return;\n            }\n            actualZendeskRef.current?.toggle(...args);\n        },\n    }));\n\n    useEffect(() => {\n        if (!isActive) {\n            rest.onLoaded();\n        }\n    }, []);\n\n    if (!isActive) {\n        return null;\n    }\n\n    return <LiveChatZendesk zendeskRef={actualZendeskRef} {...rest} />;\n};\n\nexport default LiveChatZendeskSingleton;\n","import { useEffect, useRef, useState } from 'react';\nimport * as React from 'react';\n\nimport { Input } from '@proton/components';\n\nimport './TVCodeInputs.scss';\n\ninterface Props {\n    value: string;\n    setValue: (value: string) => void;\n}\n\nconst TVCodeInputs = ({ value, setValue }: Props) => {\n    const [first, setFirst] = useState(() => value.substring(0, 4));\n    const [second, setSecond] = useState(() => value.substring(4, 4));\n    const refFirstInput = useRef<HTMLInputElement>(null);\n    const refSecondInput = useRef<HTMLInputElement>(null);\n\n    const handleKeyUpFirst = (event: React.KeyboardEvent<HTMLElement>) => {\n        const eventKey = event.key;\n        if (first.length === 4 && eventKey !== 'Backspace' && eventKey !== 'Delete') {\n            event.preventDefault();\n            refSecondInput?.current?.focus();\n        }\n    };\n\n    const handleKeyUpSecond = (event: React.KeyboardEvent<HTMLElement>) => {\n        const eventKey = event.key;\n        if (second.length === 0 && (eventKey === 'Backspace' || eventKey === 'Delete')) {\n            refFirstInput?.current?.focus();\n            setSecond('');\n        }\n    };\n\n    const handleOnChangeFirst = (event: React.ChangeEvent<HTMLInputElement>) => {\n        if (event.target.value.length > 4) {\n            event.preventDefault();\n            return false;\n        }\n        setFirst(event.target.value.toUpperCase());\n    };\n\n    const handleOnChangeSecond = (event: React.ChangeEvent<HTMLInputElement>) => {\n        if (event.target.value.length > 4) {\n            event.preventDefault();\n            return false;\n        }\n        setSecond(event.target.value.toUpperCase());\n    };\n\n    useEffect(() => {\n        setValue([first, second].join(''));\n    }, [first, second]);\n\n    return (\n        <>\n            <div className=\"code-input-container block md:flex justify-center\">\n                <div className=\"code-input-div flex-1 flex flex-column text-center pb-4 md:pb-0 pt-2 md:pt-0\">\n                    <Input\n                        ref={refFirstInput}\n                        minLength={4}\n                        maxLength={4}\n                        value={first}\n                        onChange={handleOnChangeFirst}\n                        onKeyUp={handleKeyUpFirst}\n                        placeholder=\"1234\"\n                        className=\"text-bold max-w-custom self-end m-auto\"\n                        style={{ '--max-w-custom': '15em' }}\n                        required\n                        autoFocus\n                    />\n                </div>\n                <hr className=\"w-custom tv-hr mx-4 mt-6 mb-auto hidden md:flex\" style={{ '--w-custom': '5%' }} />\n                <div className=\"code-input-div flex-1 flex flex-column text-center pb-4 md:pb-0 pt-2 md:pt-0\">\n                    <Input\n                        ref={refSecondInput}\n                        minLength={4}\n                        maxLength={4}\n                        value={second}\n                        onChange={handleOnChangeSecond}\n                        onKeyUp={handleKeyUpSecond}\n                        placeholder=\"ABCD\"\n                        className=\"text-bold max-w-custom m-auto\"\n                        style={{ '--max-w-custom': '15em' }}\n                        required\n                    />\n                </div>\n            </div>\n        </>\n    );\n};\n\nexport default TVCodeInputs;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Href } from '@proton/atoms';\nimport { Icon, PrimaryButton, VpnLogo, useApi } from '@proton/components';\nimport { useLoading } from '@proton/hooks';\nimport { pushForkSession } from '@proton/shared/lib/api/auth';\n\nimport TVCodeInputs from './TVCodeInputs';\n\nenum STEP {\n    ENTER_CODE,\n    DEVICE_CONNECTED,\n}\n\nconst TVContainer = () => {\n    const [code, setCode] = useState('');\n    const [step, setStep] = useState(STEP.ENTER_CODE);\n    const api = useApi();\n    const [loading, withLoading] = useLoading();\n    const [error, setError] = useState('');\n\n    const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {\n        event.preventDefault();\n\n        if (loading || !code) {\n            return;\n        }\n\n        try {\n            setError('');\n            await api(\n                pushForkSession({\n                    ChildClientID: 'android_tv-vpn',\n                    Independent: 1,\n                    UserCode: code,\n                })\n            );\n            setStep(STEP.DEVICE_CONNECTED);\n        } catch (error: any) {\n            const { data: { Error = '' } = {} } = error;\n            setError(Error);\n            throw error;\n        }\n    };\n\n    const render = () => {\n        if (step === STEP.ENTER_CODE) {\n            return (\n                <form onSubmit={(event) => withLoading(handleSubmit(event))}>\n                    <label className=\"h3 text-center\" htmlFor=\"code-input\">{c('Label')\n                        .t`Enter the code displayed on your TV`}</label>\n                    <TVCodeInputs value={code} setValue={setCode} />\n                    {error ? (\n                        <>\n                            <p className=\"mt-8 mb-0 pl-4 text-center color-danger\">{c('Error')\n                                .t`Code wrong or not valid anymore`}</p>\n                            <p className=\"m-0 text-center border-none\">{c('Error')\n                                .t`If the time on your TV has expired, click on Refresh on your TV and enter your code again.`}</p>\n                        </>\n                    ) : null}\n                    <div className=\"flex\">\n                        <PrimaryButton\n                            loading={loading}\n                            type=\"submit\"\n                            pill\n                            className=\"text-uppercase text-bold mt-8 mb-6 mx-auto\"\n                        >\n                            <span className=\"p-2 inline-flex\">\n                                {error ? c('Action').t`Verify code again` : c('Action').t`Verify code`}\n                            </span>\n                        </PrimaryButton>\n                    </div>\n                </form>\n            );\n        }\n\n        if (step === STEP.DEVICE_CONNECTED) {\n            return (\n                <>\n                    <h2>{c('Title').t`Device connected!`}</h2>\n                    <div className=\"flex justify-center my-8\">\n                        <span className=\"inline-flex bg-success rounded-50 p-7\">\n                            <Icon name=\"checkmark\" size={15} />\n                        </span>\n                    </div>\n                </>\n            );\n        }\n\n        return null;\n    };\n\n    return (\n        <div className=\"ui-prominent background-container h-full flex *:min-size-auto flex-column flex-nowrap items-center overflow-auto\">\n            <div className=\"flex justify-center items-center pt-7\">\n                <div className=\"w-custom\" style={{ '--w-custom': '9.375rem' }}>\n                    <Href href=\"https://protonvpn.com\" target=\"_self\">\n                        <VpnLogo />\n                    </Href>\n                </div>\n                <h3 className=\"mb-0 pl-1 text-uppercase text-bold\">{c('Title').t`TV sign in`}</h3>\n            </div>\n            <div className=\"flex flex-column flex-1 flex-nowrap shrink-0\">\n                <div className=\"m-auto p-7 shrink-0 max-w-custom\" style={{ '--max-w-custom': '30em' }}>\n                    {render()}\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default TVContainer;\n","import { useState } from 'react';\n\nimport markdownit from 'markdown-it';\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport { getAppVersion } from '../../helpers';\nimport {\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n} from '../modalTwo';\n\nimport './ChangeLogModal.scss';\n\nconst md = markdownit('default', {\n    breaks: true,\n    linkify: true,\n});\n\nconst defaultRender =\n    md.renderer.rules.link_open ||\n    function render(tokens, idx, options, env, self) {\n        return self.renderToken(tokens, idx, options);\n    };\n\nmd.renderer.rules.link_open = (tokens, idx, options, env, self) => {\n    tokens[idx].attrPush(['target', '_blank']);\n    return defaultRender(tokens, idx, options, env, self);\n};\n\ninterface Props extends ModalProps {\n    changelog?: string;\n}\n\nconst ChangelogModal = ({ changelog = '', ...rest }: Props) => {\n    const [html] = useState(() => {\n        const modifiedChangelog = changelog.replace(/\\[(\\d+\\.\\d+\\.\\d+[^\\]]*)]/g, (match, capture) => {\n            return `[${getAppVersion(capture)}]`;\n        });\n        return {\n            __html: md.render(modifiedChangelog),\n        };\n    });\n\n    return (\n        <Modal size=\"large\" data-testid=\"changelog-modal\" {...rest}>\n            <ModalHeader title={c('Title').t`What's new`} />\n            <ModalContent>\n                <div className=\"modal-content-inner-changelog\" dangerouslySetInnerHTML={html} dir=\"ltr\" lang=\"en\" />\n            </ModalContent>\n            <ModalFooter>\n                <Button data-testid=\"changelog-modal:close\" onClick={rest.onClose}>{c('Action').t`Close`}</Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ChangelogModal;\n","import { c } from 'ttag';\n\nimport { TelemetryChangelog, TelemetryMeasurementGroups } from '@proton/shared/lib/api/telemetry';\nimport { APPS_CONFIGURATION } from '@proton/shared/lib/constants';\nimport { sendTelemetryReport } from '@proton/shared/lib/helpers/metrics';\n\nimport { getAppVersion } from '../../helpers';\nimport { useApi, useConfig, useEarlyAccess } from '../../hooks';\nimport { useModalState } from '../modalTwo';\nimport { Tooltip } from '../tooltip';\nimport ChangelogModal from './ChangelogModal';\n\ninterface Props {\n    appName?: string;\n    appVersion?: string;\n    changelog?: string;\n}\n\nconst envMap = {\n    alpha: 'α',\n    beta: 'β',\n    relaunch: 'δ',\n};\n\nconst AppVersion = ({ appVersion: maybeAppVersion, appName: maybeAppName, changelog }: Props) => {\n    const api = useApi();\n    const { APP_NAME, APP_VERSION, DATE_VERSION } = useConfig();\n    const { currentEnvironment } = useEarlyAccess();\n    const [changelogModal, setChangelogModalOpen, render] = useModalState();\n\n    const appName = maybeAppName || APPS_CONFIGURATION[APP_NAME]?.name;\n    const appVersion = getAppVersion(maybeAppVersion || APP_VERSION);\n    const className = 'app-infos-version text-xs m-0';\n    const title = DATE_VERSION;\n    const children = (\n        <>\n            <span className=\"app-infos-name mr-1\">{appName}</span>\n            <span className=\"app-infos-number\" data-testid=\"app-infos:release-notes\">\n                {appVersion}\n                {currentEnvironment && envMap[currentEnvironment] && ` ${envMap[currentEnvironment]}`}\n            </span>\n        </>\n    );\n\n    if (!changelog) {\n        return (\n            <span title={title} className={className}>\n                {children}\n            </span>\n        );\n    }\n\n    const handleOpenChangelog = () => {\n        setChangelogModalOpen(true);\